export const EXAMPLE_SOURCES: readonly { file: string; source: string }[] = [
 {
  "file": "ai_before_after.storelib",
  "source": "{# example\ntitle: Before and after slider\nsummary: Two of the creator's own photos on top of each other with a real range input as the handle, so it works by mouse, touch and arrow keys; a tiny sandboxed script moves the split, and without it the slider still shows both halves at the middle.\ntags: before after, comparison, slider, range, image compare, renovation, results, script\n#}\n<template>\n<section class=\"ba\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <h2 class=\"ba__h\">{{ settings.heading }}</h2>\n  {% if settings.before and settings.after %}\n  <figure class=\"ba__fig\" style=\"--pos: {{ settings.start }}%;\">\n    <img class=\"ba__img\" src=\"{{ settings.after | asset }}\" alt=\"{{ settings.after_alt }}\" width=\"1600\" height=\"1000\">\n    <img class=\"ba__img ba__img--before\" src=\"{{ settings.before | asset }}\" alt=\"{{ settings.before_alt }}\" width=\"1600\" height=\"1000\">\n    <span class=\"ba__line\" aria-hidden=\"true\"></span>\n    <input class=\"ba__range\" type=\"range\" min=\"0\" max=\"100\" value=\"{{ settings.start }}\" aria-label=\"{{ settings.handle_label }}\">\n    <figcaption class=\"ba__cap\"><span>{{ settings.before_label }}</span><span>{{ settings.after_label }}</span></figcaption>\n  </figure>\n  {% elsif page.in_editor %}\n  <p class=\"ba__empty\">Pick a before and an after photo in the sidebar. The slider shows only when both are set.</p>\n  {% endif %}\n</section>\n</template>\n\n<style scoped>\n.ba { padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ba__h { margin: 0 0 24px; max-width: 20ch; font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1.2rem + 2.4vw, 3.25rem); line-height: 1; letter-spacing: -0.02em; font-weight: 500; color: var(--s-heading); }\n.ba__fig { position: relative; margin: 0; overflow: hidden; }\n.ba__img { display: block; width: 100%; height: auto; aspect-ratio: 16 / 10; object-fit: cover; }\n.ba__img--before { position: absolute; inset: 0; height: 100%; clip-path: inset(0 calc(100% - var(--pos, 50%)) 0 0); }\n.ba__line { position: absolute; top: 0; bottom: 0; left: var(--pos, 50%); width: 2px; margin-left: -1px; background: var(--s-bg); pointer-events: none; }\n.ba__range { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: ew-resize; }\n.ba__range:focus-visible + .ba__cap { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n.ba__cap { display: flex; justify-content: space-between; padding-top: 10px; font-size: 0.9375rem; font-weight: 500; }\n.ba__empty { opacity: 0.7; }\n</style>\n\n<script>\n/* The range is real, so keys and touch already move it; this only paints the split where it is. */\nconst fig = root.querySelector(\".ba__fig\")\nconst range = root.querySelector(\".ba__range\")\nif (fig && range) {\n  range.addEventListener(\"input\", function (e) {\n    const v = Math.max(0, Math.min(100, Number(e.target.value) || 0))\n    fig.style.setProperty(\"--pos\", v + \"%\")\n  })\n}\n</script>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_before_after\",\n  \"name\": \"Before and after\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"The kitchen on Alma Road\" },\n    { \"type\": \"image_picker\", \"id\": \"before\", \"label\": \"Before photo\" },\n    { \"type\": \"text\", \"id\": \"before_alt\", \"label\": \"Before photo description\", \"default\": \"\" },\n    { \"type\": \"image_picker\", \"id\": \"after\", \"label\": \"After photo\" },\n    { \"type\": \"text\", \"id\": \"after_alt\", \"label\": \"After photo description\", \"default\": \"\" },\n    { \"type\": \"text\", \"id\": \"before_label\", \"label\": \"Before label\", \"default\": \"Before\" },\n    { \"type\": \"text\", \"id\": \"after_label\", \"label\": \"After label\", \"default\": \"After\" },\n    { \"type\": \"text\", \"id\": \"handle_label\", \"label\": \"Slider name (read aloud)\", \"default\": \"Drag to compare before and after\" },\n    { \"type\": \"range\", \"id\": \"start\", \"label\": \"Starting point\", \"min\": 10, \"max\": 90, \"step\": 5, \"unit\": \"%\", \"default\": 50 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_counters.storelib",
  "source": "{# example\ntitle: Counters from real numbers\nsummary: Figures that count up as they scroll into view, with CSS only (@property and a view timeline); each number is one the creator typed in, the section draws nothing for a figure left empty, and the real value is always the text a screen reader and a search engine get.\ntags: counters, stats, numbers, count up, figures, facts, @property, view-timeline\n#}\n<template>\n<section class=\"ct\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  {% if settings.heading %}<h2 class=\"ct__h\">{{ settings.heading }}</h2>{% endif %}\n  <dl class=\"ct__list\">\n    {% for block in section.blocks %}\n      {% if block.settings.value != 0 %}\n      <div class=\"ct__item\" data-block-id=\"{{ block.id }}\">\n        <dt class=\"ct__label\">{{ block.settings.label }}</dt>\n        <dd class=\"ct__value\" style=\"--to: {{ block.settings.value | round }};\"><span class=\"ct__real\">{{ block.settings.value }}{{ block.settings.suffix }}</span><span class=\"ct__anim\" aria-hidden=\"true\">{{ block.settings.suffix }}</span></dd>\n      </div>\n      {% elsif page.in_editor %}\n      <p class=\"ct__empty\">A figure with no number, or 0, is not shown. Type a number you can stand behind.</p>\n      {% endif %}\n    {% endfor %}\n  </dl>\n</section>\n</template>\n\n<style scoped>\n@property --ct-n { syntax: \"<integer>\"; inherits: false; initial-value: 0; }\n.ct { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ct__h { margin: 0 0 28px; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.25rem); font-weight: 600; letter-spacing: -0.01em; line-height: 1.1; color: var(--s-heading, var(--s-text)); }\n.ct__list { display: grid; gap: 0; margin: 0; }\n.ct__item { display: flex; flex-direction: column-reverse; gap: 6px; padding: 20px 0; border-top: 1px solid var(--s-border); }\n.ct__label { font-size: 0.9375rem; line-height: 1.4; }\n.ct__value { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(3rem, 1.6rem + 6vw, 7.5rem); line-height: 0.9; letter-spacing: -0.04em; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--s-heading); }\n.ct__anim { display: none; }\n.ct__empty { opacity: 0.7; }\n@container (min-width: 760px) { .ct__list { grid-template-columns: repeat(auto-fit, minmax(min(220px, 100%), 1fr)); gap: 0 32px; } }\n/* Counting is an extra: where the browser can animate an integer on scroll and motion is welcome. The real text stays for assistive tech. */\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .ct__real { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }\n    .ct__anim { display: inline; counter-reset: ct var(--ct-n); animation: ct-count linear both; animation-timeline: view(); animation-range: entry 10% cover 45%; }\n    .ct__anim::before { content: counter(ct); }\n    @keyframes ct-count { from { --ct-n: 0; } to { --ct-n: var(--to); } }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_counters\",\n  \"name\": \"Figures\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"In numbers\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 64 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 64 }\n  ],\n  \"blocks\": [\n    { \"type\": \"figure\", \"name\": \"Figure\", \"limit\": 6, \"settings\": [\n      { \"type\": \"number\", \"id\": \"value\", \"label\": \"Number (a real one; empty hides it)\" },\n      { \"type\": \"text\", \"id\": \"suffix\", \"label\": \"After the number\", \"default\": \"\" },\n      { \"type\": \"text\", \"id\": \"label\", \"label\": \"What it counts\", \"default\": \"Loaves baked this week\" }\n    ] }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_cursor_tilt.storelib",
  "source": "{# example\ntitle: Cursor-aware tilt\nsummary: One showcase picture (a product, a cover, a piece of work) that tilts a few degrees toward the pointer, with nine CSS hover zones and :has() instead of a pointer-tracking script (a section script cannot read the pointer's position); only on a pointer that hovers, flat on touch and under reduced motion, tilt and on or off editable.\ntags: cursor, cursor aware, pointer, tilt, depth tilt, 3d, hover, showcase, product, cover, has, motion tier\n#}\n<template>\n<section class=\"tl\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-btn-bg: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px; --tl-max: {{ settings.tilt }}deg;\">\n  <div class=\"tl__in\">\n    <div class=\"tl__stage\">\n      <div class=\"tl__card\">\n        {% if settings.image %}<img class=\"tl__img\" src=\"{{ settings.image | asset }}\" alt=\"{{ settings.image_alt }}\" width=\"1200\" height=\"1200\" loading=\"lazy\">{% elsif page.in_editor %}<p class=\"tl__ph\">Pick the picture to show in the sidebar</p>{% endif %}\n      </div>\n      <div class=\"tl__zones\" aria-hidden=\"true\"><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span></div>\n    </div>\n    <div class=\"tl__copy\">\n      {% if settings.heading %}<h2 class=\"tl__h\">{{ settings.heading }}</h2>{% endif %}\n      {% if settings.text %}<p class=\"tl__text\">{{ settings.text }}</p>{% endif %}\n      {% if settings.cta_label and settings.cta_url %}<a class=\"tl__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n    </div>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.tl { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.tl__in { max-width: var(--theme-page-width, 1280px); margin: 0 auto; display: grid; gap: clamp(28px, 5vw, 72px); align-items: center; }\n.tl__stage { position: relative; perspective: 1000px; max-width: 560px; width: 100%; justify-self: center; }\n.tl__card { aspect-ratio: 1; overflow: hidden; background: color-mix(in srgb, var(--s-text) 8%, var(--s-bg)); --rx: 0; --ry: 0; }\n.tl__img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.tl__ph { display: grid; place-items: center; height: 100%; margin: 0; padding: 16px; text-align: center; opacity: 0.7; }\n.tl__zones { display: none; }\n.tl__h { margin: 0 0 14px; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.9rem, 1.2rem + 2.6vw, 3.6rem); line-height: 1; letter-spacing: -0.03em; font-weight: 700; color: var(--s-heading); }\n.tl__text { margin: 0; max-width: 44ch; font-size: 1.0625rem; line-height: 1.6; }\n.tl__cta { display: inline-flex; align-items: center; min-height: 48px; margin-top: 24px; padding: 0 24px; background: var(--s-btn-bg); color: var(--s-btn-text); text-decoration: none; font-weight: 600; border-radius: var(--t-radius-sm, 2px); }\n.tl__cta:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n@container (min-width: 820px) { .tl__in { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); } }\n/*\n  The tilt: nine invisible zones over the picture; the one under the pointer\n  sets which way it leans. Only on a pointer that hovers and when motion is\n  welcome; the zones are not even drawn otherwise, so touch gets the picture.\n*/\n@media (prefers-reduced-motion: no-preference) and (hover: hover) and (pointer: fine) {\n  .tl:not([data-motion=\"off\"]) .tl__zones { display: grid; grid-template: repeat(3, 1fr) / repeat(3, 1fr); position: absolute; inset: 0; }\n  .tl:not([data-motion=\"off\"]) .tl__card { transform: rotateX(calc(var(--rx) * var(--tl-max, 4deg))) rotateY(calc(var(--ry) * var(--tl-max, 4deg))); transition: transform calc(var(--t-motion-hover, 200ms) * 2) var(--t-motion-ease-ui, cubic-bezier(0.3, 0.7, 0.4, 1)); }\n  .tl__stage:has(.tl__z:nth-child(1):hover) .tl__card { --rx: 1; --ry: -1; }\n  .tl__stage:has(.tl__z:nth-child(2):hover) .tl__card { --rx: 1; --ry: 0; }\n  .tl__stage:has(.tl__z:nth-child(3):hover) .tl__card { --rx: 1; --ry: 1; }\n  .tl__stage:has(.tl__z:nth-child(4):hover) .tl__card { --rx: 0; --ry: -1; }\n  .tl__stage:has(.tl__z:nth-child(6):hover) .tl__card { --rx: 0; --ry: 1; }\n  .tl__stage:has(.tl__z:nth-child(7):hover) .tl__card { --rx: -1; --ry: -1; }\n  .tl__stage:has(.tl__z:nth-child(8):hover) .tl__card { --rx: -1; --ry: 0; }\n  .tl__stage:has(.tl__z:nth-child(9):hover) .tl__card { --rx: -1; --ry: 1; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_cursor_tilt\",\n  \"name\": \"Picture that leans toward you\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n    { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Picture description\", \"default\": \"\" },\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Dust Tapes, volume two\" },\n    { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Forty drum loops recorded on a four track in a garage in Margate.\" },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"Listen and buy\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button link\", \"default\": \"/about\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Leans toward the pointer\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"tilt\", \"label\": \"How far it leans\", \"min\": 0, \"max\": 10, \"step\": 1, \"unit\": \"deg\", \"default\": 4 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_faq_accordion.storelib",
  "source": "{# example\ntitle: Accordion FAQ\nsummary: Questions as details and summary, one open at a time through the name attribute, a smooth height change where the browser supports ::details-content, keyboard and screen reader behaviour from the browser itself.\ntags: faq, accordion, details, summary, questions, disclosure, expandable, syllabus\n#}\n<template>\n<section class=\"fq\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <div class=\"fq__in\">\n    <h2 class=\"fq__h\">{{ settings.heading }}</h2>\n    <div class=\"fq__list\">\n      {% for block in section.blocks %}\n        <details class=\"fq__item\" data-block-id=\"{{ block.id }}\"{% if settings.one_open %} name=\"fq-{{ section.id }}\"{% endif %}{% if forloop.first and settings.open_first %} open{% endif %}>\n          <summary class=\"fq__q\"><span>{{ block.settings.question }}</span><span class=\"fq__mark\" aria-hidden=\"true\"></span></summary>\n          <div class=\"fq__a\">{{ block.settings.answer }}</div>\n        </details>\n      {% else %}\n        {% if page.in_editor %}<p class=\"fq__empty\">Add questions in the sidebar</p>{% endif %}\n      {% endfor %}\n    </div>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.fq { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); interpolate-size: allow-keywords; }\n.fq__in { display: grid; gap: 24px; }\n.fq__h { margin: 0; font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1.2rem + 2.4vw, 3rem); line-height: 1; letter-spacing: -0.02em; font-weight: 500; color: var(--s-heading); }\n.fq__item { border-top: 1px solid var(--s-border); }\n.fq__item:last-child { border-bottom: 1px solid var(--s-border); }\n.fq__q { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 44px; padding: 18px 0; cursor: pointer; list-style: none; font-size: 1.0625rem; font-weight: 600; color: var(--s-heading); }\n.fq__q::-webkit-details-marker { display: none; }\n.fq__q::marker { content: \"\"; }\n.fq__q:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n.fq__mark { position: relative; flex: none; width: 14px; height: 14px; }\n.fq__mark::before, .fq__mark::after { content: \"\"; position: absolute; inset: 0; margin: auto; background: currentColor; }\n.fq__mark::before { width: 14px; height: 1.5px; }\n.fq__mark::after { width: 1.5px; height: 14px; transition: transform 180ms ease; }\n.fq__item[open] .fq__mark::after { transform: scaleY(0); }\n.fq__a { max-width: 62ch; padding: 0 0 20px; font-size: 1rem; line-height: 1.65; }\n.fq__empty { opacity: 0.7; }\n@container (min-width: 820px) { .fq__in { grid-template-columns: 5fr 7fr; gap: 48px; align-items: start; } .fq__h { position: sticky; top: 96px; } }\n@media (prefers-reduced-motion: no-preference) {\n  .fq__item::details-content { block-size: 0; overflow: clip; transition: block-size 260ms ease, content-visibility 260ms allow-discrete; }\n  .fq__item[open]::details-content { block-size: auto; }\n}\n@media (prefers-reduced-motion: reduce) { .fq__mark::after { transition: none; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_faq_accordion\",\n  \"name\": \"Questions\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Before your first class\" },\n    { \"type\": \"checkbox\", \"id\": \"one_open\", \"label\": \"One answer open at a time\", \"default\": true },\n    { \"type\": \"checkbox\", \"id\": \"open_first\", \"label\": \"Open the first answer\", \"default\": true },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"blocks\": [\n    { \"type\": \"question\", \"name\": \"Question\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"question\", \"label\": \"Question\", \"default\": \"What should I bring?\" },\n      { \"type\": \"textarea\", \"id\": \"answer\", \"label\": \"Answer\", \"default\": \"Write the answer people ask you for most.\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Questions\", \"blocks\": [{ \"type\": \"question\", \"settings\": { \"question\": \"What should I bring?\" } }, { \"type\": \"question\", \"settings\": { \"question\": \"Can I come as a complete beginner?\" } }, { \"type\": \"question\", \"settings\": { \"question\": \"How do I cancel a booking?\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_hover_lift.storelib",
  "source": "{# example\ntitle: Hover lift and press\nsummary: An index of offers or programmes whose rows answer the pointer: the picture lifts and pans inside its crop, the arrow travels, and a press settles the row, all timed by the site's motion feel (--t-motion-hover, --t-motion-lift); touch keeps the press only, reduced motion keeps colour and underline feedback without movement.\ntags: hover, hover lift, press, tactile, micro interaction, card hover, image pan, offers, programmes, index, links, motion tier\n#}\n<template>\n<section class=\"hl\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"hl__in\">\n    {% if settings.heading %}<h2 class=\"hl__h\">{{ settings.heading }}</h2>{% endif %}\n    <ul class=\"hl__list\">\n      {% for block in section.blocks %}\n      <li class=\"hl__row\" data-block-id=\"{{ block.id }}\">\n        <a class=\"hl__link\" href=\"{{ block.settings.url | url }}\">\n          <span class=\"hl__body\">\n            <span class=\"hl__title\">{{ block.settings.title }}</span>\n            {% if block.settings.text %}<span class=\"hl__text\">{{ block.settings.text }}</span>{% endif %}\n          </span>\n          {% if block.settings.meta %}<span class=\"hl__meta\">{{ block.settings.meta }}</span>{% endif %}\n          <span class=\"hl__arrow\" aria-hidden=\"true\">&rarr;</span>\n          {% if block.settings.image %}<span class=\"hl__crop\"><img class=\"hl__img\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"800\" height=\"1000\" loading=\"lazy\"></span>{% endif %}\n        </a>\n      </li>\n      {% else %}\n      {% if page.in_editor %}<li class=\"hl__row hl__empty\">Add offers in the sidebar</li>{% endif %}\n      {% endfor %}\n    </ul>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.hl { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.hl__in { max-width: var(--theme-page-width, 1280px); margin: 0 auto; }\n.hl__h { margin: 0 0 clamp(24px, 4vw, 48px); font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.9rem, 1.2rem + 2.8vw, 3.8rem); line-height: 1; letter-spacing: -0.03em; font-weight: 700; color: var(--s-heading); }\n.hl__list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--s-border); }\n.hl__row { border-bottom: 1px solid var(--s-border); }\n.hl__link { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px 20px; align-items: center; padding: 22px 0; min-height: 44px; color: inherit; text-decoration: none; }\n.hl__body { display: grid; gap: 6px; }\n.hl__title { font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.35rem, 1rem + 1.6vw, 2.3rem); line-height: 1.05; letter-spacing: -0.02em; font-weight: 700; color: var(--s-heading); text-decoration: underline; text-decoration-color: transparent; text-underline-offset: 6px; transition: text-decoration-color var(--t-motion-hover, 200ms) ease; }\n.hl__text { max-width: 54ch; font-size: 1rem; line-height: 1.55; }\n.hl__meta { font-size: 0.9375rem; font-variant-numeric: tabular-nums; white-space: nowrap; }\n.hl__arrow { display: none; }\n.hl__crop { grid-column: 1 / -1; display: block; overflow: hidden; aspect-ratio: 16 / 10; }\n.hl__img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.hl__link:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n.hl__link:hover .hl__title, .hl__link:focus-visible .hl__title { text-decoration-color: currentColor; }\n.hl__empty { padding: 24px 0; opacity: 0.7; }\n@container (min-width: 760px) {\n  .hl__link { grid-template-columns: minmax(0, 1fr) auto 32px 168px; padding: 26px 0; }\n  .hl__body { grid-column: 1; grid-row: 1; }\n  .hl__meta { grid-column: 2; grid-row: 1; }\n  .hl__arrow { display: block; grid-column: 3; grid-row: 1; font-size: 1.5rem; color: var(--s-accent); }\n  .hl__crop { grid-column: 4; grid-row: 1; aspect-ratio: 4 / 5; }\n}\n/* Movement only when welcome. The press works on touch too; the lift and pan only on a pointer that hovers. */\n@media (prefers-reduced-motion: no-preference) {\n  .hl:not([data-motion=\"off\"]) .hl__link { transition: transform var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, cubic-bezier(0.3, 0.7, 0.4, 1)); }\n  .hl:not([data-motion=\"off\"]) .hl__link:active { transform: scale(0.985); }\n  .hl:not([data-motion=\"off\"]) .hl__img, .hl:not([data-motion=\"off\"]) .hl__crop, .hl:not([data-motion=\"off\"]) .hl__arrow { transition: transform calc(var(--t-motion-hover, 200ms) * 1.6) var(--t-motion-ease-ui, cubic-bezier(0.3, 0.7, 0.4, 1)); }\n  @media (hover: hover) and (pointer: fine) {\n    .hl:not([data-motion=\"off\"]) .hl__link:hover .hl__crop { transform: translateY(calc(var(--t-motion-lift, 4px) * -1 * var(--m-k, 1))); }\n    .hl:not([data-motion=\"off\"]) .hl__link:hover .hl__img { transform: scale(calc(1 + (var(--t-motion-scale, 1.06) - 1) * var(--m-k, 1))); }\n    .hl:not([data-motion=\"off\"]) .hl__link:hover .hl__arrow { transform: translateX(calc(var(--t-motion-lift, 4px) * 2 * var(--m-k, 1))); }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_hover_lift\",\n  \"name\": \"Offers that answer the pointer\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Ways to train\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ],\n  \"blocks\": [\n    { \"type\": \"offer\", \"name\": \"Offer\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"One to one\" },\n      { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Twelve sessions in the studio, a plan between them.\" },\n      { \"type\": \"text\", \"id\": \"meta\", \"label\": \"Detail on the right\", \"default\": \"\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link\", \"default\": \"/about\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Picture description\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Offers that answer the pointer\", \"blocks\": [{ \"type\": \"offer\", \"settings\": { \"title\": \"One to one\", \"text\": \"Twelve sessions in the studio, a plan between them.\" } }, { \"type\": \"offer\", \"settings\": { \"title\": \"Small group\", \"text\": \"Four people, one coach, Tuesday and Thursday at 6.\" } }, { \"type\": \"offer\", \"settings\": { \"title\": \"Remote coaching\", \"text\": \"Your gym, a written plan, a video check in every Friday.\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_hover_reveal_list.storelib",
  "source": "{# example\ntitle: Index with hover image reveal\nsummary: A large text index of projects, artists or collections where the row you point at or focus shows its image, with :hover and :focus-within only; on phones each row shows a small thumbnail instead.\ntags: hover reveal, image reveal, index, project list, list, portfolio, artists, collections, :has\n#}\n<template>\n<section class=\"ix\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <h2 class=\"ix__h\">{{ settings.heading }}</h2>\n  <ul class=\"ix__list\">\n    {% for block in section.blocks %}\n      <li class=\"ix__row\" data-block-id=\"{{ block.id }}\">\n        <a class=\"ix__link\" href=\"{{ block.settings.url | url }}\">\n          <span class=\"ix__name\">{{ block.settings.name }}</span>\n          {% if block.settings.meta %}<span class=\"ix__meta\">{{ block.settings.meta }}</span>{% endif %}\n          {% if block.settings.image %}<img class=\"ix__img\" src=\"{{ block.settings.image | asset }}\" alt=\"\" width=\"640\" height=\"800\" loading=\"lazy\">{% endif %}\n        </a>\n      </li>\n    {% else %}\n      {% if page.in_editor %}<li class=\"ix__empty\">Add rows in the sidebar</li>{% endif %}\n    {% endfor %}\n  </ul>\n</section>\n</template>\n\n<style scoped>\n.ix { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ix__h { margin: 0 0 24px; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.25rem); font-weight: 600; letter-spacing: -0.01em; line-height: 1.1; color: var(--s-heading, var(--s-text)); }\n.ix__list { position: relative; list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--s-border); }\n.ix__row { border-bottom: 1px solid var(--s-border); }\n.ix__link { display: grid; grid-template-columns: minmax(0, 1fr) 64px; align-items: center; gap: 4px 16px; padding: 18px 0; color: inherit; text-decoration: none; }\n.ix__name { font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1rem + 4vw, 5rem); line-height: 1; letter-spacing: -0.03em; font-weight: 500; color: var(--s-heading); transition: color var(--t-motion-hover, 160ms) ease, transform var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease); }\n.ix__meta { grid-row: 2; font-size: 0.875rem; letter-spacing: 0.06em; }\n.ix__img { grid-row: 1 / span 2; grid-column: 2; width: 64px; height: 80px; object-fit: cover; }\n.ix__link:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n.ix__empty { padding: 24px 0; opacity: 0.7; }\n/* On a pointer that hovers, the picture leaves the row and floats beside the list. */\n@media (hover: hover) and (pointer: fine) {\n  @container (min-width: 820px) {\n    .ix__link { grid-template-columns: minmax(0, 1fr) auto; }\n    .ix__meta { grid-row: auto; }\n    .ix__img { position: absolute; right: 0; top: 50%; width: min(32%, 360px); height: auto; aspect-ratio: 4 / 5; opacity: 0; transform: translateY(-50%) scale(0.96); pointer-events: none; transition: opacity var(--t-motion-hover, 200ms) ease, transform calc(var(--t-motion-hover, 200ms) * 1.3) var(--t-motion-ease-ui, ease); }\n    .ix__row:hover .ix__img, .ix__row:focus-within .ix__img { opacity: 1; transform: translateY(-50%) scale(1); }\n    .ix__list:has(.ix__row:hover) .ix__name { color: color-mix(in srgb, var(--s-heading) 35%, transparent); }\n    .ix__list .ix__row:hover .ix__name, .ix__row:focus-within .ix__name { color: var(--s-heading); transform: translateX(12px); }\n  }\n}\n@media (prefers-reduced-motion: reduce) { .ix__img, .ix__name { transition: none; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_hover_reveal_list\",\n  \"name\": \"Index with pictures\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Selected work\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 64 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"blocks\": [\n    { \"type\": \"row\", \"name\": \"Row\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"name\", \"label\": \"Name\", \"default\": \"Harbour House\" },\n      { \"type\": \"text\", \"id\": \"meta\", \"label\": \"Details\", \"default\": \"Residential, 2025\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link\", \"default\": \"/about\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Index with pictures\", \"blocks\": [{ \"type\": \"row\", \"settings\": { \"name\": \"Harbour House\", \"meta\": \"Residential, 2025\" } }, { \"type\": \"row\", \"settings\": { \"name\": \"Mill Lane Studio\", \"meta\": \"Workplace, 2024\" } }, { \"type\": \"row\", \"settings\": { \"name\": \"The Granary\", \"meta\": \"Conversion, 2023\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_hscroll_gallery.storelib",
  "source": "{# example\ntitle: Horizontal scroll gallery\nsummary: A row of images that scrolls sideways with snap points, keyboard scrollable (the track takes focus, arrow keys move it), a progress line tied to the scroll with CSS, captions under each picture.\ntags: horizontal scroll, gallery, carousel, slider, scroll-snap, process, crate, images, scroll-timeline\n#}\n<template>\n<section class=\"hg\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <div class=\"hg__head\">\n    <h2 class=\"hg__h\">{{ settings.heading }}</h2>\n    {% if settings.hint %}<p class=\"hg__hint\">{{ settings.hint }}</p>{% endif %}\n  </div>\n  <div class=\"hg__track\" tabindex=\"0\" role=\"region\" aria-label=\"{{ settings.heading }}\">\n    {% for block in section.blocks %}\n      <figure class=\"hg__item\" data-block-id=\"{{ block.id }}\">\n        {% if block.settings.image %}<img class=\"hg__img\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"900\" height=\"1125\" loading=\"lazy\">{% elsif page.in_editor %}<div class=\"hg__ph\">Add a photo</div>{% endif %}\n        {% if block.settings.caption %}<figcaption class=\"hg__cap\">{{ block.settings.caption }}</figcaption>{% endif %}\n      </figure>\n    {% else %}\n      {% if page.in_editor %}<p class=\"hg__empty\">Add pictures in the sidebar</p>{% endif %}\n    {% endfor %}\n  </div>\n  <div class=\"hg__bar\" aria-hidden=\"true\"><span class=\"hg__fill\"></span></div>\n</section>\n</template>\n\n<style scoped>\n.hg { timeline-scope: --hg; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) 0 calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.hg__head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px 24px; padding-inline: var(--theme-padding-x, 16px); margin-bottom: 24px; }\n.hg__h { margin: 0; font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1.2rem + 2.4vw, 3.25rem); line-height: 1; letter-spacing: -0.02em; font-weight: 500; color: var(--s-heading); }\n.hg__hint { margin: 0; font-size: 0.9375rem; }\n.hg__track { display: grid; grid-auto-flow: column; grid-auto-columns: min(78%, 420px); gap: 12px; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x mandatory; scroll-padding-inline: var(--theme-padding-x, 16px); padding-inline: var(--theme-padding-x, 16px); scrollbar-width: none; scroll-timeline: --hg inline; }\n.hg__track::-webkit-scrollbar { display: none; }\n.hg__track:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n.hg__item { margin: 0; scroll-snap-align: start; }\n.hg__img, .hg__ph { display: block; width: 100%; height: auto; aspect-ratio: 4 / 5; object-fit: cover; }\n.hg__ph { display: grid; place-items: center; border: 1px dashed var(--s-border); }\n.hg__cap { margin-top: 10px; font-size: 0.875rem; line-height: 1.45; }\n.hg__empty { opacity: 0.7; }\n.hg__bar { height: 2px; margin: 24px var(--theme-padding-x, 16px) 0; background: var(--s-border); overflow: hidden; }\n.hg__fill { display: block; height: 100%; background: var(--s-accent); transform-origin: left; transform: scaleX(0.15); }\n@supports (animation-timeline: scroll()) {\n  .hg__fill { animation: hg-fill linear both; animation-timeline: --hg; }\n  @keyframes hg-fill { from { transform: scaleX(0.05); } to { transform: scaleX(1); } }\n}\n@media (prefers-reduced-motion: reduce) { .hg__track { scroll-snap-type: none; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_hscroll_gallery\",\n  \"name\": \"Sideways gallery\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"From clay to kiln\" },\n    { \"type\": \"text\", \"id\": \"hint\", \"label\": \"Hint\", \"default\": \"Scroll sideways\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ],\n  \"blocks\": [\n    { \"type\": \"picture\", \"name\": \"Picture\", \"settings\": [\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" },\n      { \"type\": \"text\", \"id\": \"caption\", \"label\": \"Caption\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Sideways gallery\", \"blocks\": [{ \"type\": \"picture\", \"settings\": { \"caption\": \"Wedging\" } }, { \"type\": \"picture\", \"settings\": { \"caption\": \"Throwing\" } }, { \"type\": \"picture\", \"settings\": { \"caption\": \"Glazing\" } }, { \"type\": \"picture\", \"settings\": { \"caption\": \"Firing\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_image_reveal.storelib",
  "source": "{# example\ntitle: Image curtain and scale-in\nsummary: One key photograph that opens like a curtain and settles from a slight scale as it scrolls into view, on a CSS view timeline (clip-path and transform only), sized by the site's motion feel; strength and curtain direction are editable, phones get the scale only, reduced motion gets the still photo.\ntags: image reveal, curtain, scale in, scale reveal, clip-path, photo, cinematic, scroll, view-timeline, motion tier, image curtain\n#}\n<template>\n<section class=\"ir ir--{{ settings.width }}\" data-motion=\"{{ settings.motion }}\" data-curtain=\"{{ settings.curtain }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px; --m-k: calc({{ settings.motion_strength }} / 100); --ir-ratio: {{ settings.ratio }};\">\n  <figure class=\"ir__fig\">\n    <div class=\"ir__frame\">\n      {% if settings.image %}<img class=\"ir__img\" src=\"{{ settings.image | asset }}\" alt=\"{{ settings.image_alt }}\" width=\"2400\" height=\"1600\" loading=\"lazy\">{% elsif page.in_editor %}<p class=\"ir__ph\">Pick the photo this section is for in the sidebar</p>{% endif %}\n    </div>\n    {% if settings.caption %}<figcaption class=\"ir__cap\">{{ settings.caption }}</figcaption>{% endif %}\n  </figure>\n</section>\n</template>\n\n<style scoped>\n.ir { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) 0 calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ir--inset .ir__fig { max-width: min(var(--theme-page-width, 1280px), 100%); padding-inline: var(--theme-padding-x, 16px); }\n.ir__fig { margin: 0 auto; }\n.ir__frame { position: relative; overflow: hidden; aspect-ratio: var(--ir-ratio, 16 / 9); background: color-mix(in srgb, var(--s-text) 8%, var(--s-bg)); }\n.ir__img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.ir__ph { display: grid; place-items: center; height: 100%; margin: 0; padding: 16px; text-align: center; opacity: 0.7; }\n.ir__cap { display: flex; justify-content: space-between; gap: 16px; padding: 12px var(--theme-padding-x, 16px) 0; font-size: 0.875rem; line-height: 1.45; }\n.ir--inset .ir__cap { padding-inline: 0; }\n/* The whole photo is the default. The curtain and the settle only run where the browser ties them to scroll and motion is welcome. */\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .ir:not([data-motion=\"off\"]) .ir__img { animation: ir-settle linear both; animation-timeline: view(); animation-range: entry 0% cover 45%; }\n    /* A phone gets the settle only: a curtain across a narrow photo hides its subject. */\n    @container (min-width: 601px) {\n      .ir:not([data-motion=\"off\"])[data-curtain=\"up\"] .ir__frame { animation: ir-up linear both; animation-timeline: view(); animation-range: entry 0% entry 90%; }\n      .ir:not([data-motion=\"off\"])[data-curtain=\"side\"] .ir__frame { animation: ir-side linear both; animation-timeline: view(); animation-range: entry 0% entry 90%; }\n    }\n    @keyframes ir-settle { from { transform: scale(calc(1 + (var(--t-motion-scale, 1.06) - 1) * var(--m-k, 1))); } to { transform: scale(1); } }\n    @keyframes ir-up { from { clip-path: inset(calc(28% * var(--m-k, 1)) 0 0 0); } to { clip-path: inset(0); } }\n    @keyframes ir-side { from { clip-path: inset(0 calc(18% * var(--m-k, 1))); } to { clip-path: inset(0); } }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_image_reveal\",\n  \"name\": \"Photo that opens\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n    { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" },\n    { \"type\": \"text\", \"id\": \"caption\", \"label\": \"Caption\", \"default\": \"\" },\n    { \"type\": \"select\", \"id\": \"width\", \"label\": \"Width\", \"default\": \"full\", \"options\": [{ \"label\": \"Edge to edge\", \"value\": \"full\" }, { \"label\": \"Inside the page\", \"value\": \"inset\" }] },\n    { \"type\": \"select\", \"id\": \"ratio\", \"label\": \"Shape\", \"default\": \"16 / 9\", \"options\": [{ \"label\": \"Wide\", \"value\": \"16 / 9\" }, { \"label\": \"Cinema\", \"value\": \"21 / 9\" }, { \"label\": \"Classic\", \"value\": \"3 / 2\" }, { \"label\": \"Tall\", \"value\": \"4 / 5\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"select\", \"id\": \"curtain\", \"label\": \"Opens\", \"default\": \"up\", \"options\": [{ \"label\": \"From below\", \"value\": \"up\" }, { \"label\": \"From the sides\", \"value\": \"side\" }, { \"label\": \"No curtain, settle only\", \"value\": \"none\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 48 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 48 }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_marquee.storelib",
  "source": "{# example\ntitle: Marquee of real words\nsummary: A slow running line of the creator's own words (dates, today's bakes, a release name), drawn twice so it loops seamlessly; pauses on hover and focus and with its own Pause switch (a checkbox and :has(), no script), stands still under reduced motion, and screen readers hear it once.\ntags: marquee, ticker, running text, loop, scrolling text, banner, motion, pause, marquee with pause\n#}\n<template>\n<section class=\"mq\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-accent: {{ scheme.accent }}; --mq-speed: {{ settings.speed }}s;\" aria-label=\"{{ settings.label }}\">\n  {% if section.blocks.size > 0 %}\n  <div class=\"mq__track\">\n    <ul class=\"mq__run\">\n      {% for block in section.blocks %}<li class=\"mq__item\" data-block-id=\"{{ block.id }}\">{{ block.settings.text }}</li>{% endfor %}\n    </ul>\n    <ul class=\"mq__run\" aria-hidden=\"true\">\n      {% for block in section.blocks %}<li class=\"mq__item\">{{ block.settings.text }}</li>{% endfor %}\n    </ul>\n  </div>\n  {% if settings.pause_label %}<label class=\"mq__pause\"><input class=\"mq__toggle\" type=\"checkbox\"><span>{{ settings.pause_label }}</span></label>{% endif %}\n  {% elsif page.in_editor %}\n  <p class=\"mq__empty\">Add lines in the sidebar</p>\n  {% endif %}\n</section>\n</template>\n\n<style scoped>\n.mq { position: relative; overflow: hidden; background: var(--s-bg); color: var(--s-text); border-block: 1px solid currentColor; }\n.mq__track { display: flex; width: max-content; }\n.mq__run { display: flex; flex: none; margin: 0; padding: 0; list-style: none; }\n.mq__item { padding: 14px 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.25rem, 0.9rem + 1.6vw, 2.25rem); line-height: 1; letter-spacing: -0.01em; text-transform: uppercase; white-space: nowrap; }\n.mq__item::after { content: \"/\"; margin-inline: 0.6em; color: var(--s-accent); }\n.mq__pause { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); display: none; align-items: center; gap: 6px; min-height: 44px; padding: 0 12px; background: var(--s-bg); color: var(--s-text); font-size: 0.8125rem; cursor: pointer; }\n.mq__toggle { width: 16px; height: 16px; margin: 0; accent-color: var(--s-accent); }\n.mq__pause:focus-within { outline: 2px solid var(--s-accent); outline-offset: -2px; }\n.mq__empty { margin: 0; padding: 16px; opacity: 0.7; }\n/* Without motion it is a line that wraps, so every word is still there. */\n@media (prefers-reduced-motion: reduce) {\n  .mq__track { width: auto; }\n  .mq__run { flex-wrap: wrap; padding-inline: 16px; }\n  .mq__run[aria-hidden=\"true\"] { display: none; }\n}\n@media (prefers-reduced-motion: no-preference) {\n  .mq__track { animation: mq-run var(--mq-speed, 40s) linear infinite; }\n  .mq:hover .mq__track, .mq:focus-within .mq__track, .mq:has(.mq__toggle:checked) .mq__track { animation-play-state: paused; }\n  .mq__pause { display: inline-flex; }\n  @keyframes mq-run { to { transform: translateX(-50%); } }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_marquee\",\n  \"name\": \"Running line\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"What it lists (read aloud)\", \"default\": \"Coming up\" },\n    { \"type\": \"text\", \"id\": \"pause_label\", \"label\": \"Pause switch (empty hides it)\", \"default\": \"Pause\" },\n    { \"type\": \"range\", \"id\": \"speed\", \"label\": \"Seconds per loop\", \"min\": 15, \"max\": 90, \"step\": 5, \"unit\": \"s\", \"default\": 40 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"line\", \"name\": \"Line\", \"settings\": [ { \"type\": \"text\", \"id\": \"text\", \"label\": \"Words\", \"default\": \"Friday 14 March, Leeds\" } ] }\n  ],\n  \"presets\": [{ \"name\": \"Running line\", \"blocks\": [{ \"type\": \"line\", \"settings\": { \"text\": \"Friday 14 March, Leeds\" } }, { \"type\": \"line\", \"settings\": { \"text\": \"Saturday 15 March, Glasgow\" } }, { \"type\": \"line\", \"settings\": { \"text\": \"Sunday 16 March, Belfast\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_mask_reveal.storelib",
  "source": "{# example\ntitle: Masked line reveal\nsummary: An opening statement whose lines rise out of clipped masks one after another, timed by the site's motion feel (--t-motion-*) with stagger and strength the creator edits; one real heading for screen readers, still under reduced motion, shorter travel on phones.\ntags: masked reveal, mask reveal, line reveal, text reveal, headline, hero, statement, stagger, motion, motion tier, opening\n#}\n<template>\n<section class=\"mr\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-btn-bg: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px; --m-k: calc({{ settings.motion_strength }} / 100); --mr-stagger: {{ settings.stagger }}ms;\">\n  <div class=\"mr__in mr__in--{{ settings.align }}\">\n    <h1 class=\"mr__h\">\n      {% for block in section.blocks %}<span class=\"mr__line\" data-block-id=\"{{ block.id }}\" style=\"--i: {{ forloop.index0 }};\"><span class=\"mr__words{% if block.settings.weight == 'light' %} mr__words--light{% endif %}\">{{ block.settings.line }}</span></span>{% endfor %}\n    </h1>\n    {% if settings.text %}<p class=\"mr__text\">{{ settings.text }}</p>{% endif %}\n    {% if settings.cta_label and settings.cta_url %}<a class=\"mr__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n  </div>\n</section>\n</template>\n\n<style scoped>\n.mr { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.mr__in { max-width: var(--theme-page-width, 1280px); margin: 0 auto; display: grid; gap: clamp(20px, 3vw, 36px); }\n.mr__in--right { justify-items: end; text-align: right; }\n.mr__h { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.6rem, 1rem + 7.2vw, 8.5rem); line-height: 0.92; letter-spacing: -0.035em; font-weight: 700; color: var(--s-heading); text-wrap: balance; }\n.mr__line { display: block; overflow: hidden; padding-bottom: 0.08em; margin-bottom: -0.08em; }\n.mr__words { display: inline-block; }\n.mr__words--light { font-weight: 400; color: color-mix(in srgb, var(--s-heading) 62%, var(--s-bg)); }\n.mr__text { margin: 0; max-width: 46ch; font-size: clamp(1.05rem, 0.95rem + 0.4vw, 1.25rem); line-height: 1.55; }\n.mr__cta { justify-self: start; display: inline-flex; align-items: center; min-height: 48px; padding: 0 24px; background: var(--s-btn-bg); color: var(--s-btn-text); text-decoration: none; font-weight: 600; border-radius: var(--t-radius-sm, 2px); transition: transform var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease-out); }\n.mr__in--right .mr__cta { justify-self: end; }\n.mr__cta:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n.mr__cta:active { transform: scale(0.98); }\n/* The still headline is the default. Motion only when welcome, and never when the creator set this section to still. */\n@media (prefers-reduced-motion: no-preference) {\n  .mr:not([data-motion=\"off\"]) .mr__words { animation: mr-rise var(--t-motion-duration, 650ms) var(--t-motion-ease, cubic-bezier(0.2, 0.7, 0.2, 1)) both; animation-delay: calc(var(--i) * var(--mr-stagger, 70ms) * var(--m-phone, 1) + 80ms); }\n  .mr:not([data-motion=\"off\"]) .mr__text, .mr:not([data-motion=\"off\"]) .mr__cta { animation: mr-fade var(--t-motion-duration, 650ms) var(--t-motion-ease, ease-out) both; animation-delay: calc(4 * var(--mr-stagger, 70ms) + 160ms); }\n  @keyframes mr-rise { from { transform: translateY(calc(108% * var(--m-k, 1) * var(--m-phone, 1))); } to { transform: none; } }\n  @keyframes mr-fade { from { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 0.5 * var(--m-k, 1))); } to { opacity: 1; transform: none; } }\n}\n/* On a phone the lines travel less and follow each other faster. */\n@container (max-width: 600px) {\n  .mr__in { --m-phone: 0.65; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_mask_reveal\",\n  \"name\": \"Masked headline\",\n  \"category\": \"hero\",\n  \"settings\": [\n    { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text under the headline\", \"default\": \"Strength sessions in a small room in Salford, built around the hours you actually have.\" },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"Book a first session\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button link\", \"default\": \"/about\" },\n    { \"type\": \"select\", \"id\": \"align\", \"label\": \"Alignment\", \"default\": \"left\", \"options\": [{ \"label\": \"Left\", \"value\": \"left\" }, { \"label\": \"Right\", \"value\": \"right\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"range\", \"id\": \"stagger\", \"label\": \"Delay between lines\", \"min\": 0, \"max\": 150, \"step\": 5, \"unit\": \"ms\", \"default\": 70 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 240, \"step\": 8, \"unit\": \"px\", \"default\": 120 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 240, \"step\": 8, \"unit\": \"px\", \"default\": 88 }\n  ],\n  \"blocks\": [\n    { \"type\": \"line\", \"name\": \"Line\", \"limit\": 5, \"settings\": [\n      { \"type\": \"text\", \"id\": \"line\", \"label\": \"Words on this line\", \"default\": \"Train with\" },\n      { \"type\": \"select\", \"id\": \"weight\", \"label\": \"Weight\", \"default\": \"bold\", \"options\": [{ \"label\": \"Bold\", \"value\": \"bold\" }, { \"label\": \"Light\", \"value\": \"light\" }] }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Masked headline\", \"blocks\": [{ \"type\": \"line\", \"settings\": { \"line\": \"Stronger in\" } }, { \"type\": \"line\", \"settings\": { \"line\": \"three hours\", \"weight\": \"light\" } }, { \"type\": \"line\", \"settings\": { \"line\": \"a week.\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_parallax_media.storelib",
  "source": "{# example\ntitle: Parallax image band\nsummary: A full bleed photo that drifts slower than the page as it passes, with a CSS view timeline on a transform only; a still photo without support or with reduced motion, and the caption is always plain text.\ntags: parallax, full bleed, image band, scroll, depth, photo, view-timeline\n#}\n<template>\n<section class=\"px\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --px-h: {{ settings.height }}svh; --px-shift: {{ settings.strength }}%;\">\n  <div class=\"px__frame\">\n    {% if settings.image %}<img class=\"px__img\" src=\"{{ settings.image | asset }}\" alt=\"{{ settings.image_alt }}\" width=\"2400\" height=\"1600\" loading=\"lazy\">{% elsif page.in_editor %}<p class=\"px__ph\">Pick a wide photo in the sidebar</p>{% endif %}\n  </div>\n  {% if settings.caption %}<p class=\"px__cap\">{{ settings.caption }}</p>{% endif %}\n</section>\n</template>\n\n<style scoped>\n.px { background: var(--s-bg); color: var(--s-text); }\n.px__frame { position: relative; height: var(--px-h, 70svh); min-height: 280px; overflow: hidden; }\n.px__img { position: absolute; inset: -12% 0; width: 100%; height: 124%; object-fit: cover; }\n.px__ph { display: grid; place-items: center; height: 100%; margin: 0; opacity: 0.7; }\n.px__cap { margin: 0; padding: 12px var(--theme-padding-x, 16px); font-size: 0.875rem; letter-spacing: 0.04em; }\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .px__img { animation: px-drift linear both; animation-timeline: view(); animation-range: cover; }\n    @keyframes px-drift { from { transform: translateY(calc(var(--px-shift, 10%) * -1)); } to { transform: translateY(var(--px-shift, 10%)); } }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_parallax_media\",\n  \"name\": \"Photo band\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n    { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" },\n    { \"type\": \"text\", \"id\": \"caption\", \"label\": \"Caption\", \"default\": \"The yard at first light\" },\n    { \"type\": \"range\", \"id\": \"height\", \"label\": \"Height\", \"min\": 40, \"max\": 100, \"step\": 5, \"unit\": \"%\", \"default\": 70 },\n    { \"type\": \"range\", \"id\": \"strength\", \"label\": \"Drift\", \"min\": 0, \"max\": 12, \"step\": 1, \"unit\": \"%\", \"default\": 8 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_scroll_reveal.storelib",
  "source": "{# example\ntitle: Scroll reveal chapters\nsummary: Chapters that fade and rise into place as they scroll into view, with CSS scroll-driven animation only, travelling as far as the site's motion feel says (--t-motion-distance) times the strength the creator sets; visible and still without support, with reduced motion or set to still.\ntags: scroll, reveal, fade, view-timeline, animation-timeline, chapters, story, motion, stagger, reveal on scroll, motion tier\n#}\n<template>\n<section class=\"rv\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--m-k: calc({{ settings.motion_strength }} / 100); --s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  {% if settings.heading %}<h2 class=\"rv__h\">{{ settings.heading }}</h2>{% endif %}\n  <ol class=\"rv__list\">\n    {% for block in section.blocks %}\n      <li class=\"rv__item\" data-block-id=\"{{ block.id }}\">\n        <span class=\"rv__num\">{{ forloop.index | prepend: '0' | slice: -2, 2 }}</span>\n        <div class=\"rv__body\">\n          <h3 class=\"rv__title\">{{ block.settings.title }}</h3>\n          {% if block.settings.text %}<div class=\"rv__text\">{{ block.settings.text }}</div>{% endif %}\n        </div>\n      </li>\n    {% else %}\n      {% if page.in_editor %}<li class=\"rv__empty\">Add chapters in the sidebar</li>{% endif %}\n    {% endfor %}\n  </ol>\n</section>\n</template>\n\n<style scoped>\n.rv { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 20px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.rv__h { margin: 0 0 clamp(32px, 6vw, 72px); max-width: 18ch; font-family: var(--theme-font-heading), serif; font-size: clamp(2rem, 1.4rem + 3vw, 4.2rem); line-height: 0.98; letter-spacing: -0.025em; font-weight: 500; color: var(--s-heading); }\n.rv__list { list-style: none; margin: 0; padding: 0; }\n.rv__item { display: grid; grid-template-columns: 3.5rem 1fr; gap: 16px; padding: 28px 0; border-top: 1px solid var(--s-border); }\n.rv__num { font-family: var(--theme-font-accent, var(--theme-font-body)), monospace; font-size: 0.8125rem; letter-spacing: 0.12em; color: var(--s-accent); font-variant-numeric: tabular-nums; }\n.rv__title { margin: 0 0 8px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.4rem, 1.1rem + 1.4vw, 2.2rem); line-height: 1.05; font-weight: 500; color: var(--s-heading); }\n.rv__text { max-width: 60ch; font-size: 1.0625rem; line-height: 1.6; }\n.rv__empty { padding: 24px 0; opacity: 0.7; }\n@container (max-width: 600px) { .rv__list { --m-phone: 0.6; } }\n@container (min-width: 760px) { .rv__item { grid-template-columns: 8rem minmax(0, 1fr); padding: 40px 0; } }\n/* Motion is an extra: only where the browser ties it to scroll, and only for people who have not asked for less. */\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .rv:not([data-motion=\"off\"]) .rv__item { animation: rv-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }\n    @keyframes rv-rise { from { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 1.3 * var(--m-k, 1) * var(--m-phone, 1))); } to { opacity: 1; transform: none; } }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_scroll_reveal\",\n  \"name\": \"Chapters that reveal\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"How a commission comes together\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Motion strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"blocks\": [\n    { \"type\": \"chapter\", \"name\": \"Chapter\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"A first conversation\" },\n      { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"What you need, where it will live, and when.\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Chapters that reveal\", \"blocks\": [{ \"type\": \"chapter\", \"settings\": { \"title\": \"A first conversation\", \"text\": \"What you need, where it will live, and when.\" } }, { \"type\": \"chapter\", \"settings\": { \"title\": \"Sketches\", \"text\": \"Two or three directions on paper before anything is made.\" } }, { \"type\": \"chapter\", \"settings\": { \"title\": \"Making\", \"text\": \"The piece is made, with photos along the way.\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_site_footer.storelib",
  "source": "{# example\ntitle: Big type footer with sign up, menus and locale switches\nsummary: A free site's own footer: the name set huge, a newsletter sign up that joins the creator's Subscribers, two menu columns from the site's own menus, language and currency switches through the page's hooks (hidden when the site has one), and the year and policies line.\ntags: footer, newsletter, signup, subscribe, menus, locale, currency, language, big type, own chrome, site footer\n#}\n<template>\n<footer class=\"sf\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }};\">\n  <div class=\"sf__top\">\n    <form class=\"sf__form\" data-storelib-form=\"subscribe\">\n      <label class=\"sf__label\" for=\"{{ section.id }}-email\">{{ settings.signup_label }}</label>\n      <div class=\"sf__row\">\n        <input class=\"sf__input\" id=\"{{ section.id }}-email\" name=\"email\" type=\"email\" inputmode=\"email\" autocomplete=\"email\" maxlength=\"254\" placeholder=\"{{ settings.email_placeholder }}\" required>\n        <button class=\"sf__btn\" type=\"submit\">{{ settings.signup_button }}</button>\n      </div>\n      <p class=\"sf__done\" data-storelib-success hidden>{{ settings.signup_success }}</p>\n    </form>\n    <nav class=\"sf__cols\" aria-label=\"{{ settings.nav_label }}\">\n      {% if settings.menu_one.links.size > 0 %}<div class=\"sf__col\"><p class=\"sf__col-h\">{{ settings.menu_one.title }}</p><ul>{% for link in settings.menu_one.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul></div>{% endif %}\n      {% if settings.menu_two.links.size > 0 %}<div class=\"sf__col\"><p class=\"sf__col-h\">{{ settings.menu_two.title }}</p><ul>{% for link in settings.menu_two.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul></div>{% endif %}\n    </nav>\n  </div>\n  <div class=\"sf__prefs\">\n    <details class=\"sf__pick\" data-storelib-locale-list>\n      <summary class=\"sf__pick-btn\">{{ settings.language_label }}: <span data-storelib-locale-current></span></summary>\n      <div class=\"sf__menu\"><button class=\"sf__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n    </details>\n    <details class=\"sf__pick\" data-storelib-currency-list>\n      <summary class=\"sf__pick-btn\">{{ settings.currency_label }}: <span data-storelib-currency-current></span></summary>\n      <div class=\"sf__menu\"><button class=\"sf__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n    </details>\n  </div>\n  <p class=\"sf__name\" aria-hidden=\"true\">{{ shop.name | default: settings.brand }}</p>\n  <div class=\"sf__base\"><span>{{ settings.copyright }}</span>{% if settings.base_link_url and settings.base_link_label %}<a href=\"{{ settings.base_link_url | url }}\">{{ settings.base_link_label }}</a>{% endif %}</div>\n</footer>\n</template>\n\n<style scoped>\n.sf { container-type: inline-size; padding: clamp(48px, 8vw, 96px) var(--theme-padding-x, 16px) 20px; background: var(--s-bg); color: var(--s-text); overflow: hidden; }\n.sf__top { display: grid; gap: 40px; }\n.sf__label { display: block; margin-bottom: 12px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.5rem, 1.1rem + 1.8vw, 2.5rem); line-height: 1.05; letter-spacing: -0.02em; color: var(--s-heading); }\n.sf__row { display: flex; gap: 8px; max-width: 520px; }\n.sf__input { flex: 1; min-width: 0; min-height: 48px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; }\n.sf__btn { min-height: 48px; padding: 0 18px; border: 0; background: var(--s-btn); color: var(--s-btn-text); font: inherit; cursor: pointer; }\n.sf__done { margin: 10px 0 0; }\n.sf__cols { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }\n.sf__col-h { margin: 0 0 10px; font-size: 0.9375rem; font-weight: 600; color: inherit; }\n.sf__col ul { margin: 0; padding: 0; list-style: none; }\n.sf__col a { display: inline-block; padding: 6px 0; color: inherit; text-decoration: none; }\n.sf__col a:hover, .sf__col a:focus-visible { text-decoration: underline; text-underline-offset: 4px; }\n.sf__prefs { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 40px; }\n.sf__pick { position: relative; }\n.sf__pick-btn { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); cursor: pointer; list-style: none; font-size: 0.875rem; }\n.sf__pick-btn::-webkit-details-marker { display: none; }\n.sf__menu { position: absolute; bottom: calc(100% + 6px); left: 0; display: grid; min-width: 180px; padding: 6px; background: var(--s-bg); border: 1px solid var(--s-border); }\n.sf__opt { min-height: 44px; padding: 0 10px; border: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }\n.sf__opt[aria-current=\"true\"] { color: var(--s-accent); }\n.sf__name { margin: clamp(32px, 6vw, 72px) 0 0; font-family: var(--theme-font-heading), serif; font-size: clamp(3.5rem, 0.5rem + 15vw, 16rem); line-height: 0.8; letter-spacing: -0.05em; font-weight: 600; color: var(--s-heading); white-space: nowrap; }\n.sf__base { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; padding-top: 16px; margin-top: 16px; border-top: 1px solid var(--s-border); font-size: 0.8125rem; }\n.sf__base a { color: inherit; }\n.sf :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@container (min-width: 820px) { .sf__top { grid-template-columns: 7fr 5fr; align-items: start; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_site_footer\",\n  \"name\": \"Site footer\",\n  \"kind\": \"footer\",\n  \"enabled_on\": { \"groups\": [\"footer\"] },\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"signup_label\", \"label\": \"Sign up heading\", \"default\": \"A letter when the new pieces are out\" },\n    { \"type\": \"text\", \"id\": \"email_placeholder\", \"label\": \"Email hint\", \"default\": \"Email address\" },\n    { \"type\": \"text\", \"id\": \"signup_button\", \"label\": \"Sign up button\", \"default\": \"Sign up\" },\n    { \"type\": \"text\", \"id\": \"signup_success\", \"label\": \"After signing up\", \"default\": \"Thanks. Check your inbox.\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menus name (read aloud)\", \"default\": \"Footer\" },\n    { \"type\": \"link_list\", \"id\": \"menu_one\", \"label\": \"First menu\", \"default\": \"main-menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu_two\", \"label\": \"Second menu\", \"default\": \"footer\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency\", \"default\": \"Currency\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no shop name\", \"default\": \"Studio\" },\n    { \"type\": \"text\", \"id\": \"copyright\", \"label\": \"Bottom line\", \"default\": \"Made in Leeds\" },\n    { \"type\": \"text\", \"id\": \"base_link_label\", \"label\": \"Bottom link\", \"default\": \"Contact\" },\n    { \"type\": \"url\", \"id\": \"base_link_url\", \"label\": \"Bottom link goes to\", \"default\": \"/contact\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_site_header.storelib",
  "source": "{# example\ntitle: Site header with mega menu, own search and own cart drawer\nsummary: A free site's own header: logo from Theme settings, the Main menu with sub links as popover mega panels on wide screens, a full screen mobile menu popover, its own search window and its own cart drawer through the page's hooks (no built-in drawer), language and currency switches; Escape, light dismiss and keyboard come from the popover API.\ntags: header, navigation, mega menu, mobile menu, hamburger, cart drawer, search panel, popover, locale, currency, language, own chrome, site header\n#}\n<template>\n<header class=\"sh\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }};\">\n  <div class=\"sh__bar\">\n    <a class=\"sh__logo\" href=\"{{ routes.root_url }}\">{% if theme.logo.url %}<img src=\"{{ theme.logo.url }}\" alt=\"{{ shop.name }}\" width=\"{{ settings.logo_width }}\" height=\"40\">{% else %}{{ shop.name | default: settings.brand }}{% endif %}</a>\n\n    <nav class=\"sh__nav\" aria-label=\"{{ settings.nav_label }}\">\n      <ul class=\"sh__links\">\n        {% for link in settings.menu.links %}\n          <li class=\"sh__li\">\n            {% if link.links.size > 0 %}\n              <button class=\"sh__top\" type=\"button\" popovertarget=\"mm-{{ section.id }}-{{ forloop.index }}\">{{ link.title }}</button>\n              <div class=\"sh__mega\" id=\"mm-{{ section.id }}-{{ forloop.index }}\" popover>\n                <a class=\"sh__mega-all\" href=\"{{ link.url }}\">{{ link.title }}</a>\n                <ul class=\"sh__mega-list\">\n                  {% for child in link.links %}<li><a class=\"sh__mega-link\" href=\"{{ child.url }}\">{{ child.title }}</a></li>{% endfor %}\n                </ul>\n              </div>\n            {% else %}\n              <a class=\"sh__top\" href=\"{{ link.url }}\">{{ link.title }}</a>\n            {% endif %}\n          </li>\n        {% endfor %}\n      </ul>\n    </nav>\n\n    <div class=\"sh__tools\">\n      <a class=\"sh__tool\" href=\"{{ routes.search_url }}\" data-storelib-search>{{ settings.search_label }}</a>\n      <a class=\"sh__tool\" href=\"{{ routes.cart_url }}\" data-storelib-cart>{{ settings.cart_label }} <span class=\"sh__count\" data-storelib-cart-count></span></a>\n      <button class=\"sh__tool sh__burger\" type=\"button\" popovertarget=\"mob-{{ section.id }}\">{{ settings.menu_label }}</button>\n    </div>\n  </div>\n\n  <div class=\"sh__mobile\" id=\"mob-{{ section.id }}\" popover>\n    <button class=\"sh__close\" type=\"button\" popovertarget=\"mob-{{ section.id }}\" popovertargetaction=\"hide\">{{ settings.close_label }}</button>\n    <nav aria-label=\"{{ settings.nav_label }}\">\n      <ul class=\"sh__mlist\">\n        {% for link in settings.menu.links %}\n          <li>\n            <a class=\"sh__mlink\" href=\"{{ link.url }}\">{{ link.title }}</a>\n            {% if link.links.size > 0 %}<ul class=\"sh__msub\">{% for child in link.links %}<li><a href=\"{{ child.url }}\">{{ child.title }}</a></li>{% endfor %}</ul>{% endif %}\n          </li>\n        {% endfor %}\n      </ul>\n    </nav>\n    <div class=\"sh__prefs\">\n      <div class=\"sh__pref\" data-storelib-locale-list><span class=\"sh__pref-label\">{{ settings.language_label }}</span><button class=\"sh__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n      <div class=\"sh__pref\" data-storelib-currency-list><span class=\"sh__pref-label\">{{ settings.currency_label }}</span><button class=\"sh__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n    </div>\n  </div>\n\n  <div class=\"sh__search\" data-storelib-search-panel role=\"dialog\" aria-label=\"{{ settings.search_label }}\">\n    <div class=\"sh__search-in\">\n      <input class=\"sh__input\" type=\"search\" data-storelib-search-input placeholder=\"{{ settings.search_placeholder }}\" aria-label=\"{{ settings.search_label }}\">\n      <button class=\"sh__close\" type=\"button\" data-storelib-search-close>{{ settings.close_label }}</button>\n      <p class=\"sh__state\" data-storelib-search-loading hidden>{{ settings.loading_text }}</p>\n      <p class=\"sh__state\" data-storelib-search-empty hidden>{{ settings.no_results_text }}</p>\n      <ul class=\"sh__results\" data-storelib-search-results>\n        <li class=\"sh__result\" data-storelib-search-result hidden><a class=\"sh__result-link\" data-result-url><img data-result-image alt=\"\" width=\"56\" height=\"70\"><span data-result-title></span><span class=\"sh__result-price\" data-result-price></span></a></li>\n      </ul>\n    </div>\n  </div>\n\n  <aside class=\"sh__cart\" data-storelib-cart-panel aria-label=\"{{ settings.cart_label }}\">\n    <div class=\"sh__cart-head\"><p class=\"sh__cart-title\">{{ settings.cart_label }}</p><button class=\"sh__close\" type=\"button\" data-storelib-cart-close>{{ settings.close_label }}</button></div>\n    <p class=\"sh__state\" data-storelib-cart-empty>{{ settings.empty_text }}</p>\n    <ul class=\"sh__lines\" data-storelib-cart-lines>\n      <li class=\"sh__line\" data-storelib-cart-line hidden>\n        <img data-line-image alt=\"\" width=\"64\" height=\"80\">\n        <div class=\"sh__line-main\"><a data-line-url><span data-line-title></span></a><span class=\"sh__line-var\" data-line-variant></span>\n          <div class=\"sh__qty\"><button type=\"button\" data-line-dec aria-label=\"{{ settings.less_label }}\">-</button><span data-line-qty></span><button type=\"button\" data-line-inc aria-label=\"{{ settings.more_label }}\">+</button><button class=\"sh__remove\" type=\"button\" data-line-remove>{{ settings.remove_label }}</button></div>\n        </div>\n        <span data-line-price></span>\n      </li>\n    </ul>\n    <div class=\"sh__cart-foot\" data-storelib-cart-filled>\n      <p class=\"sh__sub\"><span>{{ settings.subtotal_label }}</span><span data-storelib-cart-subtotal></span></p>\n      <button class=\"sh__checkout\" type=\"button\" data-storelib-checkout>{{ settings.checkout_label }}</button>\n    </div>\n  </aside>\n</header>\n</template>\n\n<style scoped>\n.sh { position: relative; z-index: 20; background: var(--s-bg); color: var(--s-text); border-bottom: 1px solid var(--s-border); }\n.sh__bar { display: flex; align-items: center; gap: 16px; min-height: 64px; padding: 0 var(--theme-padding-x, 16px); }\n.sh__logo { margin-right: auto; font-family: var(--theme-font-heading), serif; font-size: 1.375rem; letter-spacing: -0.02em; color: var(--s-heading); text-decoration: none; }\n.sh__logo img { display: block; height: auto; max-height: 40px; width: auto; }\n.sh__nav { display: none; }\n.sh__links { display: flex; gap: 4px; margin: 0; padding: 0; list-style: none; }\n.sh__top { display: inline-flex; align-items: center; min-height: 44px; padding: 0 12px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: none; cursor: pointer; }\n.sh__top:hover, .sh__top:focus-visible { color: var(--s-accent); }\n.sh__mega { position: fixed; inset: 64px 0 auto; margin: 0; width: 100%; max-width: none; padding: 32px var(--theme-padding-x, 16px) 40px; border: 0; border-bottom: 1px solid var(--s-border); background: var(--s-bg); color: var(--s-text); }\n.sh__mega-all { display: inline-block; margin-bottom: 20px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.5rem, 1rem + 2vw, 2.5rem); letter-spacing: -0.02em; color: var(--s-heading); }\n.sh__mega-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(200px, 100%), 1fr)); gap: 8px 24px; margin: 0; padding: 0; list-style: none; }\n.sh__mega-link { display: block; padding: 8px 0; color: inherit; text-decoration: none; }\n.sh__tools { display: flex; align-items: center; gap: 4px; }\n.sh__tool { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 10px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.875rem; letter-spacing: 0.04em; text-transform: uppercase; text-decoration: none; cursor: pointer; }\n.sh__count[data-count=\"0\"] { display: none; }\n.sh__count { min-width: 1.5em; padding: 0 4px; background: var(--s-accent); color: var(--s-bg); text-align: center; font-variant-numeric: tabular-nums; }\n.sh__mobile { position: fixed; inset: 0; width: 100%; height: 100%; max-width: none; max-height: none; margin: 0; padding: 20px var(--theme-padding-x, 16px); border: 0; background: var(--s-bg); color: var(--s-text); overflow-y: auto; }\n.sh__close { display: inline-flex; align-items: center; min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.sh__mlist { margin: 32px 0; padding: 0; list-style: none; }\n.sh__mlink { display: block; padding: 10px 0; font-family: var(--theme-font-heading), serif; font-size: clamp(2rem, 1.4rem + 4vw, 3.5rem); line-height: 1; letter-spacing: -0.03em; color: var(--s-heading); text-decoration: none; }\n.sh__msub { margin: 0 0 12px; padding: 0; list-style: none; }\n.sh__msub a { display: block; padding: 8px 0; color: inherit; }\n.sh__prefs { display: grid; gap: 12px; padding-top: 20px; border-top: 1px solid var(--s-border); }\n.sh__pref { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }\n.sh__pref-label { font-size: 0.875rem; font-weight: 500; }\n.sh__opt { min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.sh__opt[aria-current=\"true\"] { border-color: currentColor; }\n.sh__search, .sh__cart { position: fixed; z-index: 30; background: var(--s-bg); color: var(--s-text); visibility: hidden; opacity: 0; transition: opacity 200ms ease, transform 280ms cubic-bezier(0.32, 0.72, 0, 1), visibility 0s linear 280ms; }\n.sh__search { inset: 0 0 auto; padding: 16px var(--theme-padding-x, 16px) 32px; border-bottom: 1px solid var(--s-border); transform: translateY(-16px); max-height: 100svh; overflow-y: auto; }\n.sh__search-in { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 12px; max-width: 960px; margin: 0 auto; }\n.sh__input { min-height: 52px; padding: 0 4px; border: 0; border-bottom: 2px solid currentColor; background: none; color: inherit; font: inherit; font-size: clamp(1.25rem, 1rem + 1.2vw, 2rem); }\n.sh__state { grid-column: 1 / -1; margin: 0; }\n.sh__results { grid-column: 1 / -1; margin: 0; padding: 0; list-style: none; }\n.sh__result-link { display: grid; grid-template-columns: 56px minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 10px 0; color: inherit; text-decoration: none; border-bottom: 1px solid var(--s-border); }\n.sh__result-link img { width: 56px; height: 70px; object-fit: cover; }\n.sh__cart { inset: 0 0 0 auto; display: flex; flex-direction: column; width: min(420px, 100%); padding: 16px 20px; border-left: 1px solid var(--s-border); transform: translateX(100%); }\n.sh__cart-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }\n.sh__cart-title { margin: 0; font-family: var(--theme-font-heading), serif; font-size: 1.5rem; color: var(--s-heading); }\n.sh__lines { flex: 1; margin: 0; padding: 0; list-style: none; overflow-y: auto; }\n.sh__line { display: grid; grid-template-columns: 64px minmax(0, 1fr) auto; gap: 12px; padding: 14px 0; border-bottom: 1px solid var(--s-border); }\n.sh__line img { width: 64px; height: 80px; object-fit: cover; }\n.sh__line-main a { color: inherit; }\n.sh__line-var { display: block; font-size: 0.875rem; }\n.sh__qty { display: flex; align-items: center; gap: 6px; margin-top: 8px; }\n.sh__qty button { min-width: 44px; min-height: 44px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.sh__qty .sh__remove { min-width: 0; padding: 0 10px; border: 0; text-decoration: underline; }\n.sh__cart-foot { padding-top: 16px; }\n.sh__sub { display: flex; justify-content: space-between; margin: 0 0 12px; font-variant-numeric: tabular-nums; }\n.sh__checkout { width: 100%; min-height: 52px; border: 0; background: var(--s-btn); color: var(--s-btn-text); font: inherit; letter-spacing: 0.04em; cursor: pointer; }\n/* The page sets data-open on its own panels (search and cart) and toggles them with Escape and the close buttons. */\n.sh__search[data-open=\"true\"], .sh__cart[data-open=\"true\"] { visibility: visible; opacity: 1; transform: none; transition-delay: 0s; }\n.sh :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (min-width: 900px) {\n  .sh__nav { display: block; }\n  .sh__burger { display: none; }\n}\n@media (prefers-reduced-motion: reduce) { .sh__search, .sh__cart { transition: none; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_site_header\",\n  \"name\": \"Site header\",\n  \"kind\": \"header\",\n  \"enabled_on\": { \"groups\": [\"header\"] },\n  \"settings\": [\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"main-menu\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no logo or shop name\", \"default\": \"Home\" },\n    { \"type\": \"range\", \"id\": \"logo_width\", \"label\": \"Logo width\", \"min\": 60, \"max\": 240, \"step\": 4, \"unit\": \"px\", \"default\": 120 },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Main\" },\n    { \"type\": \"text\", \"id\": \"menu_label\", \"label\": \"Menu button\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"search_label\", \"label\": \"Search\", \"default\": \"Search\" },\n    { \"type\": \"text\", \"id\": \"search_placeholder\", \"label\": \"Search hint\", \"default\": \"Search the shop\" },\n    { \"type\": \"text\", \"id\": \"loading_text\", \"label\": \"While searching\", \"default\": \"Looking...\" },\n    { \"type\": \"text\", \"id\": \"no_results_text\", \"label\": \"No results\", \"default\": \"Nothing matches that yet.\" },\n    { \"type\": \"text\", \"id\": \"cart_label\", \"label\": \"Cart\", \"default\": \"Bag\" },\n    { \"type\": \"text\", \"id\": \"empty_text\", \"label\": \"Empty cart\", \"default\": \"Your bag is empty.\" },\n    { \"type\": \"text\", \"id\": \"subtotal_label\", \"label\": \"Subtotal\", \"default\": \"Subtotal\" },\n    { \"type\": \"text\", \"id\": \"checkout_label\", \"label\": \"Checkout button\", \"default\": \"Check out\" },\n    { \"type\": \"text\", \"id\": \"remove_label\", \"label\": \"Remove\", \"default\": \"Remove\" },\n    { \"type\": \"text\", \"id\": \"less_label\", \"label\": \"One less (read aloud)\", \"default\": \"One less\" },\n    { \"type\": \"text\", \"id\": \"more_label\", \"label\": \"One more (read aloud)\", \"default\": \"One more\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency\", \"default\": \"Currency\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_split_text.storelib",
  "source": "{# example\ntitle: Staggered headline\nsummary: A statement whose lines rise into place one after another, split by the creator's own line breaks (one line per block) so no script is needed; complete and still for reduced motion and for screen readers.\ntags: split text, staggered text, text reveal, headline, statement, hero, typography, stagger\n#}\n<template>\n<section class=\"sx\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--m-k: calc({{ settings.motion_strength }} / 100); --s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  {% if settings.label %}<p class=\"sx__label\">{{ settings.label }}</p>{% endif %}\n  <h1 class=\"sx__h sx__h--{{ settings.align }}\">\n    {% for block in section.blocks %}<span class=\"sx__line\" data-block-id=\"{{ block.id }}\" style=\"--d: {{ forloop.index0 }};\"><span class=\"sx__inner{% if block.settings.accent %} sx__inner--accent{% endif %}\">{{ block.settings.line }}</span></span>{% endfor %}\n  </h1>\n  {% if settings.cta_label and settings.cta_url %}<a class=\"sx__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n</section>\n</template>\n\n<style scoped>\n.sx { padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.sx__label { margin: 0 0 20px; font-size: 1rem; font-weight: 500; letter-spacing: 0; color: var(--s-text); }\n.sx__h { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.75rem, 1.2rem + 7.5vw, 9rem); line-height: 0.9; letter-spacing: -0.04em; font-weight: 600; color: var(--s-heading); }\n.sx__h--offset .sx__line:nth-child(even) { padding-left: 12%; }\n.sx__line { display: block; overflow: hidden; padding-bottom: 0.06em; }\n.sx__inner { display: inline-block; }\n.sx__inner--accent { color: var(--s-accent); }\n.sx__cta { display: inline-block; margin-top: clamp(24px, 4vw, 48px); padding: 14px 22px; background: var(--s-heading); color: var(--s-bg); text-decoration: none; border-radius: 2px; }\n.sx__cta:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n@media (prefers-reduced-motion: no-preference) {\n  .sx:not([data-motion=\"off\"]) .sx__inner { animation: sx-up var(--t-motion-duration, 700ms) var(--t-motion-ease, cubic-bezier(0.2, 0.7, 0, 1)) both; animation-delay: calc(var(--d) * var(--t-motion-stagger, 90ms) + 120ms); }\n  @keyframes sx-up { from { transform: translateY(calc(105% * var(--m-k, 1))); } to { transform: none; } }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_split_text\",\n  \"name\": \"Staggered headline\",\n  \"category\": \"hero\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"Small line above\", \"default\": \"Bakery, Hebden Bridge\" },\n    { \"type\": \"select\", \"id\": \"align\", \"label\": \"Lines\", \"default\": \"offset\", \"options\": [{ \"label\": \"Stepped\", \"value\": \"offset\" }, { \"label\": \"Flush left\", \"value\": \"left\" }] },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"See today's bakes\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button link\", \"default\": \"/about\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Motion strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 240, \"step\": 8, \"unit\": \"px\", \"default\": 112 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 240, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ],\n  \"blocks\": [\n    { \"type\": \"line\", \"name\": \"Line\", \"limit\": 6, \"settings\": [\n      { \"type\": \"text\", \"id\": \"line\", \"label\": \"Words on this line\", \"default\": \"Bread out\" },\n      { \"type\": \"checkbox\", \"id\": \"accent\", \"label\": \"Accent this line\", \"default\": false }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Staggered headline\", \"blocks\": [{ \"type\": \"line\", \"settings\": { \"line\": \"Bread out\" } }, { \"type\": \"line\", \"settings\": { \"line\": \"at seven,\", \"accent\": true } }, { \"type\": \"line\", \"settings\": { \"line\": \"gone by noon\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_sticky_stack.storelib",
  "source": "{# example\ntitle: Sticky stacked panels\nsummary: Panels that stick and stack on top of each other as the page scrolls, each a little lower than the last, with pure CSS position sticky; a plain list on phones that prefer less motion.\ntags: sticky, stacked cards, stack, scroll, panels, services, steps, layering\n#}\n<template>\n<section class=\"st\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <div class=\"st__head\">\n    {% if settings.label %}<p class=\"st__label\">{{ settings.label }}</p>{% endif %}\n    <h2 class=\"st__h\">{{ settings.heading }}</h2>\n  </div>\n  <ol class=\"st__stack\">\n    {% for block in section.blocks %}\n      <li class=\"st__panel\" data-block-id=\"{{ block.id }}\" style=\"--i: {{ forloop.index0 }};\">\n        <div class=\"st__copy\">\n          <span class=\"st__n\">{{ forloop.index }}</span>\n          <h3 class=\"st__title\">{{ block.settings.title }}</h3>\n          {% if block.settings.text %}<p class=\"st__text\">{{ block.settings.text }}</p>{% endif %}\n          {% if block.settings.link_url and block.settings.link_label %}<a class=\"st__link\" href=\"{{ block.settings.link_url | url }}\">{{ block.settings.link_label }}</a>{% endif %}\n        </div>\n        {% if block.settings.image %}<img class=\"st__img\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"800\" height=\"600\" loading=\"lazy\">{% endif %}\n      </li>\n    {% else %}\n      {% if page.in_editor %}<li class=\"st__empty\">Add panels in the sidebar</li>{% endif %}\n    {% endfor %}\n  </ol>\n</section>\n</template>\n\n<style scoped>\n.st { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.st__head { margin-bottom: clamp(24px, 5vw, 56px); }\n.st__label { margin: 0 0 10px; font-size: 1rem; font-weight: 500; letter-spacing: 0; color: var(--s-text); }\n.st__h { margin: 0; max-width: 16ch; font-family: var(--theme-font-heading), serif; font-size: clamp(2rem, 1.3rem + 3.4vw, 4.5rem); line-height: 0.95; letter-spacing: -0.03em; font-weight: 600; color: var(--s-heading); }\n.st__stack { list-style: none; margin: 0; padding: 0; display: grid; gap: 16px; }\n.st__panel { display: grid; gap: 20px; padding: clamp(20px, 4vw, 40px); background: var(--s-bg); border: 1px solid var(--s-border); border-radius: 4px; }\n.st__n { font-variant-numeric: tabular-nums; font-size: 0.875rem; letter-spacing: 0.1em; color: var(--s-accent); }\n.st__title { margin: 8px 0 10px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.5rem, 1.1rem + 1.8vw, 2.6rem); line-height: 1; letter-spacing: -0.02em; font-weight: 600; color: var(--s-heading); }\n.st__text { margin: 0; max-width: 52ch; font-size: 1.0625rem; line-height: 1.6; }\n.st__link { display: inline-block; margin-top: 16px; padding-block: 10px; color: inherit; text-underline-offset: 4px; }\n.st__img { width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; }\n.st__empty { opacity: 0.7; }\n@container (min-width: 760px) {\n  .st__panel { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: end; min-height: 60svh; }\n}\n/* The stack: each panel sticks a little lower than the one before. Only when motion is welcome and there is height for it. */\n@media (prefers-reduced-motion: no-preference) and (min-height: 560px) {\n  .st__panel { position: sticky; top: calc(72px + var(--i) * 18px); }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_sticky_stack\",\n  \"name\": \"Stacked panels\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"Small line above\", \"default\": \"What we do\" },\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Three ways to work together\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 120 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 160 }\n  ],\n  \"blocks\": [\n    { \"type\": \"panel\", \"name\": \"Panel\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"One to one\" },\n      { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Say what happens, how long it takes and who it suits.\" },\n      { \"type\": \"text\", \"id\": \"link_label\", \"label\": \"Link text\", \"default\": \"\" },\n      { \"type\": \"url\", \"id\": \"link_url\", \"label\": \"Link\", \"default\": \"\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Stacked panels\", \"blocks\": [{ \"type\": \"panel\", \"settings\": { \"title\": \"One to one\" } }, { \"type\": \"panel\", \"settings\": { \"title\": \"Small groups\" } }, { \"type\": \"panel\", \"settings\": { \"title\": \"Online plan\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_sticky_story.storelib",
  "source": "{# example\ntitle: Sticky storytelling\nsummary: A method told in two to five steps: on a wide screen the picture column stays while the steps pass beside it and each step's picture crossfades in on a named view timeline (position sticky plus timeline-scope, no script, no pinning by JavaScript); on phones, without support or with reduced motion it is plain sequential steps, each with its own picture.\ntags: sticky story, sticky storytelling, scrollytelling, sticky image, process, method, steps, how it works, crossfade, timeline-scope, view-timeline, motion tier\n#}\n<template>\n<section class=\"ss ss--{{ settings.layout }}\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <div class=\"ss__in\">\n    {% if settings.heading %}<h2 class=\"ss__h\">{{ settings.heading }}</h2>{% endif %}\n    <div class=\"ss__grid\">\n      <div class=\"ss__media\" aria-hidden=\"true\">\n        {% for block in section.blocks %}{% if block.settings.image %}<img class=\"ss__pic\" style=\"animation-timeline: --ss{{ forloop.index }};\" src=\"{{ block.settings.image | asset }}\" alt=\"\" width=\"1200\" height=\"1500\" loading=\"lazy\">{% endif %}{% endfor %}\n      </div>\n      <ol class=\"ss__steps\">\n        {% for block in section.blocks %}\n        <li class=\"ss__step\" data-block-id=\"{{ block.id }}\" style=\"view-timeline-name: --ss{{ forloop.index }};\">\n          <span class=\"ss__n\">{{ forloop.index }}</span>\n          <h3 class=\"ss__title\">{{ block.settings.title }}</h3>\n          {% if block.settings.text %}<p class=\"ss__text\">{{ block.settings.text }}</p>{% endif %}\n          {% if block.settings.image %}<img class=\"ss__inline\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"1200\" height=\"1500\" loading=\"lazy\">{% endif %}\n        </li>\n        {% else %}\n        {% if page.in_editor %}<li class=\"ss__step\">Add steps in the sidebar</li>{% endif %}\n        {% endfor %}\n      </ol>\n    </div>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.ss { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ss__in { max-width: var(--theme-page-width, 1280px); margin: 0 auto; }\n.ss__h { margin: 0 0 clamp(28px, 5vw, 64px); max-width: 20ch; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2rem, 1.2rem + 3.4vw, 4.4rem); line-height: 0.98; letter-spacing: -0.03em; font-weight: 700; color: var(--s-heading); }\n.ss__grid { display: block; }\n.ss__media { display: none; }\n.ss__steps { list-style: none; margin: 0; padding: 0; display: grid; gap: clamp(40px, 8vw, 72px); }\n.ss__n { display: block; font-size: 0.9375rem; font-variant-numeric: tabular-nums; color: var(--s-accent); }\n.ss__title { margin: 6px 0 10px; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.5rem); line-height: 1.02; letter-spacing: -0.02em; font-weight: 700; color: var(--s-heading); }\n.ss__text { margin: 0; max-width: 48ch; font-size: 1.0625rem; line-height: 1.6; }\n.ss__inline { display: block; width: 100%; height: auto; aspect-ratio: 4 / 5; object-fit: cover; margin-top: 20px; }\n/* Plain steps on a wider screen: words beside their own picture, never a picture the width of the page. */\n@container (min-width: 760px) {\n  .ss__step { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 4fr); grid-template-rows: auto auto 1fr; column-gap: clamp(24px, 4vw, 64px); align-items: start; }\n  .ss__n, .ss__title, .ss__text { grid-column: 1; }\n  .ss__inline { grid-column: 2; grid-row: 1 / span 3; margin-top: 0; }\n}\n/*\n  The story, only on a wide screen whose browser ties animation to a named\n  view timeline, and only when motion is welcome: the picture column sticks,\n  each step names a timeline, and its picture fades in while that step is in\n  the middle of the screen. Everywhere else the steps above are the layout.\n*/\n@supports (animation-timeline: view()) and (timeline-scope: none) {\n  @media (prefers-reduced-motion: no-preference) {\n    @container (min-width: 860px) {\n      .ss:not([data-motion=\"off\"]) .ss__in { timeline-scope: --ss1, --ss2, --ss3, --ss4, --ss5; }\n      .ss:not([data-motion=\"off\"]) .ss__grid { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); gap: clamp(32px, 5vw, 96px); align-items: start; }\n      .ss--media-right:not([data-motion=\"off\"]) .ss__media { order: 2; }\n      .ss:not([data-motion=\"off\"]) .ss__media { display: block; position: sticky; top: 12svh; max-height: 76svh; aspect-ratio: 4 / 5; overflow: hidden; }\n      .ss:not([data-motion=\"off\"]) .ss__pic { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0; animation: ss-show linear both; animation-range: cover 18% cover 82%; }\n      .ss:not([data-motion=\"off\"]) .ss__inline { display: none; }\n      .ss:not([data-motion=\"off\"]) .ss__step { min-height: 72svh; display: flex; flex-direction: column; justify-content: center; }\n      @keyframes ss-show { 0% { opacity: 0; transform: scale(calc(1 + (var(--t-motion-scale, 1.06) - 1) * 0.5)); } 20%, 80% { opacity: 1; transform: none; } 100% { opacity: 0; transform: none; } }\n    }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_sticky_story\",\n  \"name\": \"Method, step by step\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"How the twelve weeks run\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Picture stays while steps pass\", \"value\": \"site\" }, { \"label\": \"Plain steps\", \"value\": \"off\" }] },\n    { \"type\": \"select\", \"id\": \"layout\", \"label\": \"Picture side\", \"default\": \"media-left\", \"options\": [{ \"label\": \"Left\", \"value\": \"media-left\" }, { \"label\": \"Right\", \"value\": \"media-right\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"blocks\": [\n    { \"type\": \"step\", \"name\": \"Step\", \"limit\": 5, \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"An hour on the floor together\" },\n      { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"We test how you move and lift, and agree what the first month is for.\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Picture description\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Method, step by step\", \"blocks\": [{ \"type\": \"step\", \"settings\": { \"title\": \"An hour on the floor together\", \"text\": \"We test how you move and lift, and agree what the first month is for.\" } }, { \"type\": \"step\", \"settings\": { \"title\": \"A plan for the hours you have\", \"text\": \"Three sessions a week, written for your gym or your garage, in the app by Sunday night.\" } }, { \"type\": \"step\", \"settings\": { \"title\": \"A check in every Friday\", \"text\": \"Video of your top sets, a short call, and next week's numbers.\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_tabs.storelib",
  "source": "{# example\ntitle: Tabs without script\nsummary: Tabs built from a native radio group and :has(), so arrow keys move between them, the choice survives without script, and every panel is real text in the page; on a phone the tabs scroll sideways.\ntags: tabs, tab panel, switcher, timetable, menu sections, :has, radio, keyboard\n#}\n<template>\n<section class=\"tb\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <h2 class=\"tb__h\" id=\"tb-{{ section.id }}\">{{ settings.heading }}</h2>\n  {% if section.blocks.size > 0 %}\n  <div class=\"tb__tabs\" role=\"radiogroup\" aria-labelledby=\"tb-{{ section.id }}\">\n    {% for block in section.blocks %}\n      <label class=\"tb__tab\" data-block-id=\"{{ block.id }}\"><input class=\"tb__radio\" type=\"radio\" name=\"tb-{{ section.id }}\" value=\"{{ forloop.index }}\"{% if forloop.first %} checked{% endif %}><span>{{ block.settings.title }}</span></label>\n    {% endfor %}\n  </div>\n  <div class=\"tb__panels\">\n    {% for block in section.blocks %}\n      <div class=\"tb__panel tb__panel--{{ forloop.index }}\">\n        <h3 class=\"tb__ptitle\">{{ block.settings.title }}</h3>\n        <div class=\"tb__body\">{{ block.settings.body | raw }}</div>\n      </div>\n    {% endfor %}\n  </div>\n  {% elsif page.in_editor %}\n  <p class=\"tb__empty\">Add tabs in the sidebar</p>\n  {% endif %}\n</section>\n</template>\n\n<style scoped>\n.tb { padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.tb__h { margin: 0 0 20px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1.2rem + 2.4vw, 3.25rem); line-height: 1; letter-spacing: -0.02em; font-weight: 500; color: var(--s-heading); }\n.tb__tabs { display: flex; gap: 4px; overflow-x: auto; border-bottom: 1px solid var(--s-border); scrollbar-width: none; }\n.tb__tab { position: relative; flex: none; display: inline-flex; align-items: center; min-height: 44px; padding: 0 16px; cursor: pointer; font-size: 0.9375rem; letter-spacing: 0.02em; }\n.tb__radio { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; }\n.tb__tab:has(.tb__radio:checked) { color: var(--s-heading); box-shadow: inset 0 -2px 0 var(--s-accent); }\n.tb__tab:has(.tb__radio:focus-visible) { outline: 2px solid var(--s-accent); outline-offset: -2px; }\n.tb__panels { padding-top: 28px; }\n.tb__panel { display: none; max-width: 64ch; }\n.tb__ptitle { margin: 0 0 10px; font-size: 1.25rem; font-weight: 600; color: var(--s-heading); }\n.tb__body { font-size: 1.0625rem; line-height: 1.65; }\n.tb__empty { opacity: 0.7; }\n/* Up to eight tabs: the checked radio shows its panel. */\n.tb:has(.tb__radio[value=\"1\"]:checked) .tb__panel--1,\n.tb:has(.tb__radio[value=\"2\"]:checked) .tb__panel--2,\n.tb:has(.tb__radio[value=\"3\"]:checked) .tb__panel--3,\n.tb:has(.tb__radio[value=\"4\"]:checked) .tb__panel--4,\n.tb:has(.tb__radio[value=\"5\"]:checked) .tb__panel--5,\n.tb:has(.tb__radio[value=\"6\"]:checked) .tb__panel--6,\n.tb:has(.tb__radio[value=\"7\"]:checked) .tb__panel--7,\n.tb:has(.tb__radio[value=\"8\"]:checked) .tb__panel--8 { display: block; }\n/* A browser without :has() shows every panel, each under its own title: nothing is lost. */\n@supports not selector(:has(*)) { .tb__panel { display: block; margin-bottom: 24px; } .tb__tabs { display: none; } }\n@media (prefers-reduced-motion: no-preference) {\n  .tb__panel { animation: tb-in 200ms ease both; }\n  @keyframes tb-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_tabs\",\n  \"name\": \"Tabs\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"The week at the studio\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 72 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 72 }\n  ],\n  \"blocks\": [\n    { \"type\": \"tab\", \"name\": \"Tab\", \"limit\": 8, \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Tab name\", \"default\": \"Monday\" },\n      { \"type\": \"richtext\", \"id\": \"body\", \"label\": \"Content\", \"default\": \"<p>Write what happens on this day.</p>\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Tabs\", \"blocks\": [{ \"type\": \"tab\", \"settings\": { \"title\": \"Monday\" } }, { \"type\": \"tab\", \"settings\": { \"title\": \"Wednesday\" } }, { \"type\": \"tab\", \"settings\": { \"title\": \"Saturday\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_video_hero.storelib",
  "source": "{# example\ntitle: Video hero with a real pause\nsummary: An opening screen over the creator's own muted video with the browser's own controls (so it can always be paused), a poster for slow connections, a heading set large and off centre, one action; no autoplay for people who asked for less motion is left to the controls.\ntags: video hero, hero, video, background video, opening, cinematic, poster\n#}\n<template>\n<section class=\"vh\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }};\">\n  <div class=\"vh__media\">\n    {% if settings.video %}\n      <video class=\"vh__video\" src=\"{{ settings.video | asset }}\"{% if settings.poster %} poster=\"{{ settings.poster | asset }}\"{% endif %} muted loop playsinline preload=\"metadata\" controls{% if settings.autoplay %} autoplay{% endif %} aria-label=\"{{ settings.video_label }}\"></video>\n    {% elsif settings.poster %}\n      <img class=\"vh__video\" src=\"{{ settings.poster | asset }}\" alt=\"{{ settings.video_label }}\" width=\"1920\" height=\"1080\">\n    {% endif %}\n  </div>\n  <div class=\"vh__copy\">\n    {% if settings.label %}<p class=\"vh__label\">{{ settings.label }}</p>{% endif %}\n    <h1 class=\"vh__h\">{{ settings.heading }}</h1>\n    {% if settings.cta_label and settings.cta_url %}<a class=\"vh__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n  </div>\n</section>\n</template>\n\n<style scoped>\n.vh { position: relative; display: grid; min-height: 88svh; background: var(--s-bg); color: var(--s-text); }\n.vh__media { grid-area: 1 / 1; position: relative; overflow: hidden; }\n.vh__video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }\n.vh__copy { grid-area: 1 / 1; align-self: end; position: relative; z-index: 1; padding: 0 var(--theme-padding-x, 16px) clamp(64px, 10vw, 120px); max-width: 1100px; pointer-events: none; }\n.vh__copy a { pointer-events: auto; }\n.vh__label { margin: 0 0 14px; font-size: 1rem; font-weight: 500; letter-spacing: 0; color: var(--s-text); }\n.vh__h { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.75rem, 1.2rem + 7vw, 8.5rem); line-height: 0.88; letter-spacing: -0.035em; font-weight: 600; color: var(--s-heading); text-wrap: balance; }\n.vh__cta { display: inline-block; margin-top: 28px; padding: 14px 22px; background: var(--s-accent); color: var(--s-bg); text-decoration: none; }\n.vh__cta:focus-visible { outline: 2px solid var(--s-text); outline-offset: 3px; }\n@media (min-width: 900px) { .vh__copy { padding-left: 8vw; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_video_hero\",\n  \"name\": \"Video opening\",\n  \"category\": \"hero\",\n  \"settings\": [\n    { \"type\": \"video_picker\", \"id\": \"video\", \"label\": \"Video\" },\n    { \"type\": \"image_picker\", \"id\": \"poster\", \"label\": \"Still shown while it loads\" },\n    { \"type\": \"text\", \"id\": \"video_label\", \"label\": \"What the video shows\", \"default\": \"The crew rigging lights on set\" },\n    { \"type\": \"checkbox\", \"id\": \"autoplay\", \"label\": \"Play on its own (muted)\", \"default\": true },\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"Small line above\", \"default\": \"Production company, Glasgow\" },\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Short films for people who make things\" },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"See the reel\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button link\", \"default\": \"/about\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 }
]

/* The chrome kit, from ./examples/chrome (round P). */
export const CHROME_SOURCES: readonly { file: string; source: string }[] = [
 {
  "file": "ai_chrome_cart_card.storelib",
  "source": "{# example\ntitle: Floating card cart that drops from the bag\nsummary: Chrome kit cart drawer, a section placed after the header: the site's own cart panel as a compact card that drops from the top right corner under the header on wide screens and rises as a card above the bottom edge on phones, the page still visible around it. Small pictures, quantity steppers, a just added confirmation line, subtotal, checkout and keep shopping. Opened by every bag button and add to cart through the hooks; Escape and the close button shut it, keyboard kept inside. Corner, offset from the top, card width, radius, shadow and motion are settings.\ntags: chrome kit, cart drawer, floating cart, cart card, mini cart, dropdown cart, popover cart, added to cart, quick cart, own chrome\n#}\n<template>\n<div class=\"ccd\" data-corner=\"{{ settings.corner }}\" data-shadow=\"{{ settings.shadow }}\" data-motion=\"{{ settings.motion }}\" {% if page.in_editor and settings.editor_open %}data-editor-open{% endif %} data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --ccd-top: {{ settings.top_offset }}px; --ccd-w: {{ settings.width }}px; --ccd-r: {{ settings.radius }}px; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <aside class=\"ccd__card\" data-storelib-cart-panel aria-label=\"{{ settings.title }}\" role=\"dialog\">\n    <div class=\"ccd__head\">\n      <p class=\"ccd__title\">{{ settings.title }} <span class=\"ccd__n\" data-storelib-cart-count></span></p>\n      <button class=\"ccd__close\" type=\"button\" data-storelib-cart-close aria-label=\"{{ settings.close_label }}\"><span class=\"ccd__x\" aria-hidden=\"true\"></span></button>\n    </div>\n    <p class=\"ccd__empty\" data-storelib-cart-empty>{{ settings.empty_text }}</p>\n    <div data-storelib-cart-filled><p class=\"ccd__added\">{{ settings.added_text }}</p></div>\n    <ul class=\"ccd__lines\" data-storelib-cart-lines>\n      <li class=\"ccd__line\" data-storelib-cart-line hidden>\n        <img data-line-image alt=\"\" width=\"52\" height=\"52\">\n        <div class=\"ccd__info\">\n          <a class=\"ccd__name\" data-line-url><span data-line-title></span></a>\n          <span class=\"ccd__var\" data-line-variant></span>\n          <span class=\"ccd__qty\"><button type=\"button\" data-line-dec aria-label=\"{{ settings.less_label }}\">&minus;</button><span data-line-qty></span><button type=\"button\" data-line-inc aria-label=\"{{ settings.more_label }}\">+</button></span>\n        </div>\n        <div class=\"ccd__end\"><span data-line-price></span><button class=\"ccd__rm\" type=\"button\" data-line-remove aria-label=\"{{ settings.remove_label }}\"><span class=\"ccd__x ccd__x--s\" aria-hidden=\"true\"></span></button></div>\n      </li>\n    </ul>\n    <div class=\"ccd__foot\" data-storelib-cart-filled>\n      <p class=\"ccd__sub\"><span>{{ settings.subtotal_label }}</span><span data-storelib-cart-subtotal></span></p>\n      <div class=\"ccd__acts\">\n        <button class=\"ccd__ghost\" type=\"button\" data-storelib-cart-close>{{ settings.keep_label }}</button>\n        <button class=\"ccd__checkout\" type=\"button\" data-storelib-checkout>{{ settings.checkout_label }}</button>\n      </div>\n    </div>\n  </aside>\n</div>\n</template>\n\n<style scoped>\n.ccd, .ccd *, .ccd *::before, .ccd *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.ccd [hidden] { display: none !important; }\n.ccd__card { position: fixed; inset: auto 12px calc(12px + env(safe-area-inset-bottom, 0px)); z-index: 85; display: flex; flex-direction: column; gap: 12px; max-height: min(78svh, 640px); padding: 16px; overflow: hidden; border: 1px solid var(--s-border); border-radius: var(--ccd-r, 6px); background: var(--s-bg); color: var(--s-text); visibility: hidden; opacity: 0; }\n.ccd[data-shadow=\"true\"] .ccd__card { box-shadow: 0 18px 50px -12px rgba(0, 0, 0, 0.28); }\n.ccd__card[data-open=\"true\"], .ccd[data-editor-open] .ccd__card { visibility: visible; opacity: 1; transform: none; }\n.ccd[data-editor-open] .ccd__card { position: relative; inset: auto; margin: 24px auto; width: min(var(--ccd-w), 100%); }\n.ccd__head { display: flex; align-items: center; justify-content: space-between; }\n.ccd__title { margin: 0; color: var(--s-heading); font-weight: 700; font-size: 1.125rem; }\n.ccd__n { font-weight: 500; font-variant-numeric: tabular-nums; }\n.ccd__n[data-count=\"0\"] { display: none; }\n.ccd__close, .ccd__rm { display: inline-flex; align-items: center; justify-content: center; min-width: 44px; min-height: 44px; margin: -8px -8px -8px 0; border: 0; background: none; color: inherit; cursor: pointer; }\n.ccd__rm { margin: 0 -10px 0 0; }\n.ccd__x { position: relative; width: 16px; height: 16px; }\n.ccd__x--s { width: 12px; height: 12px; }\n.ccd__x::before, .ccd__x::after { content: \"\"; position: absolute; left: 0; right: 0; top: 50%; height: 1.5px; background: currentColor; transform: rotate(45deg); }\n.ccd__x::after { transform: rotate(-45deg); }\n.ccd__empty, .ccd__added { margin: 0; font-size: 0.9375rem; }\n.ccd__added::before { content: \"\"; display: inline-block; width: 8px; height: 8px; margin-right: 8px; background: var(--s-accent); vertical-align: 1px; }\n.ccd__lines { flex: 1; min-height: 0; margin: 0; padding: 0; overflow-y: auto; overscroll-behavior: contain; list-style: none; }\n.ccd__line { display: grid; grid-template-columns: 52px minmax(0, 1fr) auto; gap: 12px; padding: 10px 0; border-top: 1px solid var(--s-border); }\n.ccd__line img { width: 52px; height: 52px; object-fit: cover; border-radius: calc(var(--ccd-r, 6px) / 2); }\n.ccd__info { display: grid; gap: 2px; min-width: 0; font-size: 0.9375rem; }\n.ccd__name { color: inherit; font-weight: 600; text-decoration: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.ccd__var { font-size: 0.8125rem; }\n.ccd__qty { display: inline-flex; align-items: center; }\n.ccd__qty button { min-width: 44px; min-height: 36px; border: 0; background: none; color: inherit; font: inherit; cursor: pointer; }\n.ccd__qty button:first-child { margin-left: -14px; }\n.ccd__end { display: grid; justify-items: end; align-content: space-between; font-variant-numeric: tabular-nums; font-size: 0.9375rem; }\n.ccd__foot { display: grid; gap: 10px; padding-top: 12px; border-top: 1px solid var(--s-border); }\n.ccd__sub { display: flex; justify-content: space-between; margin: 0; font-weight: 600; font-variant-numeric: tabular-nums; }\n.ccd__acts { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr); gap: 8px; }\n.ccd__ghost, .ccd__checkout { min-height: 48px; padding: 0 12px; border: 1px solid var(--s-text); border-radius: calc(var(--ccd-r, 6px) / 1.5); background: none; color: inherit; font: inherit; font-weight: 600; cursor: pointer; }\n.ccd__checkout { border-color: var(--s-btn); background: var(--s-btn); color: var(--s-btn-text); }\n.ccd :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  .ccd:not([data-motion=\"off\"]) .ccd__card { transform: translateY(calc(16px * var(--m-k, 1))) scale(calc(1 - 0.03 * var(--m-k, 1))); transform-origin: 50% 100%; transition: opacity calc(var(--t-motion-hover, 200ms) * 1.2) ease, transform calc(var(--t-motion-duration, 650ms) * 0.6) cubic-bezier(0.32, 0.72, 0, 1), visibility 0s linear calc(var(--t-motion-duration, 650ms) * 0.6); }\n  .ccd:not([data-motion=\"off\"]) .ccd__card[data-open=\"true\"] { transition-delay: 0s; transform: none; }\n}\n@media (prefers-reduced-motion: reduce) { .ccd__card { transition: none; } }\n@media (min-width: 760px) {\n  .ccd__card { inset: var(--ccd-top, 76px) 20px auto auto; width: min(var(--ccd-w, 400px), calc(100% - 40px)); }\n  .ccd[data-corner=\"left\"] .ccd__card { inset: var(--ccd-top, 76px) auto auto 20px; }\n  .ccd:not([data-motion=\"off\"]) .ccd__card { transform-origin: 90% 0; transform: translateY(calc(-10px * var(--m-k, 1))) scale(calc(1 - 0.03 * var(--m-k, 1))); }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_cart_card\",\n  \"name\": \"Floating card cart\",\n  \"settings\": [\n    { \"type\": \"paragraph\", \"id\": \"about\", \"content\": \"Opens from every bag button and every add to cart on the page. Keep it right after the header.\" },\n    { \"type\": \"checkbox\", \"id\": \"editor_open\", \"label\": \"Keep it open in the editor\", \"default\": false },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"select\", \"id\": \"corner\", \"label\": \"Corner on wide screens\", \"default\": \"right\", \"options\": [{ \"label\": \"Top right\", \"value\": \"right\" }, { \"label\": \"Top left\", \"value\": \"left\" }] },\n    { \"type\": \"range\", \"id\": \"top_offset\", \"label\": \"Space from the top\", \"min\": 8, \"max\": 160, \"step\": 4, \"unit\": \"px\", \"default\": 76 },\n    { \"type\": \"range\", \"id\": \"width\", \"label\": \"Width\", \"min\": 320, \"max\": 480, \"step\": 10, \"unit\": \"px\", \"default\": 400 },\n    { \"type\": \"range\", \"id\": \"radius\", \"label\": \"Corners\", \"min\": 0, \"max\": 16, \"step\": 1, \"unit\": \"px\", \"default\": 6 },\n    { \"type\": \"checkbox\", \"id\": \"shadow\", \"label\": \"Shadow\", \"default\": true },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"Bag\" },\n    { \"type\": \"text\", \"id\": \"added_text\", \"label\": \"Line over the items\", \"default\": \"In your bag now\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close (read aloud)\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"empty_text\", \"label\": \"When it is empty\", \"default\": \"Your bag is empty.\" },\n    { \"type\": \"text\", \"id\": \"subtotal_label\", \"label\": \"Subtotal\", \"default\": \"Subtotal\" },\n    { \"type\": \"text\", \"id\": \"keep_label\", \"label\": \"Keep shopping button\", \"default\": \"Keep shopping\" },\n    { \"type\": \"text\", \"id\": \"checkout_label\", \"label\": \"Checkout button\", \"default\": \"Check out\" },\n    { \"type\": \"text\", \"id\": \"remove_label\", \"label\": \"Remove (read aloud)\", \"default\": \"Remove\" },\n    { \"type\": \"text\", \"id\": \"less_label\", \"label\": \"One less (read aloud)\", \"default\": \"One less\" },\n    { \"type\": \"text\", \"id\": \"more_label\", \"label\": \"One more (read aloud)\", \"default\": \"One more\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_cart_minimal.storelib",
  "source": "{# example\ntitle: Full height minimal cart, set in type\nsummary: Chrome kit cart drawer, a section placed after the header: the site's own cart panel as a full height column (the whole screen on a phone, a third or half of it on wide screens) with no boxes: lines as a numbered typographic list (title, option, quantity and price on one rule), the subtotal set large, one checkout button running the full width. Opened by every bag button and add to cart through the hooks; keyboard kept inside. Width, pictures on or off, the size of the total and motion are settings.\ntags: chrome kit, cart drawer, minimal cart, full height cart, typographic cart, editorial cart, luxury cart, checkout, own chrome\n#}\n<template>\n<div class=\"cmn\" data-pics=\"{{ settings.show_pictures }}\" data-width=\"{{ settings.width }}\" data-motion=\"{{ settings.motion }}\" {% if page.in_editor and settings.editor_open %}data-editor-open{% endif %} data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --cmn-total: {{ settings.total_size }}; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <aside class=\"cmn__panel\" data-storelib-cart-panel aria-label=\"{{ settings.title }}\">\n    <div class=\"cmn__col\" role=\"dialog\" aria-label=\"{{ settings.title }}\">\n      <div class=\"cmn__head\">\n        <h2 class=\"cmn__title\">{{ settings.title }}</h2>\n        <button class=\"cmn__close\" type=\"button\" data-storelib-cart-close>{{ settings.close_label }}</button>\n      </div>\n      <p class=\"cmn__empty\" data-storelib-cart-empty>{{ settings.empty_text }}</p>\n      <ol class=\"cmn__lines\" data-storelib-cart-lines>\n        <li class=\"cmn__line\" data-storelib-cart-line hidden>\n          <img class=\"cmn__img\" data-line-image alt=\"\" width=\"56\" height=\"70\">\n          <div class=\"cmn__main\">\n            <a class=\"cmn__name\" data-line-url><span data-line-title></span></a>\n            <span class=\"cmn__var\" data-line-variant></span>\n            <span class=\"cmn__ctl\"><button type=\"button\" data-line-dec aria-label=\"{{ settings.less_label }}\">&minus;</button><span class=\"cmn__q\" data-line-qty></span><button type=\"button\" data-line-inc aria-label=\"{{ settings.more_label }}\">+</button><button class=\"cmn__rm\" type=\"button\" data-line-remove>{{ settings.remove_label }}</button></span>\n          </div>\n          <span class=\"cmn__price\" data-line-price></span>\n        </li>\n      </ol>\n      <div class=\"cmn__foot\" data-storelib-cart-filled>\n        <p class=\"cmn__sub-l\">{{ settings.subtotal_label }}</p>\n        <p class=\"cmn__total\" data-storelib-cart-subtotal></p>\n        <p class=\"cmn__note\">{{ settings.note }}</p>\n        <button class=\"cmn__checkout\" type=\"button\" data-storelib-checkout>{{ settings.checkout_label }}</button>\n      </div>\n    </div>\n  </aside>\n</div>\n</template>\n\n<style scoped>\n.cmn, .cmn *, .cmn *::before, .cmn *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.cmn [hidden] { display: none !important; }\n.cmn__panel { position: fixed; inset: 0; z-index: 85; visibility: hidden; pointer-events: none; }\n.cmn__panel[data-open=\"true\"], .cmn[data-editor-open] .cmn__panel { visibility: visible; pointer-events: auto; }\n.cmn[data-editor-open] .cmn__panel { position: relative; min-height: 680px; }\n.cmn__col { position: absolute; inset: 0 0 0 auto; display: flex; flex-direction: column; width: 100%; padding: 0 var(--theme-padding-x, 16px) calc(20px + env(safe-area-inset-bottom, 0px)); overflow-y: auto; overscroll-behavior: contain; background: var(--s-bg); color: var(--s-text); border-left: 1px solid var(--s-border); opacity: 0; }\n.cmn__panel[data-open=\"true\"] .cmn__col, .cmn[data-editor-open] .cmn__col { opacity: 1; }\n.cmn__head { display: flex; align-items: center; justify-content: space-between; min-height: 72px; }\n.cmn__title { margin: 0; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.5rem, 1.2rem + 1.2vw, 2.25rem); font-weight: 700; letter-spacing: -0.03em; }\n.cmn__close { min-height: 44px; padding: 0; border: 0; background: none; color: inherit; font: inherit; text-decoration: underline; text-underline-offset: 4px; cursor: pointer; }\n.cmn__empty { margin: 24px 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.75rem, 1.3rem + 2vw, 3rem); line-height: 1.05; letter-spacing: -0.03em; color: var(--s-heading); }\n.cmn__lines { flex: 1; margin: 0; padding: 0; list-style: none; counter-reset: line; border-top: 1px solid var(--s-text); }\n.cmn__line { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 14px; align-items: start; padding: 16px 0; border-bottom: 1px solid var(--s-border); counter-increment: line; }\n.cmn__line::before { content: counter(line, decimal-leading-zero); font-size: 0.8125rem; font-variant-numeric: tabular-nums; padding-top: 4px; }\n.cmn__img { display: none; }\n.cmn[data-pics=\"true\"] .cmn__line { grid-template-columns: auto 56px minmax(0, 1fr) auto; }\n.cmn[data-pics=\"true\"] .cmn__img { display: block; width: 56px; height: 70px; object-fit: cover; }\n.cmn__main { display: grid; gap: 2px; min-width: 0; }\n.cmn__name { color: var(--s-heading); font-size: 1.125rem; font-weight: 600; text-decoration: none; }\n.cmn__var { font-size: 0.875rem; }\n.cmn__ctl { display: flex; flex-wrap: wrap; align-items: center; gap: 2px; margin-top: 4px; }\n.cmn__ctl button { min-width: 44px; min-height: 44px; padding: 0; border: 0; background: none; color: inherit; font: inherit; font-size: 1.125rem; cursor: pointer; }\n.cmn__ctl .cmn__rm { min-width: 0; margin-left: 8px; font-size: 0.875rem; text-decoration: underline; text-underline-offset: 3px; }\n.cmn__q { min-width: 20px; text-align: center; font-variant-numeric: tabular-nums; }\n.cmn__price { font-variant-numeric: tabular-nums; font-size: 1.0625rem; padding-top: 2px; }\n.cmn__foot { padding-top: 24px; }\n.cmn__sub-l { margin: 0; font-size: 0.9375rem; }\n.cmn__total { margin: 0 0 8px; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: calc(clamp(2.5rem, 1.6rem + 4vw, 4.5rem) * var(--cmn-total, 100) / 100); line-height: 1; letter-spacing: -0.04em; font-weight: 700; font-variant-numeric: tabular-nums; }\n.cmn__note { margin: 0 0 16px; font-size: 0.875rem; }\n.cmn__checkout { width: 100%; min-height: 56px; border: 0; background: var(--s-btn); color: var(--s-btn-text); font: inherit; font-size: 1.125rem; font-weight: 600; cursor: pointer; }\n.cmn :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  .cmn:not([data-motion=\"off\"]) .cmn__panel { transition: visibility 0s linear var(--t-motion-duration, 650ms); }\n  .cmn:not([data-motion=\"off\"]) .cmn__panel[data-open=\"true\"] { transition-delay: 0s; }\n  .cmn:not([data-motion=\"off\"]) .cmn__col { transform: translateY(calc(var(--t-motion-distance, 24px) * var(--m-k, 1))); transition: opacity calc(var(--t-motion-duration, 650ms) * 0.5) ease, transform calc(var(--t-motion-duration, 650ms) * 0.8) var(--t-motion-ease, ease-out); }\n  .cmn:not([data-motion=\"off\"]) .cmn__panel[data-open=\"true\"] .cmn__col { transform: none; }\n}\n@media (prefers-reduced-motion: reduce) { .cmn__panel, .cmn__col { transition: none; transform: none; } }\n@media (min-width: 760px) {\n  .cmn[data-width=\"third\"] .cmn__col { width: max(420px, 34%); }\n  .cmn[data-width=\"half\"] .cmn__col { width: 50%; }\n  .cmn__col { padding-left: 32px; padding-right: 32px; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_cart_minimal\",\n  \"name\": \"Minimal full height cart\",\n  \"settings\": [\n    { \"type\": \"paragraph\", \"id\": \"about\", \"content\": \"Opens from every bag button and every add to cart on the page. Keep it right after the header.\" },\n    { \"type\": \"checkbox\", \"id\": \"editor_open\", \"label\": \"Keep it open in the editor\", \"default\": false },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"select\", \"id\": \"width\", \"label\": \"Width on wide screens\", \"default\": \"third\", \"options\": [{ \"label\": \"A third\", \"value\": \"third\" }, { \"label\": \"Half\", \"value\": \"half\" }, { \"label\": \"The whole screen\", \"value\": \"full\" }] },\n    { \"type\": \"checkbox\", \"id\": \"show_pictures\", \"label\": \"Show pictures\", \"default\": false },\n    { \"type\": \"range\", \"id\": \"total_size\", \"label\": \"Total size\", \"min\": 50, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"Bag\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"empty_text\", \"label\": \"When it is empty\", \"default\": \"Your bag is empty.\" },\n    { \"type\": \"text\", \"id\": \"subtotal_label\", \"label\": \"Subtotal\", \"default\": \"Subtotal\" },\n    { \"type\": \"text\", \"id\": \"note\", \"label\": \"Line above checkout\", \"default\": \"Delivery and taxes at checkout.\" },\n    { \"type\": \"text\", \"id\": \"checkout_label\", \"label\": \"Checkout button\", \"default\": \"Check out\" },\n    { \"type\": \"text\", \"id\": \"remove_label\", \"label\": \"Remove\", \"default\": \"Remove\" },\n    { \"type\": \"text\", \"id\": \"less_label\", \"label\": \"One less (read aloud)\", \"default\": \"One less\" },\n    { \"type\": \"text\", \"id\": \"more_label\", \"label\": \"One more (read aloud)\", \"default\": \"One more\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_cart_side.storelib",
  "source": "{# example\ntitle: Side cart drawer with product pictures and an upsell row\nsummary: Chrome kit cart drawer, a section placed after the header: the site's own cart panel (data-storelib-cart-panel) that every bag button and every add to cart on the page opens, sliding from the right over a dimmed page. Lines with pictures, options, quantity steppers and remove, a sideways row of the creator's chosen products to add (product_list, real add to cart buttons), an order note line, subtotal and checkout. Edge, width, picture shape, upsell on or off and its heading, and motion are settings; keyboard stays inside while it is open.\ntags: chrome kit, cart drawer, side cart, slide out cart, mini cart, upsell, cross sell, add to cart, product thumbnails, quantity, checkout, own chrome\n#}\n<template>\n<div class=\"csd\" data-edge=\"{{ settings.edge }}\" data-shape=\"{{ settings.picture_shape }}\" data-motion=\"{{ settings.motion }}\" {% if page.in_editor and settings.editor_open %}data-editor-open{% endif %} data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --csd-w: {{ settings.width }}px; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <aside class=\"csd__panel\" data-storelib-cart-panel aria-label=\"{{ settings.title }}\">\n    <button class=\"csd__scrim\" type=\"button\" data-storelib-cart-close tabindex=\"-1\" aria-label=\"{{ settings.close_label }}\"></button>\n    <div class=\"csd__sheet\" role=\"dialog\" aria-label=\"{{ settings.title }}\">\n      <div class=\"csd__head\">\n        <h2 class=\"csd__title\">{{ settings.title }} <span class=\"csd__n\" data-storelib-cart-count></span></h2>\n        <button class=\"csd__close\" type=\"button\" data-storelib-cart-close>{{ settings.close_label }}</button>\n      </div>\n      <div class=\"csd__body\">\n        <div class=\"csd__empty\" data-storelib-cart-empty>\n          <p>{{ settings.empty_text }}</p>\n          <a class=\"csd__ghost\" href=\"{{ settings.empty_url | url }}\">{{ settings.empty_link }}</a>\n        </div>\n        <ul class=\"csd__lines\" data-storelib-cart-lines>\n          <li class=\"csd__line\" data-storelib-cart-line hidden>\n            <a class=\"csd__pic\" data-line-url><img data-line-image alt=\"\" width=\"96\" height=\"120\"></a>\n            <div class=\"csd__info\">\n              <a class=\"csd__name\" data-line-url><span data-line-title></span></a>\n              <span class=\"csd__var\" data-line-variant></span>\n              <div class=\"csd__qty\">\n                <button type=\"button\" data-line-dec aria-label=\"{{ settings.less_label }}\">&minus;</button>\n                <span data-line-qty></span>\n                <button type=\"button\" data-line-inc aria-label=\"{{ settings.more_label }}\">+</button>\n              </div>\n            </div>\n            <div class=\"csd__end\"><span class=\"csd__price\" data-line-price></span><button class=\"csd__remove\" type=\"button\" data-line-remove>{{ settings.remove_label }}</button></div>\n          </li>\n        </ul>\n        {% if settings.show_upsell and settings.upsell.size > 0 %}\n        <div class=\"csd__up\">\n          <h3 class=\"csd__up-h\">{{ settings.upsell_heading }}</h3>\n          <ul class=\"csd__up-row\">\n            {% for p in settings.upsell %}\n            <li class=\"csd__up-card\">\n              <a class=\"csd__up-link\" href=\"{{ p.settings.url | url }}\">{% if p.settings.image %}<img src=\"{{ p.settings.image | asset }}\" alt=\"{{ p.settings.title }}\" width=\"240\" height=\"300\" loading=\"lazy\">{% endif %}<span>{{ p.settings.title }}</span></a>\n              <span class=\"csd__up-price\">{{ p.settings.price }}</span>\n              {% if p.settings.available %}<button class=\"csd__add\" type=\"button\" data-storelib-add-to-cart=\"{{ p.id }}\" data-title=\"{{ p.settings.title }}\" data-price=\"{{ p.settings.price }}\" data-image=\"{{ p.settings.image | asset }}\" data-url=\"{{ p.settings.url }}\" data-kind=\"{{ p.settings.kind }}\">{{ settings.add_label }}</button>{% endif %}\n            </li>\n            {% endfor %}\n          </ul>\n        </div>\n        {% endif %}\n      </div>\n      <div class=\"csd__foot\" data-storelib-cart-filled>\n        <p class=\"csd__sub\"><span>{{ settings.subtotal_label }}</span><span data-storelib-cart-subtotal></span></p>\n        {% if settings.note %}<p class=\"csd__note\">{{ settings.note }}</p>{% endif %}\n        <button class=\"csd__checkout\" type=\"button\" data-storelib-checkout>{{ settings.checkout_label }}</button>\n        <a class=\"csd__view\" href=\"{{ routes.cart_url }}\">{{ settings.view_label }}</a>\n      </div>\n    </div>\n  </aside>\n</div>\n</template>\n\n<style scoped>\n.csd, .csd *, .csd *::before, .csd *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.csd [hidden] { display: none !important; }\n.csd__panel { position: fixed; inset: 0; z-index: 85; visibility: hidden; }\n.csd__panel[data-open=\"true\"], .csd[data-editor-open] .csd__panel { visibility: visible; }\n.csd[data-editor-open] .csd__panel { position: relative; min-height: 720px; }\n.csd__scrim { position: absolute; inset: 0; width: 100%; padding: 0; border: 0; background: rgba(0, 0, 0, 0.4); opacity: 0; cursor: pointer; }\n.csd__panel[data-open=\"true\"] .csd__scrim, .csd[data-editor-open] .csd__scrim { opacity: 1; }\n.csd__sheet { position: absolute; inset: 0 0 0 auto; display: flex; flex-direction: column; width: min(var(--csd-w), 100%); background: var(--s-bg); color: var(--s-text); transform: translateX(100%); }\n.csd[data-edge=\"left\"] .csd__sheet { inset: 0 auto 0 0; transform: translateX(-100%); }\n.csd__panel[data-open=\"true\"] .csd__sheet, .csd[data-editor-open] .csd__sheet { transform: none; }\n.csd__head { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 64px; padding: 0 20px; border-bottom: 1px solid var(--s-border); }\n.csd__title { margin: 0; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.25rem, 1.1rem + 0.6vw, 1.625rem); font-weight: 700; letter-spacing: -0.02em; }\n.csd__n { font-family: var(--theme-font-body), sans-serif; font-size: 0.875rem; font-weight: 500; font-variant-numeric: tabular-nums; }\n.csd__n[data-count=\"0\"] { display: none; }\n.csd__close { min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.csd__body { flex: 1; overflow-y: auto; overscroll-behavior: contain; padding: 0 20px; }\n.csd__empty { display: grid; justify-items: start; gap: 12px; padding: 32px 0; }\n.csd__empty p { margin: 0; font-size: 1.125rem; }\n.csd__ghost { display: inline-flex; align-items: center; min-height: 44px; padding: 0 16px; border: 1px solid currentColor; color: inherit; text-decoration: none; }\n.csd__lines { margin: 0; padding: 0; list-style: none; }\n.csd__line { display: grid; grid-template-columns: 80px minmax(0, 1fr) auto; gap: 14px; padding: 16px 0; border-bottom: 1px solid var(--s-border); }\n.csd__pic { display: block; }\n.csd__pic img { display: block; width: 80px; height: 100px; object-fit: cover; background: var(--s-border); }\n.csd[data-shape=\"square\"] .csd__pic img { height: 80px; }\n.csd__info { display: grid; gap: 4px; align-content: start; min-width: 0; }\n.csd__name { color: inherit; font-weight: 600; text-decoration: none; }\n.csd__var { font-size: 0.875rem; opacity: 0.8; }\n.csd__qty { display: inline-flex; align-items: center; width: max-content; margin-top: 6px; border: 1px solid var(--s-border); }\n.csd__qty button { min-width: 44px; min-height: 40px; border: 0; background: none; color: inherit; font: inherit; font-size: 1.125rem; cursor: pointer; }\n.csd__qty span { min-width: 24px; text-align: center; font-variant-numeric: tabular-nums; }\n.csd__end { display: grid; justify-items: end; align-content: space-between; gap: 8px; }\n.csd__price { font-variant-numeric: tabular-nums; font-weight: 600; }\n.csd__remove { min-height: 44px; padding: 0; border: 0; background: none; color: inherit; font: inherit; font-size: 0.875rem; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }\n.csd__up { padding: 20px 0; }\n.csd__up-h { margin: 0 0 12px; font-size: 1rem; font-weight: 600; }\n.csd__up-row { display: flex; gap: 12px; margin: 0; padding: 0 0 4px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: thin; list-style: none; }\n.csd__up-card { flex: 0 0 136px; display: grid; gap: 6px; scroll-snap-align: start; font-size: 0.875rem; }\n.csd__up-link { display: grid; gap: 6px; color: inherit; text-decoration: none; }\n.csd__up-link img { display: block; width: 100%; height: auto; aspect-ratio: 4 / 5; object-fit: cover; }\n.csd__up-price { font-variant-numeric: tabular-nums; }\n.csd__add { min-height: 40px; border: 1px solid currentColor; background: none; color: inherit; font: inherit; cursor: pointer; }\n.csd__add:hover { background: var(--s-text); color: var(--s-bg); }\n.csd__foot { display: grid; gap: 10px; padding: 16px 20px calc(16px + env(safe-area-inset-bottom, 0px)); border-top: 1px solid var(--s-border); }\n.csd__sub { display: flex; justify-content: space-between; margin: 0; font-size: 1.125rem; font-weight: 600; font-variant-numeric: tabular-nums; }\n.csd__note { margin: 0; font-size: 0.875rem; }\n.csd__checkout { min-height: 54px; border: 0; background: var(--s-btn); color: var(--s-btn-text); font: inherit; font-size: 1.0625rem; font-weight: 600; cursor: pointer; }\n.csd__checkout[disabled] { opacity: 0.6; cursor: progress; }\n.csd__view { justify-self: center; display: inline-flex; align-items: center; min-height: 44px; color: inherit; font-size: 0.9375rem; }\n.csd :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  .csd:not([data-motion=\"off\"]) .csd__panel { transition: visibility 0s linear var(--t-motion-duration, 650ms); }\n  .csd:not([data-motion=\"off\"]) .csd__panel[data-open=\"true\"] { transition-delay: 0s; }\n  .csd:not([data-motion=\"off\"]) .csd__sheet { transition: transform calc(var(--t-motion-duration, 650ms) * 0.7) cubic-bezier(0.32, 0.72, 0, 1); }\n  .csd:not([data-motion=\"off\"]) .csd__scrim { transition: opacity calc(var(--t-motion-duration, 650ms) * 0.5) ease; }\n  .csd:not([data-motion=\"off\"]) .csd__panel[data-open=\"true\"] .csd__line { animation: csd-in calc(var(--t-motion-duration, 650ms) * 0.7) var(--t-motion-ease, ease-out) 120ms both; }\n  @keyframes csd-in { from { opacity: 0; transform: translateX(calc(var(--t-motion-distance, 24px) * var(--m-k, 1))); } }\n}\n@media (prefers-reduced-motion: reduce) { .csd__panel, .csd__sheet, .csd__scrim, .csd__line { transition: none; animation: none; } }\n@media (min-width: 600px) {\n  .csd__line { grid-template-columns: 96px minmax(0, 1fr) auto; }\n  .csd__pic img { width: 96px; height: 120px; }\n  .csd[data-shape=\"square\"] .csd__pic img { height: 96px; }\n  .csd__head, .csd__body, .csd__foot { padding-left: 24px; padding-right: 24px; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_cart_side\",\n  \"name\": \"Side cart with upsell\",\n  \"settings\": [\n    { \"type\": \"paragraph\", \"id\": \"about\", \"content\": \"Opens from every bag button and every add to cart on the page. Keep it right after the header.\" },\n    { \"type\": \"checkbox\", \"id\": \"editor_open\", \"label\": \"Keep it open in the editor\", \"default\": false },\n    { \"type\": \"header\", \"id\": \"hdr_upsell\", \"label\": \"Upsell\" },\n    { \"type\": \"checkbox\", \"id\": \"show_upsell\", \"label\": \"Show products to add\", \"default\": true },\n    { \"type\": \"text\", \"id\": \"upsell_heading\", \"label\": \"Heading\", \"default\": \"Goes well with it\" },\n    { \"type\": \"product_list\", \"id\": \"upsell\", \"label\": \"Products\", \"limit\": 8 },\n    { \"type\": \"text\", \"id\": \"add_label\", \"label\": \"Add button\", \"default\": \"Add\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"select\", \"id\": \"edge\", \"label\": \"Comes from\", \"default\": \"right\", \"options\": [{ \"label\": \"Right\", \"value\": \"right\" }, { \"label\": \"Left\", \"value\": \"left\" }] },\n    { \"type\": \"range\", \"id\": \"width\", \"label\": \"Width\", \"min\": 340, \"max\": 560, \"step\": 10, \"unit\": \"px\", \"default\": 440 },\n    { \"type\": \"select\", \"id\": \"picture_shape\", \"label\": \"Line pictures\", \"default\": \"portrait\", \"options\": [{ \"label\": \"Portrait\", \"value\": \"portrait\" }, { \"label\": \"Square\", \"value\": \"square\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"Your bag\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"empty_text\", \"label\": \"When it is empty\", \"default\": \"Nothing in here yet.\" },\n    { \"type\": \"text\", \"id\": \"empty_link\", \"label\": \"Link when it is empty\", \"default\": \"Start with the shop\" },\n    { \"type\": \"url\", \"id\": \"empty_url\", \"label\": \"That link goes to\", \"default\": \"/shop\" },\n    { \"type\": \"text\", \"id\": \"subtotal_label\", \"label\": \"Subtotal\", \"default\": \"Subtotal\" },\n    { \"type\": \"text\", \"id\": \"note\", \"label\": \"Line above checkout\", \"default\": \"Delivery and taxes are worked out at checkout.\" },\n    { \"type\": \"text\", \"id\": \"checkout_label\", \"label\": \"Checkout button\", \"default\": \"Check out\" },\n    { \"type\": \"text\", \"id\": \"view_label\", \"label\": \"Link to the full bag\", \"default\": \"View the full bag\" },\n    { \"type\": \"text\", \"id\": \"remove_label\", \"label\": \"Remove\", \"default\": \"Remove\" },\n    { \"type\": \"text\", \"id\": \"less_label\", \"label\": \"One less (read aloud)\", \"default\": \"One less\" },\n    { \"type\": \"text\", \"id\": \"more_label\", \"label\": \"One more (read aloud)\", \"default\": \"One more\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_footer_columns.storelib",
  "source": "{# example\ntitle: Multi column footer built from blocks\nsummary: Chrome kit footer whose columns are blocks the creator adds, orders and removes: a menu column (any of the site's menus, its own heading), a text column (address, hours, a note with a link), and a social column. A brand line and the logo lead, columns follow (two per row on phones, up to six on wide screens), then the language and currency drop downs and the bottom line. Columns per row, divider lines, the brand line and colours are settings.\ntags: chrome kit, footer, multi column footer, columns, footer menus, link columns, address, opening hours, socials, store footer, own chrome, site footer\n#}\n<template>\n<footer class=\"fcl\" data-lines=\"{{ settings.lines }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --fcl-cols: {{ settings.columns }};\">\n  <div class=\"fcl__grid\">\n    <div class=\"fcl__brand\">\n      <a class=\"fcl__logo\" href=\"{{ routes.root_url }}\">{% if theme.logo.url %}<img src=\"{{ theme.logo.url }}\" alt=\"{{ shop.name }}\" width=\"160\" height=\"40\" loading=\"lazy\">{% else %}{{ shop.name | default: settings.brand }}{% endif %}</a>\n      <p class=\"fcl__line\">{{ settings.brand_line }}</p>\n    </div>\n    {% for block in section.blocks %}\n    <div class=\"fcl__col\" data-block-id=\"{{ block.id }}\">\n      {% if block.type == \"menu\" %}\n      <h2 class=\"fcl__h\">{{ block.settings.heading | default: block.settings.menu.title }}</h2>\n      <ul>{% for link in block.settings.menu.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul>\n      {% elsif block.type == \"text\" %}\n      <h2 class=\"fcl__h\">{{ block.settings.heading }}</h2>\n      <p class=\"fcl__text\">{{ block.settings.text }}</p>\n      {% if block.settings.link_label %}<a class=\"fcl__more\" href=\"{{ block.settings.link_url | url }}\">{{ block.settings.link_label }}</a>{% endif %}\n      {% elsif block.type == \"social\" %}\n      <h2 class=\"fcl__h\">{{ block.settings.heading }}</h2>\n      <ul>\n        {% if block.settings.instagram %}<li><a href=\"{{ block.settings.instagram | url }}\" target=\"_blank\" rel=\"noopener\">Instagram</a></li>{% endif %}\n        {% if block.settings.tiktok %}<li><a href=\"{{ block.settings.tiktok | url }}\" target=\"_blank\" rel=\"noopener\">TikTok</a></li>{% endif %}\n        {% if block.settings.youtube %}<li><a href=\"{{ block.settings.youtube | url }}\" target=\"_blank\" rel=\"noopener\">YouTube</a></li>{% endif %}\n        {% if block.settings.pinterest %}<li><a href=\"{{ block.settings.pinterest | url }}\" target=\"_blank\" rel=\"noopener\">Pinterest</a></li>{% endif %}\n      </ul>\n      {% endif %}\n    </div>\n    {% endfor %}\n  </div>\n  <div class=\"fcl__base\">\n    <span>{{ settings.copyright }}</span>\n    <div class=\"fcl__prefs\">\n      <details class=\"fcl__pick\" data-storelib-locale-list>\n        <summary>{{ settings.language_label }}: <span data-storelib-locale-current></span></summary>\n        <div class=\"fcl__menu\"><button class=\"fcl__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n      </details>\n      <details class=\"fcl__pick\" data-storelib-currency-list>\n        <summary>{{ settings.currency_label }}: <span data-storelib-currency-current></span></summary>\n        <div class=\"fcl__menu\"><button class=\"fcl__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n      </details>\n    </div>\n  </div>\n</footer>\n</template>\n\n<style scoped>\n.fcl, .fcl *, .fcl *::before, .fcl *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.fcl [hidden] { display: none !important; }\n.fcl { container-type: inline-size; padding: clamp(48px, 7vw, 96px) var(--theme-padding-x, 16px) 20px; background: var(--s-bg); color: var(--s-text); }\n.fcl__grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 36px 20px; }\n.fcl__brand { grid-column: 1 / -1; display: grid; gap: 12px; align-content: start; }\n.fcl__logo { display: inline-flex; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: 1.75rem; font-weight: 700; letter-spacing: -0.03em; text-decoration: none; }\n.fcl__logo img { display: block; width: auto; height: 36px; }\n.fcl__line { margin: 0; max-width: 34ch; font-size: 1.0625rem; }\n.fcl__col { min-width: 0; }\n.fcl[data-lines=\"true\"] .fcl__col { padding-top: 14px; border-top: 1px solid var(--s-border); }\n.fcl__h { margin: 0 0 10px; color: var(--s-heading); font-family: var(--theme-font-body), sans-serif; font-size: 0.9375rem; font-weight: 700; }\n.fcl__col ul { margin: 0; padding: 0; list-style: none; }\n.fcl__col a { display: inline-flex; align-items: center; min-height: 40px; color: inherit; text-decoration: none; }\n.fcl__col a:hover { text-decoration: underline; text-underline-offset: 4px; }\n.fcl__text { margin: 0; white-space: pre-line; line-height: 1.6; }\n.fcl__more { font-weight: 600; text-decoration: underline !important; text-underline-offset: 4px; }\n.fcl__base { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 12px 24px; margin-top: clamp(40px, 6vw, 72px); padding-top: 16px; border-top: 1px solid var(--s-border); font-size: 0.875rem; }\n.fcl__prefs { display: flex; flex-wrap: wrap; gap: 8px; }\n.fcl__pick { position: relative; }\n.fcl__pick summary { display: inline-flex; align-items: center; gap: 4px; min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); cursor: pointer; list-style: none; }\n.fcl__pick summary::-webkit-details-marker { display: none; }\n.fcl__menu { position: absolute; bottom: calc(100% + 6px); right: 0; z-index: 5; display: grid; min-width: 180px; padding: 6px; border: 1px solid var(--s-border); background: var(--s-bg); }\n.fcl__opt { min-height: 44px; padding: 0 10px; border: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }\n.fcl__opt[aria-current=\"true\"] { font-weight: 700; }\n.fcl :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@container (min-width: 900px) {\n  .fcl__grid { grid-template-columns: minmax(0, 2fr) repeat(var(--fcl-cols, 4), minmax(0, 1fr)); gap: 40px 32px; }\n  .fcl__brand { grid-column: auto; grid-row: span 2; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_footer_columns\",\n  \"name\": \"Multi column footer\",\n  \"kind\": \"footer\",\n  \"enabled_on\": { \"groups\": [\"footer\"] },\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no logo\", \"default\": \"Studio\" },\n    { \"type\": \"text\", \"id\": \"brand_line\", \"label\": \"Brand line\", \"default\": \"Small batches, made to last, sent with care.\" },\n    { \"type\": \"range\", \"id\": \"columns\", \"label\": \"Columns on wide screens\", \"min\": 2, \"max\": 6, \"step\": 1, \"default\": 4 },\n    { \"type\": \"checkbox\", \"id\": \"lines\", \"label\": \"Line above each column\", \"default\": true },\n    { \"type\": \"text\", \"id\": \"copyright\", \"label\": \"Bottom line\", \"default\": \"Made by hand in small batches\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency\", \"default\": \"Currency\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"menu\", \"name\": \"Menu column\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading (empty for the menu's name)\", \"default\": \"\" },\n      { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"footer\" }\n    ] },\n    { \"type\": \"text\", \"name\": \"Text column\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Visit\" },\n      { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"12 Mill Lane, Leeds\\nTuesday to Saturday, 10 to 5\" },\n      { \"type\": \"text\", \"id\": \"link_label\", \"label\": \"Link\", \"default\": \"Directions\" },\n      { \"type\": \"url\", \"id\": \"link_url\", \"label\": \"Link goes to\", \"default\": \"/contact\" }\n    ] },\n    { \"type\": \"social\", \"name\": \"Social column\", \"limit\": 1, \"settings\": [\n      { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Follow\" },\n      { \"type\": \"url\", \"id\": \"instagram\", \"label\": \"Instagram\", \"default\": \"https://instagram.com\" },\n      { \"type\": \"url\", \"id\": \"tiktok\", \"label\": \"TikTok\" },\n      { \"type\": \"url\", \"id\": \"youtube\", \"label\": \"YouTube\" },\n      { \"type\": \"url\", \"id\": \"pinterest\", \"label\": \"Pinterest\", \"default\": \"https://pinterest.com\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Multi column footer\", \"blocks\": [\n    { \"type\": \"menu\", \"settings\": { \"heading\": \"Shop\", \"menu\": \"main-menu\" } },\n    { \"type\": \"menu\", \"settings\": { \"heading\": \"Help\", \"menu\": \"footer\" } },\n    { \"type\": \"text\", \"settings\": { \"heading\": \"Visit\", \"text\": \"12 Mill Lane, Leeds\\nTuesday to Saturday, 10 to 5\", \"link_label\": \"Directions\", \"link_url\": \"/contact\" } },\n    { \"type\": \"social\", \"settings\": { \"heading\": \"Follow\", \"instagram\": \"https://instagram.com\", \"pinterest\": \"https://pinterest.com\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_footer_image.storelib",
  "source": "{# example\ntitle: Image backed footer with a last call to action\nsummary: Chrome kit footer over a full bleed photograph (the creator's own, image_picker, with a focal point and a scrim so the words stay readable): a last statement and one action, then the menus, address and the language and currency over the picture, drifting slowly as it scrolls past (a CSS view timeline, off under reduced motion). Without a picture it falls back to a designed solid panel in the scheme's colours, never a grey box. Scrim strength, height, text colour, drift and the action are settings.\ntags: chrome kit, footer, image footer, photo footer, full bleed footer, background image, call to action footer, cta, parallax, restaurant, hotel, travel, own chrome, site footer\n#}\n<template>\n<footer class=\"fim\" data-has-image=\"{% if settings.image %}true{% else %}false{% endif %}\" data-text=\"{{ settings.text_tone }}\" data-drift=\"{{ settings.drift }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --fim-scrim: {{ settings.scrim }}; --fim-h: {{ settings.min_height }}svh;\">\n  {% if settings.image %}<div class=\"fim__media\" aria-hidden=\"true\"><img src=\"{{ settings.image | asset }}\" alt=\"\" width=\"2400\" height=\"1600\" loading=\"lazy\" style=\"object-position: {{ settings.focus }};\"></div>{% endif %}\n  <div class=\"fim__in\">\n    <div class=\"fim__lead\">\n      <h2 class=\"fim__h\">{{ settings.statement }}</h2>\n      {% if settings.cta_label %}<a class=\"fim__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n    </div>\n    <div class=\"fim__cols\">\n      <nav aria-label=\"{{ settings.nav_label }}\"><ul>{% for link in settings.menu.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul></nav>\n      <p class=\"fim__addr\">{{ settings.address }}</p>\n    </div>\n    <div class=\"fim__base\"><span>{{ settings.copyright }}</span><span class=\"fim__prefs\"><span data-storelib-locale-current></span> <span data-storelib-currency-current></span></span></div>\n  </div>\n</footer>\n</template>\n\n<style scoped>\n.fim, .fim *, .fim *::before, .fim *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.fim [hidden] { display: none !important; }\n.fim { container-type: inline-size; position: relative; isolation: isolate; overflow: hidden; display: flex; min-height: var(--fim-h, 80svh); background: var(--s-bg); color: var(--s-text); }\n.fim__media { position: absolute; inset: -8% 0; z-index: -2; }\n.fim__media img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.fim[data-has-image=\"true\"]::before { content: \"\"; position: absolute; inset: 0; z-index: -1; background: linear-gradient(to top, rgba(0, 0, 0, var(--fim-scrim, 0.6)), rgba(0, 0, 0, calc(var(--fim-scrim, 0.6) * 0.35)) 70%, transparent); }\n.fim[data-has-image=\"true\"][data-text=\"light\"] { color: #fff; --s-heading: #fff; --s-border: rgba(255, 255, 255, 0.35); }\n.fim[data-has-image=\"false\"] { background: var(--s-heading); color: var(--s-bg); --s-border: color-mix(in srgb, var(--s-bg) 30%, transparent); }\n.fim[data-has-image=\"false\"] .fim__h { color: var(--s-bg); }\n.fim[data-has-image=\"false\"] .fim__cta { background: var(--s-bg); color: var(--s-heading); }\n.fim__in { display: grid; align-content: end; gap: clamp(32px, 6vw, 72px); width: 100%; padding: clamp(64px, 12vw, 160px) var(--theme-padding-x, 16px) 20px; }\n.fim__lead { display: grid; gap: 24px; justify-items: start; }\n.fim__h { margin: 0; max-width: 14ch; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.5rem, 1.2rem + 6vw, 6.5rem); line-height: 0.95; letter-spacing: -0.04em; font-weight: 700; text-wrap: balance; }\n.fim__cta { display: inline-flex; align-items: center; min-height: 52px; padding: 0 26px; background: var(--s-btn); color: var(--s-btn-text); font-weight: 600; text-decoration: none; }\n.fim__cols { display: grid; gap: 20px; padding-top: 20px; border-top: 1px solid var(--s-border); }\n.fim__cols ul { display: flex; flex-wrap: wrap; gap: 0 22px; margin: 0; padding: 0; list-style: none; }\n.fim__cols a { display: inline-flex; align-items: center; min-height: 44px; color: inherit; text-decoration: none; }\n.fim__cols a:hover { text-decoration: underline; text-underline-offset: 4px; }\n.fim__addr { margin: 0; white-space: pre-line; line-height: 1.6; }\n.fim__base { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 20px; font-size: 0.875rem; }\n.fim :focus-visible { outline: 2px solid currentColor; outline-offset: 3px; }\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .fim[data-drift=\"true\"] .fim__media { animation: fim-drift linear both; animation-timeline: view(); }\n    @keyframes fim-drift { from { transform: translateY(calc(var(--t-motion-parallax, 6%) * -1)); } to { transform: translateY(var(--t-motion-parallax, 6%)); } }\n  }\n}\n@media (prefers-reduced-motion: reduce) { .fim__media { animation: none; } }\n@container (min-width: 820px) {\n  .fim__cols { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); align-items: start; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_footer_image\",\n  \"name\": \"Image footer\",\n  \"kind\": \"footer\",\n  \"enabled_on\": { \"groups\": [\"footer\"] },\n  \"settings\": [\n    { \"type\": \"header\", \"id\": \"hdr_image\", \"label\": \"Picture\" },\n    { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n    { \"type\": \"select\", \"id\": \"focus\", \"label\": \"Keep in view\", \"default\": \"center\", \"options\": [{ \"label\": \"Centre\", \"value\": \"center\" }, { \"label\": \"Top\", \"value\": \"top\" }, { \"label\": \"Bottom\", \"value\": \"bottom\" }] },\n    { \"type\": \"range\", \"id\": \"scrim\", \"label\": \"Shade over the picture\", \"min\": 0, \"max\": 0.9, \"step\": 0.05, \"default\": 0.6 },\n    { \"type\": \"select\", \"id\": \"text_tone\", \"label\": \"Text over the picture\", \"default\": \"light\", \"options\": [{ \"label\": \"Light\", \"value\": \"light\" }, { \"label\": \"Scheme colours\", \"value\": \"scheme\" }] },\n    { \"type\": \"checkbox\", \"id\": \"drift\", \"label\": \"Picture drifts on scroll\", \"default\": true },\n    { \"type\": \"range\", \"id\": \"min_height\", \"label\": \"Height (share of the screen)\", \"min\": 40, \"max\": 100, \"step\": 5, \"unit\": \"%\", \"default\": 80 },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"statement\", \"label\": \"Statement\", \"default\": \"Come and see it in person.\" },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"Book a visit\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button goes to\", \"default\": \"/contact\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"footer\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Footer\" },\n    { \"type\": \"textarea\", \"id\": \"address\", \"label\": \"Address and hours\", \"default\": \"4 Harbour Street\\nOpen Thursday to Sunday\" },\n    { \"type\": \"text\", \"id\": \"copyright\", \"label\": \"Bottom line\", \"default\": \"Family run since 1998\" },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_footer_line.storelib",
  "source": "{# example\ntitle: Minimal one line footer\nsummary: Chrome kit footer for quiet sites: one line holding the name and a short note, the menu, socials (blocks) and the current language and currency, wrapping into two or three short rows on a phone. A thin rule or none above it, one link at the end (contact, press), spacing, text size and colours are settings.\ntags: chrome kit, footer, minimal footer, one line footer, simple footer, small footer, portfolio footer, socials, own chrome, site footer\n#}\n<template>\n<footer class=\"fln\" data-rule=\"{{ settings.rule }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --fln-py: {{ settings.padding_y }}px; --fln-size: {{ settings.text_size }}px;\">\n  <div class=\"fln__in\">\n    <p class=\"fln__name\"><a href=\"{{ routes.root_url }}\">{{ shop.name | default: settings.brand }}</a> <span>{{ settings.note }}</span></p>\n    <nav class=\"fln__nav\" aria-label=\"{{ settings.nav_label }}\"><ul>{% for link in settings.menu.links limit: 6 %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}{% for block in section.blocks %}<li data-block-id=\"{{ block.id }}\"><a href=\"{{ block.settings.url | url }}\" target=\"_blank\" rel=\"noopener\">{{ block.settings.label }}</a></li>{% endfor %}</ul></nav>\n    <p class=\"fln__end\"><span class=\"fln__prefs\"><span data-storelib-locale-current></span> <span data-storelib-currency-current></span></span>{% if settings.end_label %}<a class=\"fln__top\" href=\"{{ settings.end_url | url }}\">{{ settings.end_label }}</a>{% endif %}</p>\n  </div>\n</footer>\n</template>\n\n<style scoped>\n.fln, .fln *, .fln *::before, .fln *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.fln [hidden] { display: none !important; }\n.fln { padding: var(--fln-py, 28px) var(--theme-padding-x, 16px); background: var(--s-bg); color: var(--s-text); font-size: var(--fln-size, 15px); }\n.fln[data-rule=\"true\"] .fln__in { padding-top: 16px; border-top: 1px solid var(--s-border); }\n.fln__in { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 28px; }\n.fln__name { margin: 0; }\n.fln__name a { color: var(--s-heading); font-weight: 700; text-decoration: none; }\n.fln__nav ul { display: flex; flex-wrap: wrap; gap: 0 18px; margin: 0; padding: 0; list-style: none; }\n.fln a { display: inline-flex; align-items: center; min-height: 44px; color: inherit; }\n.fln__nav a { text-decoration: none; }\n.fln__nav a:hover { text-decoration: underline; text-underline-offset: 4px; }\n.fln__end { display: flex; flex-wrap: wrap; align-items: center; gap: 0 18px; margin: 0; }\n.fln__prefs:has(> span:empty + span:empty) { display: none; }\n.fln :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (min-width: 900px) { .fln__nav { margin-left: auto; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_footer_line\",\n  \"name\": \"One line footer\",\n  \"kind\": \"footer\",\n  \"enabled_on\": { \"groups\": [\"footer\"] },\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no shop name\", \"default\": \"Studio\" },\n    { \"type\": \"text\", \"id\": \"note\", \"label\": \"Note beside the name\", \"default\": \"Leeds, since 2019\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"footer\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Footer\" },\n    { \"type\": \"text\", \"id\": \"end_label\", \"label\": \"Link at the end\", \"default\": \"Contact\" },\n    { \"type\": \"url\", \"id\": \"end_url\", \"label\": \"That link goes to\", \"default\": \"/contact\" },\n    { \"type\": \"checkbox\", \"id\": \"rule\", \"label\": \"Thin line above\", \"default\": true },\n    { \"type\": \"range\", \"id\": \"padding_y\", \"label\": \"Space above and below\", \"min\": 8, \"max\": 80, \"step\": 4, \"unit\": \"px\", \"default\": 28 },\n    { \"type\": \"range\", \"id\": \"text_size\", \"label\": \"Text size\", \"min\": 13, \"max\": 18, \"step\": 1, \"unit\": \"px\", \"default\": 15 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"social\", \"name\": \"Social link\", \"limit\": 4, \"settings\": [\n      { \"type\": \"text\", \"id\": \"label\", \"label\": \"Name\", \"default\": \"Instagram\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Address\", \"default\": \"https://instagram.com\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"One line footer\", \"blocks\": [\n    { \"type\": \"social\", \"settings\": { \"label\": \"Instagram\", \"url\": \"https://instagram.com\" } },\n    { \"type\": \"social\", \"settings\": { \"label\": \"LinkedIn\", \"url\": \"https://linkedin.com\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_footer_newsletter.storelib",
  "source": "{# example\ntitle: Newsletter led footer with a big sign up\nsummary: Chrome kit footer that leads with the sign up: a large promise, the email field and button on one line (joins the creator's Subscribers through data-storelib-form=\"subscribe\", with a thank you line), a short consent line, then reasons to join as a numbered row (blocks), the menus and a bottom line with language and currency. Layout (split or stacked), field style (underline or box), the promise size and colours are settings.\ntags: chrome kit, footer, newsletter footer, signup, sign up, subscribe, email capture, mailing list, community, own chrome, site footer\n#}\n<template>\n<footer class=\"fnl\" data-layout=\"{{ settings.layout }}\" data-field=\"{{ settings.field_style }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --fnl-size: {{ settings.promise_size }};\">\n  <div class=\"fnl__lead\">\n    <h2 class=\"fnl__promise\">{{ settings.promise }}</h2>\n    <form class=\"fnl__form\" data-storelib-form=\"subscribe\">\n      <label class=\"fnl__label\" for=\"{{ section.id }}-mail\">{{ settings.field_label }}</label>\n      <div class=\"fnl__row\">\n        <input class=\"fnl__input\" id=\"{{ section.id }}-mail\" name=\"email\" type=\"email\" inputmode=\"email\" autocomplete=\"email\" maxlength=\"254\" placeholder=\"{{ settings.placeholder }}\" required>\n        <button class=\"fnl__btn\" type=\"submit\">{{ settings.button }}</button>\n      </div>\n      <p class=\"fnl__small\">{{ settings.consent }}</p>\n      <p class=\"fnl__done\" data-storelib-success hidden>{{ settings.success }}</p>\n    </form>\n  </div>\n  {% if section.blocks.size > 0 %}\n  <ol class=\"fnl__reasons\">\n    {% for block in section.blocks %}<li data-block-id=\"{{ block.id }}\"><span class=\"fnl__n\" aria-hidden=\"true\">{{ forloop.index }}</span><span class=\"fnl__r-t\">{{ block.settings.title }}</span><span class=\"fnl__r-x\">{{ block.settings.text }}</span></li>{% endfor %}\n  </ol>\n  {% endif %}\n  <div class=\"fnl__menus\">\n    <nav aria-label=\"{{ settings.nav_label }}\"><ul>{% for link in settings.menu.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul></nav>\n    <nav aria-label=\"{{ settings.second_label }}\"><ul>{% for link in settings.second_menu.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul></nav>\n  </div>\n  <div class=\"fnl__base\">\n    <span>{{ settings.copyright }}</span>\n    <span class=\"fnl__prefs\"><span data-storelib-locale-current></span> <span data-storelib-currency-current></span></span>\n  </div>\n</footer>\n</template>\n\n<style scoped>\n.fnl, .fnl *, .fnl *::before, .fnl *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.fnl [hidden] { display: none !important; }\n.fnl { container-type: inline-size; padding: clamp(56px, 9vw, 128px) var(--theme-padding-x, 16px) 20px; background: var(--s-bg); color: var(--s-text); }\n.fnl__lead { display: grid; gap: 28px; }\n.fnl__promise { margin: 0; max-width: 16ch; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: calc(clamp(2.25rem, 1.2rem + 5vw, 5.5rem) * var(--fnl-size, 100) / 100); line-height: 0.98; letter-spacing: -0.04em; font-weight: 700; text-wrap: balance; }\n.fnl__form { display: grid; gap: 10px; max-width: 560px; }\n.fnl__label { font-weight: 600; }\n.fnl__row { display: flex; gap: 8px; }\n.fnl__input { flex: 1; min-width: 0; min-height: 52px; padding: 0 14px; border: 1px solid var(--s-text); background: none; color: inherit; font: inherit; font-size: 1.0625rem; }\n.fnl[data-field=\"underline\"] .fnl__input { padding: 0; border-width: 0 0 2px; }\n.fnl__btn { min-height: 52px; padding: 0 22px; border: 0; background: var(--s-btn); color: var(--s-btn-text); font: inherit; font-weight: 600; cursor: pointer; }\n.fnl__small { margin: 0; font-size: 0.875rem; }\n.fnl__done { margin: 0; font-weight: 600; }\n.fnl__reasons { display: grid; gap: 20px; margin: clamp(40px, 7vw, 88px) 0 0; padding: 24px 0 0; border-top: 1px solid var(--s-border); list-style: none; }\n.fnl__reasons li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 2px 14px; }\n.fnl__n { grid-row: span 2; font-variant-numeric: tabular-nums; font-weight: 600; }\n.fnl__r-t { font-weight: 600; color: var(--s-heading); }\n.fnl__menus { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; margin-top: clamp(40px, 6vw, 72px); }\n.fnl__menus ul { margin: 0; padding: 0; list-style: none; }\n.fnl__menus a { display: inline-flex; align-items: center; min-height: 44px; color: inherit; text-decoration: none; }\n.fnl__menus a:hover { text-decoration: underline; text-underline-offset: 4px; }\n.fnl__base { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 20px; margin-top: 32px; padding-top: 16px; border-top: 1px solid var(--s-border); font-size: 0.875rem; }\n.fnl :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n@media (prefers-reduced-motion: no-preference) { .fnl__btn { transition: transform var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease); } .fnl__btn:active { transform: scale(0.98); } }\n@container (min-width: 820px) {\n  .fnl[data-layout=\"split\"] .fnl__lead { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); align-items: end; gap: 48px; }\n  .fnl__reasons { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 32px; }\n  .fnl__menus { grid-template-columns: repeat(4, minmax(0, 1fr)); }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_footer_newsletter\",\n  \"name\": \"Newsletter footer\",\n  \"kind\": \"footer\",\n  \"enabled_on\": { \"groups\": [\"footer\"] },\n  \"settings\": [\n    { \"type\": \"header\", \"id\": \"hdr_signup\", \"label\": \"Sign up\" },\n    { \"type\": \"text\", \"id\": \"promise\", \"label\": \"Promise\", \"default\": \"One letter a month. New work first, no noise.\" },\n    { \"type\": \"text\", \"id\": \"field_label\", \"label\": \"Field label\", \"default\": \"Your email\" },\n    { \"type\": \"text\", \"id\": \"placeholder\", \"label\": \"Hint in the field\", \"default\": \"Your email address\" },\n    { \"type\": \"text\", \"id\": \"button\", \"label\": \"Button\", \"default\": \"Join\" },\n    { \"type\": \"text\", \"id\": \"consent\", \"label\": \"Small print\", \"default\": \"Leave whenever you like, one click.\" },\n    { \"type\": \"text\", \"id\": \"success\", \"label\": \"After signing up\", \"default\": \"You are in. Check your inbox.\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"select\", \"id\": \"layout\", \"label\": \"Promise and form\", \"default\": \"split\", \"options\": [{ \"label\": \"Side by side\", \"value\": \"split\" }, { \"label\": \"Stacked\", \"value\": \"stacked\" }] },\n    { \"type\": \"select\", \"id\": \"field_style\", \"label\": \"Field\", \"default\": \"underline\", \"options\": [{ \"label\": \"Underline\", \"value\": \"underline\" }, { \"label\": \"Box\", \"value\": \"box\" }] },\n    { \"type\": \"range\", \"id\": \"promise_size\", \"label\": \"Promise size\", \"min\": 50, \"max\": 130, \"step\": 5, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_menus\", \"label\": \"Menus\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"First menu\", \"default\": \"main-menu\" },\n    { \"type\": \"link_list\", \"id\": \"second_menu\", \"label\": \"Second menu\", \"default\": \"footer\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"First menu name (read aloud)\", \"default\": \"Shop\" },\n    { \"type\": \"text\", \"id\": \"second_label\", \"label\": \"Second menu name (read aloud)\", \"default\": \"Help\" },\n    { \"type\": \"text\", \"id\": \"copyright\", \"label\": \"Bottom line\", \"default\": \"Independent and proud of it\" },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"reason\", \"name\": \"Reason to join\", \"limit\": 3, \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"First look\" },\n      { \"type\": \"text\", \"id\": \"text\", \"label\": \"Line\", \"default\": \"New pieces a day before the shop.\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Newsletter footer\", \"blocks\": [\n    { \"type\": \"reason\", \"settings\": { \"title\": \"First look\", \"text\": \"New pieces a day before the shop.\" } },\n    { \"type\": \"reason\", \"settings\": { \"title\": \"Behind the work\", \"text\": \"How each batch is made, start to finish.\" } },\n    { \"type\": \"reason\", \"settings\": { \"title\": \"Members' prices\", \"text\": \"Twice a year, only by email.\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_footer_sitemap.storelib",
  "source": "{# example\ntitle: Sitemap grid footer\nsummary: Chrome kit footer for sites with many pages: the whole site menu drawn as a grid, each top link a numbered heading with its sub links under it (two levels from one link_list, so it stays in step with the menu), set on hairline cells like a directory; a contact cell (blocks: email, phone, address lines) and the language and currency pills in the last cells. Cells per row, numbering, cell lines and colours are settings.\ntags: chrome kit, footer, sitemap footer, site map, directory footer, grid footer, mega footer, large site, menus, contact, locale, currency, own chrome, site footer\n#}\n<template>\n<footer class=\"fsm\" data-numbers=\"{{ settings.numbers }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --fsm-cols: {{ settings.columns }};\">\n  <h2 class=\"fsm__title\">{{ settings.title }}</h2>\n  <div class=\"fsm__grid\">\n    {% for link in settings.menu.links %}\n    <nav class=\"fsm__cell\" aria-label=\"{{ link.title }}\">\n      <a class=\"fsm__h\" href=\"{{ link.url }}\"><span class=\"fsm__n\" aria-hidden=\"true\">{{ forloop.index }}</span>{{ link.title }}</a>\n      {% if link.links.size > 0 %}<ul>{% for child in link.links %}<li><a href=\"{{ child.url }}\">{{ child.title }}</a></li>{% endfor %}</ul>{% endif %}\n    </nav>\n    {% endfor %}\n    <div class=\"fsm__cell fsm__contact\">\n      <p class=\"fsm__h\">{{ settings.contact_heading }}</p>\n      <ul>\n        {% for block in section.blocks %}\n        <li data-block-id=\"{{ block.id }}\">{% if block.settings.url %}<a href=\"{{ block.settings.url | url }}\">{{ block.settings.text }}</a>{% else %}<span>{{ block.settings.text }}</span>{% endif %}</li>\n        {% endfor %}\n      </ul>\n    </div>\n    <div class=\"fsm__cell fsm__prefs\">\n      <div class=\"fsm__pref\" data-storelib-locale-list role=\"group\" aria-label=\"{{ settings.language_label }}\"><p class=\"fsm__h\">{{ settings.language_label }}</p><button class=\"fsm__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n      <div class=\"fsm__pref\" data-storelib-currency-list role=\"group\" aria-label=\"{{ settings.currency_label }}\"><p class=\"fsm__h\">{{ settings.currency_label }}</p><button class=\"fsm__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n    </div>\n  </div>\n  <p class=\"fsm__base\">{{ settings.copyright }}</p>\n</footer>\n</template>\n\n<style scoped>\n.fsm, .fsm *, .fsm *::before, .fsm *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.fsm [hidden] { display: none !important; }\n.fsm { container-type: inline-size; padding: clamp(48px, 7vw, 96px) var(--theme-padding-x, 16px) 20px; background: var(--s-bg); color: var(--s-text); }\n.fsm__title { margin: 0 0 24px; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.75rem, 1.2rem + 2.4vw, 3.25rem); line-height: 1; letter-spacing: -0.03em; font-weight: 700; }\n.fsm__grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); border-top: 1px solid var(--s-border); border-left: 1px solid var(--s-border); }\n.fsm__cell { min-width: 0; padding: 16px 14px 20px; border-right: 1px solid var(--s-border); border-bottom: 1px solid var(--s-border); }\n.fsm__h { display: flex; align-items: baseline; gap: 10px; min-height: 32px; margin: 0 0 8px; color: var(--s-heading); font-weight: 700; text-decoration: none; }\na.fsm__h:hover { text-decoration: underline; text-underline-offset: 4px; }\n.fsm__n { font-size: 0.75rem; font-weight: 500; font-variant-numeric: tabular-nums; }\n.fsm[data-numbers=\"false\"] .fsm__n { display: none; }\n.fsm__cell ul { margin: 0; padding: 0; list-style: none; }\n.fsm__cell li a, .fsm__cell li span { display: inline-flex; align-items: center; min-height: 36px; color: inherit; text-decoration: none; font-size: 0.9375rem; overflow-wrap: anywhere; }\n.fsm__cell li a { min-height: 44px; }\n.fsm__cell li a:hover { text-decoration: underline; text-underline-offset: 4px; }\n.fsm__prefs { display: grid; gap: 12px; align-content: start; }\n.fsm__pref { display: flex; flex-wrap: wrap; gap: 6px; }\n.fsm__pref .fsm__h { flex-basis: 100%; margin: 0; }\n.fsm__opt { min-height: 40px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; font-size: 0.875rem; cursor: pointer; }\n.fsm__opt[aria-current=\"true\"] { border-color: currentColor; font-weight: 700; }\n.fsm__base { margin: 16px 0 0; font-size: 0.875rem; }\n.fsm :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@container (min-width: 760px) {\n  .fsm__grid { grid-template-columns: repeat(var(--fsm-cols, 4), minmax(0, 1fr)); }\n  .fsm__cell { padding: 20px 20px 28px; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_footer_sitemap\",\n  \"name\": \"Sitemap footer\",\n  \"kind\": \"footer\",\n  \"enabled_on\": { \"groups\": [\"footer\"] },\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"title\", \"label\": \"Heading\", \"default\": \"Everything, in one place\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu (top links become headings)\", \"default\": \"main-menu\" },\n    { \"type\": \"range\", \"id\": \"columns\", \"label\": \"Cells per row on wide screens\", \"min\": 3, \"max\": 6, \"step\": 1, \"default\": 4 },\n    { \"type\": \"checkbox\", \"id\": \"numbers\", \"label\": \"Number the headings\", \"default\": true },\n    { \"type\": \"text\", \"id\": \"contact_heading\", \"label\": \"Contact heading\", \"default\": \"Talk to us\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency\", \"default\": \"Currency\" },\n    { \"type\": \"text\", \"id\": \"copyright\", \"label\": \"Bottom line\", \"default\": \"Every order packed by hand\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"line\", \"name\": \"Contact line\", \"limit\": 5, \"settings\": [\n      { \"type\": \"text\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Write to us\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link (optional)\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Sitemap footer\", \"blocks\": [\n    { \"type\": \"line\", \"settings\": { \"text\": \"Write to us\", \"url\": \"/contact\" } },\n    { \"type\": \"line\", \"settings\": { \"text\": \"Monday to Friday, 9 to 5\" } },\n    { \"type\": \"line\", \"settings\": { \"text\": \"Returns and exchanges\", \"url\": \"/contact\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_footer_wordmark.storelib",
  "source": "{# example\ntitle: Footer with a giant wordmark that fills the width\nsummary: Chrome kit footer. A short line and a link, the menu and socials (blocks) in a quiet row, then the name set so large it spans the whole width (sized from its own length in container units, so it fills the width and never runs off), rising out of a mask as it scrolls into view (a CSS view timeline; still under reduced motion). The current language and currency and a bottom line close it. Wordmark words, size, weight, whether it rises, alignment and colours are settings.\ntags: chrome kit, footer, giant wordmark, big type footer, huge logo footer, brand footer, wordmark, scroll reveal, view timeline, socials, own chrome, site footer\n#}\n<template>\n<footer class=\"fwm\" data-reveal=\"{{ settings.reveal }}\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --fwm-fill: {{ settings.size }}; --fwm-chars: {{ settings.wordmark | default: shop.name | default: settings.fallback | size }}; --fwm-weight: {{ settings.weight }}; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"fwm__top\">\n    <p class=\"fwm__line\">{{ settings.line }}</p>\n    {% if settings.link_label %}<a class=\"fwm__cta\" href=\"{{ settings.link_url | url }}\">{{ settings.link_label }}<span class=\"fwm__arrow\" aria-hidden=\"true\"></span></a>{% endif %}\n  </div>\n  <div class=\"fwm__row\">\n    <nav aria-label=\"{{ settings.nav_label }}\"><ul class=\"fwm__links\">{% for link in settings.menu.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul></nav>\n    <ul class=\"fwm__links\">{% for block in section.blocks %}<li data-block-id=\"{{ block.id }}\"><a href=\"{{ block.settings.url | url }}\" target=\"_blank\" rel=\"noopener\">{{ block.settings.label }}</a></li>{% endfor %}</ul>\n  </div>\n  <div class=\"fwm__mark\" aria-hidden=\"true\"><span class=\"fwm__word\">{{ settings.wordmark | default: shop.name | default: settings.fallback }}</span></div>\n  <div class=\"fwm__base\">\n    <span>{{ settings.copyright }}</span>\n    <span class=\"fwm__prefs\"><span data-storelib-locale-current></span> <span data-storelib-currency-current></span></span>\n    {% if settings.legal_menu.links.size > 0 %}<ul class=\"fwm__legal\">{% for link in settings.legal_menu.links limit: 4 %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul>{% endif %}\n  </div>\n</footer>\n</template>\n\n<style scoped>\n.fwm, .fwm *, .fwm *::before, .fwm *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.fwm [hidden] { display: none !important; }\n.fwm { container-type: inline-size; overflow: hidden; padding: clamp(56px, 9vw, 120px) var(--theme-padding-x, 16px) 20px; background: var(--s-bg); color: var(--s-text); }\n.fwm__top { display: grid; gap: 20px; justify-items: start; max-width: 880px; }\n.fwm__line { margin: 0; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.75rem, 1.1rem + 3vw, 3.5rem); line-height: 1.02; letter-spacing: -0.03em; font-weight: 600; text-wrap: balance; }\n.fwm__cta { display: inline-flex; align-items: center; gap: 12px; min-height: 48px; color: inherit; font-size: 1.0625rem; font-weight: 600; text-decoration: underline; text-underline-offset: 6px; text-decoration-thickness: 1px; }\n.fwm__arrow { width: 22px; height: 1.5px; background: currentColor; position: relative; }\n.fwm__arrow::after { content: \"\"; position: absolute; right: 0; top: 50%; width: 9px; height: 9px; margin-top: -4.5px; border-top: 1.5px solid currentColor; border-right: 1.5px solid currentColor; transform: rotate(45deg); }\n.fwm__row { display: grid; gap: 8px; margin-top: clamp(40px, 7vw, 96px); padding-top: 16px; border-top: 1px solid var(--s-border); }\n.fwm__links, .fwm__legal { display: flex; flex-wrap: wrap; gap: 0 22px; margin: 0; padding: 0; list-style: none; }\n.fwm__links a, .fwm__legal a { display: inline-flex; align-items: center; min-height: 44px; color: inherit; text-decoration: none; }\n.fwm__links a:hover, .fwm__legal a:hover { text-decoration: underline; text-underline-offset: 4px; }\n.fwm__mark { margin: clamp(24px, 5vw, 56px) 0 0; overflow: hidden; }\n.fwm__word { display: block; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: min(40cqi, calc(var(--fwm-fill, 96) * 1cqi / (max(var(--fwm-chars, 8), 2) * 0.5))); font-weight: var(--fwm-weight, 800); line-height: 0.82; letter-spacing: -0.06em; white-space: nowrap; overflow: hidden; text-overflow: clip; padding-bottom: 0.14em; margin-bottom: -0.1em; }\n.fwm__base { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 4px 24px; margin-top: 16px; font-size: 0.875rem; }\n.fwm__prefs:has(> span:empty + span:empty) { display: none; }\n.fwm :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .fwm[data-reveal=\"true\"]:not([data-motion=\"off\"]) .fwm__word { animation: fwm-rise linear both; animation-timeline: view(); animation-range: entry 0% cover 40%; }\n    @keyframes fwm-rise { from { transform: translateY(calc(70% * var(--m-k, 1))); opacity: 0.2; } }\n  }\n}\n@media (prefers-reduced-motion: no-preference) { .fwm__cta .fwm__arrow { transition: transform var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease); } .fwm__cta:hover .fwm__arrow { transform: translateX(var(--t-motion-lift, 4px)); } }\n@media (prefers-reduced-motion: reduce) { .fwm__word, .fwm__arrow { animation: none; transition: none; } }\n@container (min-width: 760px) {\n  .fwm__row { grid-template-columns: minmax(0, 1fr) auto; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_footer_wordmark\",\n  \"name\": \"Giant wordmark footer\",\n  \"kind\": \"footer\",\n  \"enabled_on\": { \"groups\": [\"footer\"] },\n  \"settings\": [\n    { \"type\": \"header\", \"id\": \"hdr_top\", \"label\": \"Top\" },\n    { \"type\": \"text\", \"id\": \"line\", \"label\": \"Line\", \"default\": \"Made slowly, sent quickly.\" },\n    { \"type\": \"text\", \"id\": \"link_label\", \"label\": \"Link\", \"default\": \"Get in touch\" },\n    { \"type\": \"url\", \"id\": \"link_url\", \"label\": \"Link goes to\", \"default\": \"/contact\" },\n    { \"type\": \"header\", \"id\": \"hdr_menus\", \"label\": \"Menus\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"footer\" },\n    { \"type\": \"link_list\", \"id\": \"legal_menu\", \"label\": \"Bottom links\", \"default\": \"\" },\n    { \"type\": \"header\", \"id\": \"hdr_mark\", \"label\": \"Wordmark\" },\n    { \"type\": \"text\", \"id\": \"wordmark\", \"label\": \"Words (empty for the shop name)\", \"default\": \"\" },\n    { \"type\": \"range\", \"id\": \"size\", \"label\": \"How much of the width it fills\", \"min\": 40, \"max\": 100, \"step\": 2, \"unit\": \"%\", \"default\": 96 },\n    { \"type\": \"text\", \"id\": \"fallback\", \"label\": \"Words when there is no shop name\", \"default\": \"Studio\" },\n    { \"type\": \"select\", \"id\": \"weight\", \"label\": \"Weight\", \"default\": \"800\", \"options\": [{ \"label\": \"Regular\", \"value\": \"400\" }, { \"label\": \"Semibold\", \"value\": \"600\" }, { \"label\": \"Heavy\", \"value\": \"800\" }] },\n    { \"type\": \"checkbox\", \"id\": \"reveal\", \"label\": \"Rise as it comes into view\", \"default\": true },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Footer\" },\n    { \"type\": \"text\", \"id\": \"copyright\", \"label\": \"Bottom line\", \"default\": \"Studio of one, since 2019\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"social\", \"name\": \"Social link\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"label\", \"label\": \"Name\", \"default\": \"Instagram\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Address\", \"default\": \"https://instagram.com\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Giant wordmark footer\", \"blocks\": [\n    { \"type\": \"social\", \"settings\": { \"label\": \"Instagram\", \"url\": \"https://instagram.com\" } },\n    { \"type\": \"social\", \"settings\": { \"label\": \"Pinterest\", \"url\": \"https://pinterest.com\" } },\n    { \"type\": \"social\", \"settings\": { \"label\": \"Newsletter\", \"url\": \"/contact\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_header_announce.storelib",
  "source": "{# example\ntitle: Header with an announcement bar that rotates, scrolls or stays\nsummary: Chrome kit header. A thin bar of the creator's own messages above the header (up to five blocks, each with an optional link) shown one after another, as a moving line, or side by side, then a bar with the menu inline, the language and currency switches as a compact drop down, search and bag. The bar's style, speed, colours (its own scheme), and whether the switches show are settings; everything stops for reduced motion and while hovered or focused.\ntags: chrome kit, header, announcement bar, announcement, promo bar, ticker, marquee, rotating messages, free shipping message, locale, currency, language, own chrome, site header\n#}\n<template>\n<header class=\"han\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  {% if section.blocks.size > 0 %}\n  <div class=\"han__ann\" data-n=\"{{ section.blocks.size }}\" data-style=\"{{ settings.bar_style }}\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.bar_scheme }}\" style=\"--a-bg: {{ settings.bar_scheme.bg }}; --a-text: {{ settings.bar_scheme.text }}; --n: {{ section.blocks.size }}; --step: {{ settings.seconds }}s;\" aria-label=\"{{ settings.bar_label }}\" role=\"region\">\n    <ul class=\"han__msgs\">\n      {% for block in section.blocks %}\n      <li class=\"han__msg\" style=\"--i: {{ forloop.index0 }};\" data-block-id=\"{{ block.id }}\">{% if block.settings.url %}<a href=\"{{ block.settings.url | url }}\">{{ block.settings.text }}</a>{% else %}<span>{{ block.settings.text }}</span>{% endif %}</li>\n      {% endfor %}\n    </ul>\n  </div>\n  {% endif %}\n  <div class=\"han__bar\">\n    <button class=\"han__tool han__burger\" type=\"button\" data-storelib-menu=\"{{ settings.menu.handle }}\">{{ settings.menu_label }}</button>\n    <a class=\"han__logo\" href=\"{{ routes.root_url }}\">{% if theme.logo.url %}<img src=\"{{ theme.logo.url }}\" alt=\"{{ shop.name }}\" width=\"150\" height=\"40\">{% else %}{{ shop.name | default: settings.brand }}{% endif %}</a>\n    <nav class=\"han__nav\" aria-label=\"{{ settings.nav_label }}\">\n      <ul>{% for link in settings.menu.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul>\n    </nav>\n    <div class=\"han__tools\">\n      {% if settings.show_switches %}\n      <details class=\"han__pick\" data-storelib-locale-list>\n        <summary class=\"han__tool\"><span data-storelib-locale-current>{{ settings.language_label }}</span></summary>\n        <div class=\"han__menu\"><button class=\"han__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n      </details>\n      <details class=\"han__pick\" data-storelib-currency-list>\n        <summary class=\"han__tool\"><span data-storelib-currency-current>{{ settings.currency_label }}</span></summary>\n        <div class=\"han__menu\"><button class=\"han__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n      </details>\n      {% endif %}\n      <a class=\"han__tool\" href=\"{{ routes.search_url }}\" data-storelib-search>{{ settings.search_label }}</a>\n      <a class=\"han__tool\" href=\"{{ routes.cart_url }}\" data-storelib-cart>{{ settings.cart_label }} <span class=\"han__count\" data-storelib-cart-count></span></a>\n    </div>\n  </div>\n</header>\n</template>\n\n<style scoped>\n.han, .han *, .han *::before, .han *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.han [hidden] { display: none !important; }\n.han { position: relative; z-index: 40; background: var(--s-bg); color: var(--s-text); border-bottom: 1px solid var(--s-border); }\n.han__ann { position: relative; overflow: hidden; background: var(--a-bg); color: var(--a-text); font-size: 0.875rem; }\n.han__msgs { display: grid; margin: 0; padding: 0; list-style: none; }\n.han__msg { grid-area: 1 / 1; display: flex; align-items: center; justify-content: center; min-height: 40px; padding: 0 16px; text-align: center; }\n.han__msg:not(:first-child) { visibility: hidden; }\n.han__msg a { display: inline-flex; align-items: center; min-height: 40px; color: inherit; text-underline-offset: 3px; }\n.han__ann[data-style=\"row\"] .han__msgs { display: flex; flex-wrap: wrap; justify-content: center; gap: 0 32px; }\n.han__ann[data-style=\"row\"] .han__msg { grid-area: auto; visibility: visible; }\n.han__bar { display: flex; align-items: center; gap: 12px; min-height: 64px; padding: 0 var(--theme-padding-x, 16px); }\n.han__logo { display: inline-flex; align-items: center; min-height: 44px; margin-right: auto; color: var(--s-heading); text-decoration: none; font-family: var(--theme-font-heading), sans-serif; font-size: 1.375rem; font-weight: 700; letter-spacing: -0.02em; }\n.han__logo img { display: block; width: auto; height: 34px; }\n.han__nav { display: none; }\n.han__nav ul { display: flex; gap: 4px; margin: 0; padding: 0; list-style: none; }\n.han__nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 0 10px; color: inherit; text-decoration: none; }\n.han__nav a:hover { text-decoration: underline; text-underline-offset: 6px; }\n.han__tools { display: flex; align-items: center; gap: 2px; }\n.han__tool { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; min-width: 44px; padding: 0 8px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: none; cursor: pointer; list-style: none; }\n.han__tool::-webkit-details-marker { display: none; }\n.han__count[data-count=\"0\"] { display: none; }\n.han__pick { position: relative; display: none; }\n.han__menu { position: absolute; top: 100%; right: 0; display: grid; min-width: 160px; padding: 6px; border: 1px solid var(--s-border); background: var(--s-bg); }\n.han__opt { min-height: 44px; padding: 0 10px; border: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }\n.han__opt[aria-current=\"true\"] { text-decoration: underline; }\n.han :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  /* One after another: each message has its slice of one cycle (n messages, n slices); keyframe stops cannot be computed, so there is one set per count. */\n  .han__ann[data-style=\"rotate\"]:not([data-motion=\"off\"]):not([data-n=\"1\"]) .han__msg { visibility: visible; opacity: 0; animation: han-rot-5 calc(var(--n) * var(--step)) linear infinite; animation-delay: calc(var(--i) * var(--step)); }\n  .han__ann[data-n=\"2\"] .han__msg { animation-name: han-rot-2 !important; }\n  .han__ann[data-n=\"3\"] .han__msg { animation-name: han-rot-3 !important; }\n  .han__ann[data-n=\"4\"] .han__msg { animation-name: han-rot-4 !important; }\n  .han__ann[data-style=\"rotate\"]:is(:hover, :focus-within) .han__msg { animation-play-state: paused; }\n  @keyframes han-rot-2 { 0% { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 0.33 * var(--m-k, 1))); } 3%, 47% { opacity: 1; transform: none; } 50%, 100% { opacity: 0; } }\n  @keyframes han-rot-3 { 0% { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 0.33 * var(--m-k, 1))); } 3%, 30% { opacity: 1; transform: none; } 33.34%, 100% { opacity: 0; } }\n  @keyframes han-rot-4 { 0% { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 0.33 * var(--m-k, 1))); } 2%, 23% { opacity: 1; transform: none; } 25%, 100% { opacity: 0; } }\n  @keyframes han-rot-5 { 0% { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 0.33 * var(--m-k, 1))); } 2%, 18% { opacity: 1; transform: none; } 20%, 100% { opacity: 0; } }\n  .han__ann[data-style=\"scroll\"]:not([data-motion=\"off\"]) .han__msgs { display: flex; width: max-content; gap: 48px; padding-left: 100%; animation: han-scroll calc(var(--n) * var(--step) * 2 / max(var(--m-k, 1), 0.2)) linear infinite; }\n  .han__ann[data-style=\"scroll\"]:not([data-motion=\"off\"]) .han__msg { grid-area: auto; visibility: visible; white-space: nowrap; }\n  .han__ann[data-style=\"scroll\"]:not([data-motion=\"off\"]):is(:hover, :focus-within) .han__msgs { animation-play-state: paused; }\n  @keyframes han-scroll { to { transform: translateX(-100%); } }\n}\n@media (prefers-reduced-motion: reduce) { .han__msgs, .han__msg { animation: none; } }\n@media (min-width: 990px) {\n  .han__burger { display: none; }\n  .han__nav { display: block; order: 0; }\n  .han__logo { margin-right: 24px; }\n  .han__tools { margin-left: auto; }\n  .han__pick { display: block; }\n  .han__pick[hidden] { display: none; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_header_announce\",\n  \"name\": \"Header with announcement bar\",\n  \"kind\": \"header\",\n  \"enabled_on\": { \"groups\": [\"header\"] },\n  \"settings\": [\n    { \"type\": \"header\", \"id\": \"hdr_bar\", \"label\": \"Announcement bar\" },\n    { \"type\": \"select\", \"id\": \"bar_style\", \"label\": \"Messages\", \"default\": \"rotate\", \"options\": [{ \"label\": \"One after another\", \"value\": \"rotate\" }, { \"label\": \"A moving line\", \"value\": \"scroll\" }, { \"label\": \"Side by side\", \"value\": \"row\" }] },\n    { \"type\": \"range\", \"id\": \"seconds\", \"label\": \"Seconds per message\", \"min\": 2, \"max\": 10, \"step\": 1, \"unit\": \"s\", \"default\": 5 },\n    { \"type\": \"color_scheme\", \"id\": \"bar_scheme\", \"label\": \"Bar colours\", \"default\": \"site\" },\n    { \"type\": \"text\", \"id\": \"bar_label\", \"label\": \"Bar name (read aloud)\", \"default\": \"News\" },\n    { \"type\": \"header\", \"id\": \"hdr_menu\", \"label\": \"Menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"main-menu\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no logo\", \"default\": \"Home\" },\n    { \"type\": \"checkbox\", \"id\": \"show_switches\", \"label\": \"Show language and currency\", \"default\": true },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Main\" },\n    { \"type\": \"text\", \"id\": \"menu_label\", \"label\": \"Menu button\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"search_label\", \"label\": \"Search\", \"default\": \"Search\" },\n    { \"type\": \"text\", \"id\": \"cart_label\", \"label\": \"Bag\", \"default\": \"Bag\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency\", \"default\": \"Currency\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 20, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"message\", \"name\": \"Message\", \"limit\": 5, \"settings\": [\n      { \"type\": \"text\", \"id\": \"text\", \"label\": \"Message\", \"default\": \"Free delivery on orders over 50\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link (optional)\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Header with announcement bar\", \"blocks\": [\n    { \"type\": \"message\", \"settings\": { \"text\": \"Free delivery on orders over 50\" } },\n    { \"type\": \"message\", \"settings\": { \"text\": \"New pieces every first Friday\", \"url\": \"/shop\" } },\n    { \"type\": \"message\", \"settings\": { \"text\": \"Gift wrapping on request, no charge\", \"url\": \"/about\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_header_mega.storelib",
  "source": "{# example\ntitle: Mega menu header with link columns, image cards and featured products\nsummary: Chrome kit header. Each top link of the site's menu with sub links opens a full width mega panel (a popover: Escape and a press outside close it): its sub links as columns with their own links underneath, then image cards and the creator's chosen products (product_list) for that panel, matched by the top link's name. Cards and product rows are blocks with filled presets. On phones the menu button opens the site's own drawer. Panel width, card ratio, how many columns and motion are settings.\ntags: chrome kit, header, mega menu, megamenu, dropdown, image cards, featured products, columns, navigation, popover, own chrome, site header, store header\n#}\n<template>\n<header class=\"hmg\" data-ratio=\"{{ settings.card_ratio }}\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --hmg-h: {{ settings.bar_height }}px; --hmg-logo: {{ settings.logo_height }}px; --hmg-cols: {{ settings.columns }}; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"hmg__bar\">\n    <a class=\"hmg__logo\" href=\"{{ routes.root_url }}\">{% if theme.logo.url %}<img src=\"{{ theme.logo.url }}\" alt=\"{{ shop.name }}\" width=\"160\" height=\"40\">{% else %}{{ shop.name | default: settings.brand }}{% endif %}</a>\n    <nav class=\"hmg__nav\" aria-label=\"{{ settings.nav_label }}\">\n      <ul class=\"hmg__tops\">\n        {% for link in settings.menu.links %}\n        <li>\n          {% if link.links.size > 0 %}\n          <button class=\"hmg__top\" type=\"button\" popovertarget=\"hmg-{{ section.id }}-{{ forloop.index }}\">{{ link.title }}</button>\n          <div class=\"hmg__panel\" id=\"hmg-{{ section.id }}-{{ forloop.index }}\" popover>\n            <div class=\"hmg__in\">\n              <div class=\"hmg__cols\">\n                {% for child in link.links %}\n                <div class=\"hmg__col\" style=\"--i: {{ forloop.index }};\">\n                  <a class=\"hmg__col-h\" href=\"{{ child.url }}\">{{ child.title }}</a>\n                  {% if child.links.size > 0 %}<ul>{% for leaf in child.links %}<li><a href=\"{{ leaf.url }}\">{{ leaf.title }}</a></li>{% endfor %}</ul>{% endif %}\n                </div>\n                {% endfor %}\n                <a class=\"hmg__all\" href=\"{{ link.url }}\">{{ settings.all_prefix }} {{ link.title }}</a>\n              </div>\n              <div class=\"hmg__feature\">\n                {% for block in section.blocks %}\n                {% if block.settings.under == link.title or block.settings.under == \"\" %}\n                {% if block.type == \"card\" %}\n                <a class=\"hmg__card\" href=\"{{ block.settings.url | url }}\" data-block-id=\"{{ block.id }}\">\n                  <span class=\"hmg__crop\">{% if block.settings.image %}<img src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"800\" height=\"1000\" loading=\"lazy\">{% else %}<span class=\"hmg__tone\" aria-hidden=\"true\"></span>{% endif %}</span>\n                  <span class=\"hmg__card-t\">{{ block.settings.title }}</span>\n                  {% if block.settings.text %}<span class=\"hmg__card-x\">{{ block.settings.text }}</span>{% endif %}\n                </a>\n                {% elsif block.type == \"products\" %}\n                <div class=\"hmg__prods\" data-block-id=\"{{ block.id }}\">\n                  <p class=\"hmg__prods-h\">{{ block.settings.heading }}</p>\n                  <ul>\n                    {% for p in block.settings.products %}\n                    <li><a class=\"hmg__prod\" href=\"{{ p.settings.url | url }}\">{% if p.settings.image %}<img src=\"{{ p.settings.image | asset }}\" alt=\"{{ p.settings.title }}\" width=\"120\" height=\"150\" loading=\"lazy\">{% endif %}<span>{{ p.settings.title }}</span><span class=\"hmg__price\">{{ p.settings.price }}</span></a></li>\n                    {% else %}\n                    {% if page.in_editor %}<li class=\"hmg__hint\">Pick products for this row in the sidebar</li>{% endif %}\n                    {% endfor %}\n                  </ul>\n                </div>\n                {% endif %}\n                {% endif %}\n                {% endfor %}\n              </div>\n            </div>\n          </div>\n          {% else %}\n          <a class=\"hmg__top\" href=\"{{ link.url }}\">{{ link.title }}</a>\n          {% endif %}\n        </li>\n        {% endfor %}\n      </ul>\n    </nav>\n    <div class=\"hmg__tools\">\n      <a class=\"hmg__tool\" href=\"{{ routes.search_url }}\" data-storelib-search><svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"6.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M16 16l4.5 4.5\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg><span class=\"hmg__word\">{{ settings.search_label }}</span></a>\n      <a class=\"hmg__tool\" href=\"{{ routes.cart_url }}\" data-storelib-cart>{{ settings.cart_label }} <span class=\"hmg__count\" data-storelib-cart-count></span></a>\n      <button class=\"hmg__tool hmg__burger\" type=\"button\" data-storelib-menu=\"{{ settings.menu.handle }}\">{{ settings.menu_label }}</button>\n    </div>\n  </div>\n</header>\n</template>\n\n<style scoped>\n.hmg, .hmg *, .hmg *::before, .hmg *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.hmg [hidden] { display: none !important; }\n.hmg { position: relative; z-index: 40; background: var(--s-bg); color: var(--s-text); border-bottom: 1px solid var(--s-border); }\n.hmg__bar { display: flex; align-items: center; gap: 16px; min-height: var(--hmg-h); padding: 0 var(--theme-padding-x, 16px); }\n.hmg__logo { display: inline-flex; align-items: center; min-height: 44px; color: var(--s-heading); text-decoration: none; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.25rem, 1rem + 0.8vw, 1.75rem); font-weight: 700; letter-spacing: -0.03em; }\n.hmg__logo img { display: block; width: auto; height: var(--hmg-logo); }\n.hmg__nav { display: none; }\n.hmg__tops { display: flex; gap: 2px; margin: 0; padding: 0; list-style: none; }\n.hmg__top { display: inline-flex; align-items: center; min-height: 44px; padding: 0 12px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; font-weight: 500; text-decoration: none; cursor: pointer; }\n.hmg__top:hover, .hmg__top:focus-visible { text-decoration: underline; text-underline-offset: 8px; text-decoration-thickness: 2px; }\n.hmg__panel { position: fixed; inset: var(--hmg-h) 0 auto; width: 100%; max-width: none; max-height: calc(100svh - var(--hmg-h)); margin: 0; padding: 0; overflow-y: auto; border: 0; border-top: 1px solid var(--s-border); border-bottom: 1px solid var(--s-border); background: var(--s-bg); color: var(--s-text); }\n.hmg__in { display: grid; gap: 32px; max-width: var(--theme-page-width, 1440px); margin: 0 auto; padding: 32px var(--theme-padding-x, 16px) 40px; }\n.hmg__cols { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 28px 24px; align-content: start; }\n.hmg__col-h { display: block; margin-bottom: 10px; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: 1.125rem; font-weight: 600; text-decoration: none; }\n.hmg__col ul { margin: 0; padding: 0; list-style: none; }\n.hmg__col li a { display: block; padding: 6px 0; color: inherit; text-decoration: none; }\n.hmg__col a:hover { text-decoration: underline; }\n.hmg__all { grid-column: 1 / -1; align-self: end; color: inherit; font-weight: 500; text-underline-offset: 4px; }\n.hmg__feature { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; align-content: start; }\n.hmg__card { display: grid; gap: 8px; color: inherit; text-decoration: none; }\n.hmg__crop { display: block; overflow: hidden; aspect-ratio: 4 / 5; background: var(--s-border); }\n.hmg[data-ratio=\"square\"] .hmg__crop { aspect-ratio: 1; }\n.hmg[data-ratio=\"wide\"] .hmg__crop { aspect-ratio: 3 / 2; }\n.hmg__crop img, .hmg__tone { display: block; width: 100%; height: 100%; object-fit: cover; }\n.hmg__tone { background: linear-gradient(160deg, var(--s-border), transparent); }\n.hmg__card-t { font-family: var(--theme-font-heading), sans-serif; font-size: 1.0625rem; font-weight: 600; color: var(--s-heading); }\n.hmg__card-x { font-size: 0.875rem; }\n.hmg__prods { grid-column: 1 / -1; }\n.hmg__prods-h { margin: 0 0 8px; font-weight: 600; }\n.hmg__prods ul { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }\n.hmg__prod { display: grid; grid-template-columns: 48px minmax(0, 1fr) auto; gap: 12px; align-items: center; min-height: 44px; color: inherit; text-decoration: none; }\n.hmg__prod img { width: 48px; height: 60px; object-fit: cover; }\n.hmg__price { font-variant-numeric: tabular-nums; }\n.hmg__hint { opacity: 0.7; }\n.hmg__tools { display: flex; align-items: center; gap: 2px; margin-left: auto; }\n.hmg__tool { display: inline-flex; align-items: center; gap: 6px; min-width: 44px; min-height: 44px; justify-content: center; padding: 0 10px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: none; cursor: pointer; }\n.hmg__word { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }\n.hmg__count { font-variant-numeric: tabular-nums; }\n.hmg__count[data-count=\"0\"] { display: none; }\n.hmg :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  .hmg:not([data-motion=\"off\"]) .hmg__panel:popover-open .hmg__col, .hmg:not([data-motion=\"off\"]) .hmg__panel:popover-open .hmg__card { animation: hmg-in var(--t-motion-duration, 650ms) var(--t-motion-ease, ease-out) both; animation-delay: calc(var(--i, 1) * var(--t-motion-stagger, 65ms)); }\n  .hmg:not([data-motion=\"off\"]) .hmg__card img { transition: transform calc(var(--t-motion-hover, 200ms) * 2) var(--t-motion-ease-ui, ease); }\n  .hmg:not([data-motion=\"off\"]) .hmg__card:hover img { transform: scale(calc(1 + (var(--t-motion-scale, 1.06) - 1) * var(--m-k, 1))); }\n  @keyframes hmg-in { from { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 0.5 * var(--m-k, 1))); } }\n}\n@media (prefers-reduced-motion: reduce) { .hmg__col, .hmg__card { animation: none; } }\n@media (min-width: 990px) {\n  .hmg__nav { display: block; }\n  .hmg__burger { display: none; }\n  .hmg__in { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: 48px; }\n  .hmg__cols { grid-template-columns: repeat(var(--hmg-cols, 3), minmax(0, 1fr)); }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_header_mega\",\n  \"name\": \"Mega menu header\",\n  \"kind\": \"header\",\n  \"enabled_on\": { \"groups\": [\"header\"] },\n  \"settings\": [\n    { \"type\": \"header\", \"id\": \"hdr_menu\", \"label\": \"Menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu (top links with sub links open a panel)\", \"default\": \"main-menu\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no logo\", \"default\": \"Home\" },\n    { \"type\": \"text\", \"id\": \"all_prefix\", \"label\": \"Link to the whole section starts with\", \"default\": \"All of\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"range\", \"id\": \"bar_height\", \"label\": \"Bar height\", \"min\": 56, \"max\": 96, \"step\": 4, \"unit\": \"px\", \"default\": 68 },\n    { \"type\": \"range\", \"id\": \"logo_height\", \"label\": \"Logo height\", \"min\": 20, \"max\": 64, \"step\": 2, \"unit\": \"px\", \"default\": 30 },\n    { \"type\": \"range\", \"id\": \"columns\", \"label\": \"Link columns in a panel\", \"min\": 2, \"max\": 4, \"step\": 1, \"default\": 3 },\n    { \"type\": \"select\", \"id\": \"card_ratio\", \"label\": \"Card pictures\", \"default\": \"portrait\", \"options\": [{ \"label\": \"Portrait\", \"value\": \"portrait\" }, { \"label\": \"Square\", \"value\": \"square\" }, { \"label\": \"Wide\", \"value\": \"wide\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Main\" },\n    { \"type\": \"text\", \"id\": \"menu_label\", \"label\": \"Menu button\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"search_label\", \"label\": \"Search (read aloud)\", \"default\": \"Search\" },\n    { \"type\": \"text\", \"id\": \"cart_label\", \"label\": \"Bag\", \"default\": \"Bag\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"card\", \"name\": \"Image card\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"under\", \"label\": \"Show in the panel of (top link name, empty for every panel)\", \"default\": \"\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Picture description\", \"default\": \"\" },\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"New this season\" },\n      { \"type\": \"text\", \"id\": \"text\", \"label\": \"Line under it\", \"default\": \"\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link\", \"default\": \"/shop\" }\n    ] },\n    { \"type\": \"products\", \"name\": \"Featured products\", \"limit\": 2, \"settings\": [\n      { \"type\": \"text\", \"id\": \"under\", \"label\": \"Show in the panel of (top link name, empty for every panel)\", \"default\": \"\" },\n      { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Most loved\" },\n      { \"type\": \"product_list\", \"id\": \"products\", \"label\": \"Products\", \"limit\": 4 }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Mega menu header\", \"blocks\": [\n    { \"type\": \"card\", \"settings\": { \"under\": \"\", \"title\": \"New this season\", \"text\": \"The latest pieces, as they land\", \"url\": \"/shop\" } },\n    { \"type\": \"card\", \"settings\": { \"under\": \"\", \"title\": \"Our story\", \"text\": \"Who makes it and where\", \"url\": \"/about\" } },\n    { \"type\": \"products\", \"settings\": { \"under\": \"\", \"heading\": \"Most loved\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_header_minimal.storelib",
  "source": "{# example\ntitle: Minimal header with a full screen menu of its own\nsummary: Chrome kit header. Only the name, search, a bag count and one Menu button in the bar; the button opens the header's own full screen menu (data-storelib-menu-panel: a dialog with focus kept inside, Escape and its close button shut it) with the site's menu set huge on one side and a picture with a line and a link on the other, plus contact, socials and language and currency switches. Bar position, type size, picture, which parts show and motion strength are settings; social links are blocks.\ntags: chrome kit, header, minimal header, hamburger, full screen menu, fullscreen menu, overlay menu, menu drawer, studio, agency, portfolio, own chrome, site header\n#}\n<template>\n<header class=\"hmn\" data-pos=\"{{ settings.position }}\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --hmn-big: {{ settings.menu_size }}; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"hmn__bar\">\n    <a class=\"hmn__logo\" href=\"{{ routes.root_url }}\">{% if theme.logo.url %}<img src=\"{{ theme.logo.url }}\" alt=\"{{ shop.name }}\" width=\"140\" height=\"36\">{% else %}{{ shop.name | default: settings.brand }}{% endif %}</a>\n    {% if settings.show_search %}<a class=\"hmn__btn hmn__bag\" href=\"{{ routes.search_url }}\" data-storelib-search>{{ settings.search_label }}</a>{% endif %}\n    <a class=\"hmn__btn hmn__bag\" href=\"{{ routes.cart_url }}\" data-storelib-cart>{{ settings.cart_label }} <span class=\"hmn__count\" data-storelib-cart-count></span></a>\n    <button class=\"hmn__btn hmn__open\" type=\"button\" data-storelib-menu=\"{{ settings.menu.handle }}\"><span class=\"hmn__dots\" aria-hidden=\"true\"></span>{{ settings.menu_label }}</button>\n  </div>\n  <div class=\"hmn__panel\" data-storelib-menu-panel aria-label=\"{{ settings.menu_label }}\">\n    <div class=\"hmn__top\">\n      <span class=\"hmn__logo\">{{ shop.name | default: settings.brand }}</span>\n      <button class=\"hmn__btn\" type=\"button\" data-storelib-menu-close>{{ settings.close_label }}</button>\n    </div>\n    <div class=\"hmn__body\">\n      <nav class=\"hmn__nav\" aria-label=\"{{ settings.nav_label }}\">\n        <ol class=\"hmn__list\">\n          {% for link in settings.menu.links %}\n          <li style=\"--i: {{ forloop.index }};\"><a class=\"hmn__big\" href=\"{{ link.url }}\"><span class=\"hmn__num\" aria-hidden=\"true\">{{ forloop.index }}</span>{{ link.title }}</a></li>\n          {% endfor %}\n        </ol>\n      </nav>\n      <aside class=\"hmn__side\">\n        {% if settings.show_picture and settings.image %}\n        <a class=\"hmn__pic\" href=\"{{ settings.picture_url | url }}\"><img src=\"{{ settings.image | asset }}\" alt=\"{{ settings.image_alt }}\" width=\"900\" height=\"1100\" loading=\"lazy\"><span>{{ settings.picture_line }}</span></a>\n        {% endif %}\n        {% if settings.contact %}<p class=\"hmn__contact\">{{ settings.contact }}</p>{% endif %}\n        <ul class=\"hmn__social\">\n          {% for block in section.blocks %}<li data-block-id=\"{{ block.id }}\"><a href=\"{{ block.settings.url | url }}\" rel=\"me noopener\" target=\"_blank\">{{ block.settings.label }}</a></li>{% endfor %}\n        </ul>\n        <div class=\"hmn__prefs\">\n          <div class=\"hmn__pref\" data-storelib-locale-list><button class=\"hmn__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n          <div class=\"hmn__pref\" data-storelib-currency-list><button class=\"hmn__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n        </div>\n      </aside>\n    </div>\n  </div>\n</header>\n</template>\n\n<style scoped>\n.hmn, .hmn *, .hmn *::before, .hmn *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.hmn [hidden] { display: none !important; }\n.hmn { position: relative; z-index: 40; color: var(--s-text); }\n.hmn[data-pos=\"pinned\"] .hmn__bar { position: fixed; inset: 0 0 auto; }\n.hmn[data-pos=\"pinned\"]::after { content: \"\"; display: block; height: 64px; }\n.hmn__bar { display: flex; align-items: center; gap: 8px; min-height: 64px; padding: 0 var(--theme-padding-x, 16px); background: var(--s-bg); }\n.hmn__logo { display: inline-flex; align-items: center; min-height: 44px; margin-right: auto; color: var(--s-heading); text-decoration: none; font-family: var(--theme-font-heading), sans-serif; font-size: 1.25rem; font-weight: 700; letter-spacing: -0.02em; }\n.hmn__logo img { display: block; width: auto; height: 32px; }\n.hmn__btn { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; min-width: 44px; padding: 0 12px; border: 1px solid var(--s-border); background: var(--s-bg); color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: none; cursor: pointer; }\n.hmn__bag { border-color: transparent; }\n.hmn__count { font-variant-numeric: tabular-nums; }\n.hmn__count[data-count=\"0\"] { display: none; }\n.hmn__dots { width: 8px; height: 8px; background: currentColor; }\n.hmn__panel { position: fixed; inset: 0; z-index: 60; display: flex; flex-direction: column; padding: 0 var(--theme-padding-x, 16px) 24px; overflow-y: auto; background: var(--s-bg); color: var(--s-text); visibility: hidden; opacity: 0; }\n.hmn__panel[data-open=\"true\"] { visibility: visible; opacity: 1; }\n.hmn__top { display: flex; align-items: center; min-height: 64px; }\n.hmn__body { display: grid; gap: 40px; flex: 1; padding-top: 16px; }\n.hmn__list { margin: 0; padding: 0; list-style: none; }\n.hmn__big { display: flex; align-items: baseline; gap: 14px; padding: 4px 0; color: var(--s-heading); text-decoration: none; font-family: var(--theme-font-heading), sans-serif; font-size: calc(clamp(2.5rem, 1.2rem + 7vw, 7rem) * var(--hmn-big, 100) / 100); line-height: 0.98; letter-spacing: -0.04em; font-weight: 700; overflow-wrap: anywhere; }\n.hmn__num { font-family: var(--theme-font-body), sans-serif; font-size: 0.875rem; font-weight: 500; letter-spacing: 0; font-variant-numeric: tabular-nums; }\n.hmn__big:hover, .hmn__big:focus-visible { color: var(--s-accent); }\n.hmn__side { display: grid; gap: 20px; align-content: start; }\n.hmn__pic { display: grid; gap: 10px; color: inherit; text-decoration: none; }\n.hmn__pic img { display: block; width: 100%; height: auto; aspect-ratio: 4 / 5; object-fit: cover; }\n.hmn__contact { margin: 0; white-space: pre-line; }\n.hmn__social { display: flex; flex-wrap: wrap; gap: 4px 16px; margin: 0; padding: 0; list-style: none; }\n.hmn__social a { display: inline-flex; align-items: center; min-height: 44px; color: inherit; }\n.hmn__prefs { display: flex; flex-wrap: wrap; gap: 8px; }\n.hmn__pref { display: flex; flex-wrap: wrap; gap: 6px; }\n.hmn__opt { min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.hmn__opt[aria-current=\"true\"] { border-color: currentColor; }\n.hmn :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n@media (prefers-reduced-motion: no-preference) {\n  .hmn:not([data-motion=\"off\"]) .hmn__panel { transition: opacity calc(var(--t-motion-duration, 650ms) * 0.5) var(--t-motion-ease, ease-out), visibility 0s linear calc(var(--t-motion-duration, 650ms) * 0.5); }\n  .hmn:not([data-motion=\"off\"]) .hmn__panel[data-open=\"true\"] { transition-delay: 0s; }\n  .hmn:not([data-motion=\"off\"]) .hmn__panel[data-open=\"true\"] .hmn__list li { animation: hmn-up var(--t-motion-duration, 650ms) var(--t-motion-ease, ease-out) both; animation-delay: calc(var(--i, 1) * var(--t-motion-stagger, 65ms) + 80ms); }\n  .hmn:not([data-motion=\"off\"]) .hmn__panel[data-open=\"true\"] .hmn__side { animation: hmn-up var(--t-motion-duration, 650ms) var(--t-motion-ease, ease-out) 240ms both; }\n  @keyframes hmn-up { from { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 1.5 * var(--m-k, 1))); } }\n}\n@media (prefers-reduced-motion: reduce) { .hmn__panel, .hmn__list li, .hmn__side { transition: none; animation: none; } }\n@media (min-width: 900px) {\n  .hmn__body { grid-template-columns: minmax(0, 7fr) minmax(0, 4fr); gap: 64px; align-items: end; padding-bottom: 24px; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_header_minimal\",\n  \"name\": \"Minimal header and full screen menu\",\n  \"kind\": \"header\",\n  \"enabled_on\": { \"groups\": [\"header\"] },\n  \"settings\": [\n    { \"type\": \"header\", \"id\": \"hdr_menu\", \"label\": \"Menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"main-menu\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no logo\", \"default\": \"Studio\" },\n    { \"type\": \"range\", \"id\": \"menu_size\", \"label\": \"Menu type size\", \"min\": 60, \"max\": 130, \"step\": 5, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_side\", \"label\": \"Beside the menu\" },\n    { \"type\": \"checkbox\", \"id\": \"show_picture\", \"label\": \"Show a picture\", \"default\": true },\n    { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n    { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Picture description\", \"default\": \"\" },\n    { \"type\": \"text\", \"id\": \"picture_line\", \"label\": \"Line under the picture\", \"default\": \"See the latest work\" },\n    { \"type\": \"url\", \"id\": \"picture_url\", \"label\": \"Picture goes to\", \"default\": \"/about\" },\n    { \"type\": \"textarea\", \"id\": \"contact\", \"label\": \"Contact lines\", \"default\": \"hello@studio.com\\nMonday to Friday, 9 to 6\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"select\", \"id\": \"position\", \"label\": \"Bar\", \"default\": \"pinned\", \"options\": [{ \"label\": \"Pinned to the top\", \"value\": \"pinned\" }, { \"label\": \"In the page\", \"value\": \"static\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Main\" },\n    { \"type\": \"text\", \"id\": \"menu_label\", \"label\": \"Menu button\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"cart_label\", \"label\": \"Bag\", \"default\": \"Bag\" },\n    { \"type\": \"checkbox\", \"id\": \"show_search\", \"label\": \"Show search\", \"default\": true },\n    { \"type\": \"text\", \"id\": \"search_label\", \"label\": \"Search\", \"default\": \"Search\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"social\", \"name\": \"Social link\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"label\", \"label\": \"Name\", \"default\": \"Instagram\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Address\", \"default\": \"https://instagram.com\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Minimal header and full screen menu\", \"blocks\": [\n    { \"type\": \"social\", \"settings\": { \"label\": \"Instagram\", \"url\": \"https://instagram.com\" } },\n    { \"type\": \"social\", \"settings\": { \"label\": \"Pinterest\", \"url\": \"https://pinterest.com\" } },\n    { \"type\": \"social\", \"settings\": { \"label\": \"TikTok\", \"url\": \"https://tiktok.com\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_header_overlay.storelib",
  "source": "{# example\ntitle: Header over the hero that turns solid on scroll\nsummary: Chrome kit header. Sits transparent over a full bleed first section with a soft scrim, then fills with the scheme's colour after the first scroll (a CSS scroll timeline, no script); drop down sub menus as popovers, search, bag with live count and a menu button that opens the site's own menu drawer through the hooks. Behaviour (over the hero, always solid and pinned, or in the page), logo size, text colour over the picture, which tools show and motion are settings.\ntags: chrome kit, header, transparent header, over hero, solid on scroll, sticky header, scroll timeline, dropdown, popover, own chrome, site header\n#}\n<template>\n<header class=\"hov\" data-mode=\"{{ settings.behaviour }}\" data-over=\"{{ settings.over_image_text }}\" data-tools=\"{{ settings.tool_style }}\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --hov-h: {{ settings.bar_height }}px; --hov-logo: {{ settings.logo_height }}px; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"hov__bar\">\n    <a class=\"hov__logo\" href=\"{{ routes.root_url }}\">{% if theme.logo.url %}<img src=\"{{ theme.logo.url }}\" alt=\"{{ shop.name }}\" width=\"160\" height=\"40\">{% else %}{{ shop.name | default: settings.brand }}{% endif %}</a>\n    <nav class=\"hov__nav\" aria-label=\"{{ settings.nav_label }}\">\n      <ul class=\"hov__links\">\n        {% for link in settings.menu.links %}\n        <li>\n          {% if link.links.size > 0 %}\n          <button class=\"hov__top\" type=\"button\" popovertarget=\"hov-{{ section.id }}-{{ forloop.index }}\">{{ link.title }}<svg class=\"hov__caret\" viewBox=\"0 0 12 12\" width=\"12\" height=\"12\" aria-hidden=\"true\"><path d=\"M2 4l4 4 4-4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg></button>\n          <div class=\"hov__drop\" id=\"hov-{{ section.id }}-{{ forloop.index }}\" popover>\n            <a class=\"hov__drop-all\" href=\"{{ link.url }}\">{{ link.title }}</a>\n            <ul class=\"hov__drop-list\">{% for child in link.links %}<li style=\"--i: {{ forloop.index }};\"><a href=\"{{ child.url }}\">{{ child.title }}</a></li>{% endfor %}</ul>\n          </div>\n          {% else %}\n          <a class=\"hov__top\" href=\"{{ link.url }}\">{{ link.title }}</a>\n          {% endif %}\n        </li>\n        {% endfor %}\n      </ul>\n    </nav>\n    <div class=\"hov__tools\">\n      {% if settings.show_search %}<a class=\"hov__tool\" href=\"{{ routes.search_url }}\" data-storelib-search aria-label=\"{{ settings.search_label }}\"><svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"6.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M16 16l4.5 4.5\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg><span class=\"hov__word\">{{ settings.search_label }}</span></a>{% endif %}\n      {% if settings.show_account %}<a class=\"hov__tool hov__wide\" href=\"{{ routes.account_url }}\">{{ settings.account_label }}</a>{% endif %}\n      <a class=\"hov__tool\" href=\"{{ routes.cart_url }}\" data-storelib-cart aria-label=\"{{ settings.cart_label }}\"><svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" aria-hidden=\"true\"><path d=\"M5 8h14l-1.2 12H6.2L5 8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M9 8a3 3 0 016 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg><span class=\"hov__word\">{{ settings.cart_label }}</span><span class=\"hov__count\" data-storelib-cart-count></span></a>\n      <button class=\"hov__tool hov__burger\" type=\"button\" data-storelib-menu=\"{{ settings.menu.handle }}\" aria-label=\"{{ settings.menu_label }}\"><span class=\"hov__lines\" aria-hidden=\"true\"></span><span class=\"hov__word\">{{ settings.menu_label }}</span></button>\n    </div>\n  </div>\n</header>\n<div class=\"hov-space\" data-mode=\"{{ settings.behaviour }}\" style=\"--hov-h: {{ settings.bar_height }}px;\" aria-hidden=\"true\"></div>\n</template>\n\n<style scoped>\n.hov, .hov *, .hov *::before, .hov *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.hov [hidden] { display: none !important; }\n.hov { position: relative; z-index: 40; background: var(--s-bg); color: var(--s-text); border-bottom: 1px solid var(--s-border); }\n.hov[data-mode=\"overlay\"], .hov[data-mode=\"pinned\"] { position: fixed; inset: 0 0 auto; }\n.hov-space { display: none; }\n.hov-space[data-mode=\"pinned\"] { display: block; height: var(--hov-h); }\n.hov__bar { display: flex; align-items: center; gap: 12px; min-height: var(--hov-h); padding: 0 var(--theme-padding-x, 16px); max-width: var(--theme-page-width, 1440px); margin: 0 auto; }\n.hov__logo { display: inline-flex; align-items: center; min-height: 44px; margin-right: auto; color: inherit; text-decoration: none; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.125rem, 1rem + 0.6vw, 1.5rem); font-weight: 700; letter-spacing: -0.02em; }\n.hov__logo img { display: block; width: auto; height: var(--hov-logo); }\n.hov__nav { display: none; }\n.hov__links { display: flex; gap: 2px; margin: 0; padding: 0; list-style: none; }\n.hov__top { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 12px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: none; cursor: pointer; }\n.hov__caret { opacity: 0.7; }\n.hov__top:hover { text-decoration: underline; text-underline-offset: 6px; }\n.hov__drop { position: fixed; inset: var(--hov-h) auto auto 50%; translate: -50% 0; margin: 0; min-width: min(560px, calc(100% - 32px)); padding: 28px 32px 32px; border: 1px solid var(--s-border); background: var(--s-bg); color: var(--s-text); }\n.hov__drop-all { display: inline-block; margin-bottom: 16px; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.5rem, 1.1rem + 1.4vw, 2.25rem); letter-spacing: -0.02em; text-decoration: none; }\n.hov__drop-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 24px; margin: 0; padding: 0; list-style: none; }\n.hov__drop-list a { display: block; padding: 10px 0; color: inherit; text-decoration: none; border-bottom: 1px solid var(--s-border); }\n.hov__drop-list a:hover { text-decoration: underline; }\n.hov__tools { display: flex; align-items: center; gap: 2px; }\n.hov__tool { position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-width: 44px; min-height: 44px; padding: 0 8px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: none; cursor: pointer; }\n.hov__wide { display: none; }\n.hov[data-tools=\"icons\"] .hov__word { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }\n.hov[data-tools=\"words\"] .hov__tool svg { display: none; }\n.hov__count { min-width: 18px; padding: 0 5px; line-height: 18px; background: var(--s-accent); color: var(--s-bg); font-size: 0.75rem; text-align: center; font-variant-numeric: tabular-nums; }\n.hov[data-tools=\"icons\"] .hov__count { position: absolute; top: 6px; right: 2px; }\n.hov__count[data-count=\"0\"] { display: none; }\n.hov__lines { position: relative; display: block; width: 22px; height: 12px; border-top: 1.6px solid currentColor; border-bottom: 1.6px solid currentColor; }\n.hov :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }\n/* Over the first section: transparent with a scrim for contrast, then solid from the first 120px of scroll. Without scroll timelines it stays solid. */\n@supports (animation-timeline: scroll()) {\n  .hov[data-mode=\"overlay\"] { border-bottom-color: transparent; background: linear-gradient(to bottom, rgba(0, 0, 0, 0.42), transparent); color: var(--hov-over, #fff); animation: hov-solid linear both; animation-timeline: scroll(root); animation-range: 0 120px; }\n  .hov[data-mode=\"overlay\"][data-over=\"dark\"] { --hov-over: var(--s-heading); background: linear-gradient(to bottom, rgba(255, 255, 255, 0.5), transparent); }\n  .hov[data-mode=\"overlay\"] .hov__logo img { filter: var(--hov-logo-filter, none); }\n  @keyframes hov-solid { 99% { background-image: linear-gradient(transparent, transparent); } to { background: var(--s-bg); color: var(--s-text); border-bottom-color: var(--s-border); } }\n}\n@media (prefers-reduced-motion: no-preference) {\n  .hov:not([data-motion=\"off\"]) .hov__drop:popover-open .hov__drop-list li { animation: hov-in calc(var(--t-motion-duration, 650ms) * 0.6) var(--t-motion-ease, ease-out) both; animation-delay: calc(var(--i, 1) * var(--t-motion-stagger, 65ms) * 0.5); }\n  @keyframes hov-in { from { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 0.4 * var(--m-k, 1))); } }\n  .hov__top, .hov__tool { transition: opacity var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease); }\n}\n@media (prefers-reduced-motion: reduce) { .hov__drop-list li { animation: none; } }\n@media (min-width: 990px) {\n  .hov__nav { display: block; }\n  .hov__wide { display: inline-flex; }\n  .hov__burger { display: none; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_header_overlay\",\n  \"name\": \"Header over the hero\",\n  \"kind\": \"header\",\n  \"enabled_on\": { \"groups\": [\"header\"] },\n  \"settings\": [\n    { \"type\": \"header\", \"id\": \"hdr_menu\", \"label\": \"Menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"main-menu\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no logo\", \"default\": \"Home\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"select\", \"id\": \"behaviour\", \"label\": \"Behaviour\", \"default\": \"overlay\", \"options\": [{ \"label\": \"Over the first section, solid on scroll\", \"value\": \"overlay\" }, { \"label\": \"Solid and pinned to the top\", \"value\": \"pinned\" }, { \"label\": \"In the page\", \"value\": \"static\" }] },\n    { \"type\": \"select\", \"id\": \"over_image_text\", \"label\": \"Text over the picture\", \"default\": \"light\", \"options\": [{ \"label\": \"Light\", \"value\": \"light\" }, { \"label\": \"Dark\", \"value\": \"dark\" }] },\n    { \"type\": \"range\", \"id\": \"bar_height\", \"label\": \"Bar height\", \"min\": 56, \"max\": 104, \"step\": 4, \"unit\": \"px\", \"default\": 72 },\n    { \"type\": \"range\", \"id\": \"logo_height\", \"label\": \"Logo height\", \"min\": 20, \"max\": 72, \"step\": 2, \"unit\": \"px\", \"default\": 32 },\n    { \"type\": \"select\", \"id\": \"tool_style\", \"label\": \"Search and bag as\", \"default\": \"icons\", \"options\": [{ \"label\": \"Icons\", \"value\": \"icons\" }, { \"label\": \"Words\", \"value\": \"words\" }] },\n    { \"type\": \"checkbox\", \"id\": \"show_search\", \"label\": \"Show search\", \"default\": true },\n    { \"type\": \"checkbox\", \"id\": \"show_account\", \"label\": \"Show account link\", \"default\": false },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Main\" },\n    { \"type\": \"text\", \"id\": \"menu_label\", \"label\": \"Menu button\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"search_label\", \"label\": \"Search\", \"default\": \"Search\" },\n    { \"type\": \"text\", \"id\": \"cart_label\", \"label\": \"Bag\", \"default\": \"Bag\" },\n    { \"type\": \"text\", \"id\": \"account_label\", \"label\": \"Account\", \"default\": \"Account\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_header_shop.storelib",
  "source": "{# example\ntitle: Compact shop header with a search field and category tabs\nsummary: Chrome kit header for a shop with many products. A pinned bar with the name, a wide search field that opens the site's own search window, account and bag, and under it a row of category tabs from a menu (link_list) that scrolls sideways on phones with snap points; on scroll the top row slides away and the tabs stay (a CSS scroll timeline, no script). Tab style (underline, outline, filled), whether the top row collapses, a short promise line and colours are settings.\ntags: chrome kit, header, shop header, store header, sticky header, compact header, category tabs, tabs, search field, ecommerce, marketplace, grocery, own chrome, site header\n#}\n<template>\n<header class=\"hsh\" data-collapse=\"{{ settings.collapse }}\" data-tabs=\"{{ settings.tab_style }}\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }};\">\n  <div class=\"hsh__fix\">\n    <div class=\"hsh__row\">\n      <button class=\"hsh__icon hsh__burger\" type=\"button\" data-storelib-menu=\"{{ settings.categories.handle }}\" aria-label=\"{{ settings.menu_label }}\"><span class=\"hsh__lines\" aria-hidden=\"true\"></span></button>\n      <a class=\"hsh__logo\" href=\"{{ routes.root_url }}\">{% if theme.logo.url %}<img src=\"{{ theme.logo.url }}\" alt=\"{{ shop.name }}\" width=\"140\" height=\"36\">{% else %}{{ shop.name | default: settings.brand }}{% endif %}</a>\n      <a class=\"hsh__field\" href=\"{{ routes.search_url }}\" data-storelib-search=\"{{ settings.search_placeholder }}\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"6.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M16 16l4.5 4.5\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg><span>{{ settings.search_placeholder }}</span></a>\n      {% if settings.promise %}<p class=\"hsh__promise\">{{ settings.promise }}</p>{% endif %}\n      <a class=\"hsh__icon hsh__account\" href=\"{{ routes.account_url }}\">{{ settings.account_label }}</a>\n      <a class=\"hsh__icon hsh__bag\" href=\"{{ routes.cart_url }}\" data-storelib-cart>{{ settings.cart_label }}<span class=\"hsh__count\" data-storelib-cart-count></span></a>\n    </div>\n    <nav class=\"hsh__tabs\" aria-label=\"{{ settings.tabs_label }}\">\n      <ul>\n        {% for link in settings.categories.links %}<li><a class=\"hsh__tab\" href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}\n      </ul>\n    </nav>\n  </div>\n  <div class=\"hsh__space\" aria-hidden=\"true\"></div>\n</header>\n</template>\n\n<style scoped>\n.hsh, .hsh *, .hsh *::before, .hsh *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.hsh [hidden] { display: none !important; }\n.hsh { --hsh-row: 60px; --hsh-tabs: 48px; position: relative; z-index: 40; color: var(--s-text); }\n.hsh__fix { position: fixed; inset: 0 0 auto; background: var(--s-bg); border-bottom: 1px solid var(--s-border); }\n.hsh__space { height: calc(var(--hsh-row) + var(--hsh-tabs) + 52px); }\n.hsh__row { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: \"burger logo bag\" \"field field field\"; align-items: center; gap: 4px 8px; padding: 6px var(--theme-padding-x, 16px); }\n.hsh__burger { grid-area: burger; }\n.hsh__logo { grid-area: logo; display: inline-flex; align-items: center; min-height: 44px; color: var(--s-heading); text-decoration: none; font-family: var(--theme-font-heading), sans-serif; font-size: 1.25rem; font-weight: 800; letter-spacing: -0.03em; }\n.hsh__logo img { display: block; width: auto; height: 30px; }\n.hsh__field { grid-area: field; display: flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 14px; border: 1.5px solid var(--s-border); border-radius: 4px; background: var(--s-bg); color: inherit; text-decoration: none; font-size: 0.9375rem; }\n.hsh__field span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; opacity: 0.75; }\n.hsh__field:hover { border-color: currentColor; }\n.hsh__promise { display: none; }\n.hsh__row .hsh__account { display: none; }\n.hsh__bag { grid-area: bag; }\n.hsh__icon { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-width: 44px; min-height: 44px; padding: 0 8px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: none; cursor: pointer; }\n.hsh__lines { display: block; width: 20px; height: 12px; border-top: 2px solid currentColor; border-bottom: 2px solid currentColor; }\n.hsh__count { min-width: 20px; margin-left: 2px; padding: 0 5px; line-height: 20px; border-radius: 10px; background: var(--s-btn); color: var(--s-btn-text); font-size: 0.75rem; text-align: center; font-variant-numeric: tabular-nums; }\n.hsh__count[data-count=\"0\"] { display: none; }\n.hsh__tabs { overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x proximity; scrollbar-width: none; mask-image: linear-gradient(to right, #000 85%, transparent); }\n.hsh__tabs ul { display: flex; gap: 6px; width: max-content; margin: 0; padding: 0 var(--theme-padding-x, 16px) 8px; list-style: none; }\n.hsh__tab { display: inline-flex; align-items: center; min-height: 40px; padding: 0 12px; scroll-snap-align: start; color: inherit; text-decoration: none; font-size: 0.9375rem; font-weight: 500; white-space: nowrap; }\n.hsh[data-tabs=\"underline\"] .hsh__tab { padding: 0 4px; margin-right: 12px; box-shadow: inset 0 -2px 0 transparent; }\n.hsh[data-tabs=\"underline\"] .hsh__tab:hover { box-shadow: inset 0 -2px 0 currentColor; }\n.hsh[data-tabs=\"outline\"] .hsh__tab { border: 1px solid var(--s-border); border-radius: 4px; }\n.hsh[data-tabs=\"outline\"] .hsh__tab:hover { border-color: currentColor; }\n.hsh[data-tabs=\"filled\"] .hsh__tab { background: color-mix(in srgb, var(--s-text) 7%, var(--s-bg)); border-radius: 4px; }\n.hsh[data-tabs=\"filled\"] .hsh__tab:hover { background: var(--s-btn); color: var(--s-btn-text); }\n.hsh :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n/* The top row slides away after the first scroll and the tabs stay; without scroll timelines, or with less motion, everything stays. */\n@supports (animation-timeline: scroll()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .hsh[data-collapse=\"true\"]:not([data-motion=\"off\"]) .hsh__fix { animation: hsh-compact linear both; animation-timeline: scroll(root); animation-range: 40px 160px; }\n    @keyframes hsh-compact { to { transform: translateY(calc(-1 * var(--hsh-lift, 104px))); } }\n  }\n}\n@media (prefers-reduced-motion: reduce) { .hsh__fix { animation: none; } }\n@media (min-width: 900px) {\n  .hsh { --hsh-lift: 60px; }\n  .hsh__space { height: calc(var(--hsh-row) + var(--hsh-tabs)); }\n  .hsh__row { grid-template-columns: auto minmax(0, 560px) minmax(0, 1fr) auto auto; grid-template-areas: \"logo field promise account bag\"; gap: 16px; min-height: var(--hsh-row); }\n  .hsh__burger { display: none; }\n  .hsh__promise { grid-area: promise; display: block; margin: 0; font-size: 0.875rem; text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .hsh__row .hsh__account { grid-area: account; display: inline-flex; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_header_shop\",\n  \"name\": \"Shop header with category tabs\",\n  \"kind\": \"header\",\n  \"enabled_on\": { \"groups\": [\"header\"] },\n  \"settings\": [\n    { \"type\": \"header\", \"id\": \"hdr_menu\", \"label\": \"Categories\" },\n    { \"type\": \"link_list\", \"id\": \"categories\", \"label\": \"Category tabs (also the phone menu)\", \"default\": \"main-menu\" },\n    { \"type\": \"select\", \"id\": \"tab_style\", \"label\": \"Tabs\", \"default\": \"filled\", \"options\": [{ \"label\": \"Underline\", \"value\": \"underline\" }, { \"label\": \"Outline\", \"value\": \"outline\" }, { \"label\": \"Filled\", \"value\": \"filled\" }] },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no logo\", \"default\": \"Market\" },\n    { \"type\": \"text\", \"id\": \"promise\", \"label\": \"Short promise beside the field\", \"default\": \"Order by 2pm, at your door tomorrow\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"checkbox\", \"id\": \"collapse\", \"label\": \"Hide the top row when scrolling\", \"default\": true },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"search_placeholder\", \"label\": \"Search field\", \"default\": \"Search the shop\" },\n    { \"type\": \"text\", \"id\": \"tabs_label\", \"label\": \"Tabs name (read aloud)\", \"default\": \"Categories\" },\n    { \"type\": \"text\", \"id\": \"menu_label\", \"label\": \"Menu button (read aloud)\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"account_label\", \"label\": \"Account\", \"default\": \"Account\" },\n    { \"type\": \"text\", \"id\": \"cart_label\", \"label\": \"Basket\", \"default\": \"Basket\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_header_split.storelib",
  "source": "{# example\ntitle: Centred logo header with the menu split either side\nsummary: Chrome kit header. The logo in the middle, one menu on its left and another on its right (two link_list settings, so the creator decides what sits where), a thin line of utility links above, search and bag at the far right; on phones a three part bar (menu, logo, bag) whose menu button opens the site's own drawer. Logo size, line on or off, link style (plain, underline that grows, letters that roll), alignment and colours are settings.\ntags: chrome kit, header, centered logo, centred logo, split nav, split navigation, luxury header, boutique header, own chrome, site header\n#}\n<template>\n<header class=\"hsp\" data-link=\"{{ settings.link_style }}\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --hsp-logo: {{ settings.logo_height }}px; --hsp-pad: {{ settings.padding_y }}px; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  {% if settings.show_utility %}\n  <div class=\"hsp__util\">\n    <p class=\"hsp__note\">{{ settings.utility_text }}</p>\n    <ul class=\"hsp__util-links\">{% for link in settings.utility_menu.links limit: 3 %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul>\n  </div>\n  {% endif %}\n  <div class=\"hsp__bar\">\n    <button class=\"hsp__icon hsp__burger\" type=\"button\" data-storelib-menu=\"{{ settings.menu_left.handle }}\" aria-label=\"{{ settings.menu_label }}\"><span class=\"hsp__lines\" aria-hidden=\"true\"></span></button>\n    <nav class=\"hsp__nav hsp__nav--left\" aria-label=\"{{ settings.left_label }}\">\n      <ul>{% for link in settings.menu_left.links limit: 4 %}<li><a class=\"hsp__link\" href=\"{{ link.url }}\"><span class=\"hsp__roll\" data-text=\"{{ link.title }}\">{{ link.title }}</span></a></li>{% endfor %}</ul>\n    </nav>\n    <a class=\"hsp__logo\" href=\"{{ routes.root_url }}\">{% if theme.logo.url %}<img src=\"{{ theme.logo.url }}\" alt=\"{{ shop.name }}\" width=\"200\" height=\"60\">{% else %}{{ shop.name | default: settings.brand }}{% endif %}</a>\n    <div class=\"hsp__right\">\n      <nav class=\"hsp__nav\" aria-label=\"{{ settings.right_label }}\">\n        <ul>{% for link in settings.menu_right.links limit: 4 %}<li><a class=\"hsp__link\" href=\"{{ link.url }}\"><span class=\"hsp__roll\" data-text=\"{{ link.title }}\">{{ link.title }}</span></a></li>{% endfor %}</ul>\n      </nav>\n      <a class=\"hsp__icon hsp__search\" href=\"{{ routes.search_url }}\" data-storelib-search aria-label=\"{{ settings.search_label }}\"><svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"6.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M16 16l4.5 4.5\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg></a>\n      <a class=\"hsp__icon hsp__bag\" href=\"{{ routes.cart_url }}\" data-storelib-cart aria-label=\"{{ settings.cart_label }}\"><svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" aria-hidden=\"true\"><path d=\"M5 8h14l-1.2 12H6.2L5 8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M9 8a3 3 0 016 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg><span class=\"hsp__bag-word\">{{ settings.cart_label }}</span> <span class=\"hsp__count\" data-storelib-cart-count></span></a>\n    </div>\n  </div>\n</header>\n</template>\n\n<style scoped>\n.hsp, .hsp *, .hsp *::before, .hsp *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.hsp [hidden] { display: none !important; }\n.hsp { position: relative; z-index: 40; background: var(--s-bg); color: var(--s-text); border-bottom: 1px solid var(--s-border); }\n.hsp__util { display: none; }\n.hsp__bar { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 12px; padding: var(--hsp-pad) var(--theme-padding-x, 16px); max-width: var(--theme-page-width, 1440px); margin: 0 auto; }\n.hsp__nav { display: none; }\n.hsp__nav ul { display: flex; flex-wrap: wrap; gap: 0 8px; margin: 0; padding: 0; list-style: none; }\n.hsp__logo { grid-column: 2; display: inline-flex; align-items: center; justify-content: center; min-height: 44px; color: var(--s-heading); text-decoration: none; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.375rem, 1rem + 1.4vw, 2.25rem); font-weight: 600; letter-spacing: -0.02em; text-align: center; }\n.hsp__logo img { display: block; width: auto; height: var(--hsp-logo); }\n.hsp__right { grid-column: 3; display: flex; align-items: center; justify-content: flex-end; gap: 4px; }\n.hsp__icon { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-width: 44px; min-height: 44px; padding: 0 6px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: none; cursor: pointer; }\n.hsp__burger { grid-column: 1; grid-row: 1; justify-self: start; }\n.hsp__lines { display: block; width: 22px; height: 10px; border-top: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor; }\n.hsp__bag-word { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }\n.hsp__count { font-size: 0.8125rem; font-variant-numeric: tabular-nums; }\n.hsp__count[data-count=\"0\"] { display: none; }\n.hsp__link { display: inline-flex; align-items: center; min-height: 44px; padding: 0 8px; color: inherit; text-decoration: none; font-size: 0.9375rem; }\n.hsp__roll { position: relative; display: inline-block; overflow: hidden; line-height: 1.3; }\n.hsp[data-link=\"underline\"] .hsp__roll { background: linear-gradient(currentColor, currentColor) 0 100% / 0 1px no-repeat; }\n.hsp[data-link=\"underline\"] .hsp__link:hover .hsp__roll, .hsp[data-link=\"underline\"] .hsp__link:focus-visible .hsp__roll { background-size: 100% 1px; }\n.hsp[data-link=\"plain\"] .hsp__link:hover { text-decoration: underline; text-underline-offset: 6px; }\n.hsp :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  .hsp:not([data-motion=\"off\"])[data-link=\"underline\"] .hsp__roll { transition: background-size var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease); }\n  .hsp:not([data-motion=\"off\"])[data-link=\"roll\"] .hsp__roll::after { content: attr(data-text); position: absolute; left: 0; top: 100%; }\n  .hsp:not([data-motion=\"off\"])[data-link=\"roll\"] .hsp__roll { transition: transform calc(var(--t-motion-hover, 200ms) * 1.5) var(--t-motion-ease-ui, ease); }\n  .hsp:not([data-motion=\"off\"])[data-link=\"roll\"] .hsp__link:hover .hsp__roll, .hsp:not([data-motion=\"off\"])[data-link=\"roll\"] .hsp__link:focus-visible .hsp__roll { transform: translateY(calc(-100% * min(1, var(--m-k, 1)))); }\n}\n@media (prefers-reduced-motion: reduce) { .hsp__roll { transition: none; } }\n@media (min-width: 990px) {\n  .hsp__util { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 0 var(--theme-padding-x, 16px); border-bottom: 1px solid var(--s-border); font-size: 0.8125rem; }\n  .hsp__note { margin: 0; padding: 8px 0; }\n  .hsp__util-links { display: flex; gap: 16px; margin: 0; padding: 0; list-style: none; }\n  .hsp__util-links a { display: inline-flex; align-items: center; min-height: 32px; color: inherit; }\n  .hsp__nav { display: block; }\n  .hsp__nav--left { grid-column: 1; grid-row: 1; }\n  .hsp__burger { display: none; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_header_split\",\n  \"name\": \"Centred logo header\",\n  \"kind\": \"header\",\n  \"enabled_on\": { \"groups\": [\"header\"] },\n  \"settings\": [\n    { \"type\": \"header\", \"id\": \"hdr_menus\", \"label\": \"Menus\" },\n    { \"type\": \"link_list\", \"id\": \"menu_left\", \"label\": \"Left of the logo (also the phone menu)\", \"default\": \"main-menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu_right\", \"label\": \"Right of the logo\", \"default\": \"footer\" },\n    { \"type\": \"checkbox\", \"id\": \"show_utility\", \"label\": \"Show the thin line above\", \"default\": true },\n    { \"type\": \"text\", \"id\": \"utility_text\", \"label\": \"Line above: note\", \"default\": \"Free returns within 30 days\" },\n    { \"type\": \"link_list\", \"id\": \"utility_menu\", \"label\": \"Line above: links\", \"default\": \"footer\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no logo\", \"default\": \"Home\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"range\", \"id\": \"logo_height\", \"label\": \"Logo height\", \"min\": 24, \"max\": 96, \"step\": 2, \"unit\": \"px\", \"default\": 44 },\n    { \"type\": \"range\", \"id\": \"padding_y\", \"label\": \"Space above and below\", \"min\": 4, \"max\": 40, \"step\": 2, \"unit\": \"px\", \"default\": 14 },\n    { \"type\": \"select\", \"id\": \"link_style\", \"label\": \"Link hover\", \"default\": \"roll\", \"options\": [{ \"label\": \"Plain underline\", \"value\": \"plain\" }, { \"label\": \"Line that grows\", \"value\": \"underline\" }, { \"label\": \"Words that roll\", \"value\": \"roll\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"left_label\", \"label\": \"Left menu name (read aloud)\", \"default\": \"Shop\" },\n    { \"type\": \"text\", \"id\": \"right_label\", \"label\": \"Right menu name (read aloud)\", \"default\": \"More\" },\n    { \"type\": \"text\", \"id\": \"menu_label\", \"label\": \"Menu button (read aloud)\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"search_label\", \"label\": \"Search (read aloud)\", \"default\": \"Search\" },\n    { \"type\": \"text\", \"id\": \"cart_label\", \"label\": \"Bag\", \"default\": \"Bag\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_locale.storelib",
  "source": "{# example\ntitle: Language and currency selectors as pills, a drop down or a sentence\nsummary: Chrome kit switches, a small section for the header group, the footer group or any page: the site's real languages and currencies (Settings, Markets) through the hooks, each list hidden by the page when the site has only one. Three styles: inline pills, a compact drop down (details, works by keyboard), or a plain sentence with the current choices (\"Shipping to France, prices in EUR\") that opens the lists. Flags are off by default (a language is not a country) and can be turned on for common languages; codes, labels, alignment and colours are settings.\ntags: chrome kit, language selector, currency selector, locale switcher, language switcher, currency switcher, country selector, markets, translation, flags, pills, dropdown, own chrome\n#}\n<template>\n<div class=\"loc\" data-style=\"{{ settings.style }}\" data-flags=\"{{ settings.show_flags }}\" data-codes=\"{{ settings.show_codes }}\" data-align=\"{{ settings.align }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --loc-py: {{ settings.padding_y }}px;\">\n  {% if settings.style == \"sentence\" %}\n  <p class=\"loc__sentence\">{% if settings.show_language %}<span class=\"loc__part-l\">{{ settings.sentence_before }} <span class=\"loc__now\" data-storelib-locale-current>{{ settings.language_label }}</span></span>{% endif %}{% if settings.show_currency %}<span class=\"loc__part-c\">{{ settings.sentence_middle }} <span class=\"loc__now\" data-storelib-currency-current>{{ settings.currency_label }}</span></span>{% endif %}</p>\n  {% endif %}\n  <div class=\"loc__row\">\n    {% if settings.show_language %}\n    <details class=\"loc__group\" data-storelib-locale-list {% if settings.style != \"dropdown\" %}open{% endif %}>\n      <summary class=\"loc__sum\">{{ settings.language_label }}<span class=\"loc__cur\" data-storelib-locale-current></span></summary>\n      <div class=\"loc__opts\" role=\"group\" aria-label=\"{{ settings.language_label }}\"><button class=\"loc__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span><span class=\"loc__code\" data-option-code></span></button></div>\n    </details>\n    {% endif %}\n    {% if settings.show_currency %}\n    <details class=\"loc__group\" data-storelib-currency-list {% if settings.style != \"dropdown\" %}open{% endif %}>\n      <summary class=\"loc__sum\">{{ settings.currency_label }}<span class=\"loc__cur\" data-storelib-currency-current></span></summary>\n      <div class=\"loc__opts\" role=\"group\" aria-label=\"{{ settings.currency_label }}\"><button class=\"loc__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n    </details>\n    {% endif %}\n  </div>\n</div>\n</template>\n\n<style scoped>\n.loc, .loc *, .loc *::before, .loc *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.loc [hidden] { display: none !important; }\n.loc { padding: var(--loc-py, 12px) var(--theme-padding-x, 16px); background: var(--s-bg); color: var(--s-text); font-size: 0.9375rem; }\n.loc__row { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 24px; }\n.loc[data-align=\"center\"] .loc__row, .loc[data-align=\"center\"] .loc__sentence { justify-content: center; text-align: center; }\n.loc[data-align=\"end\"] .loc__row, .loc[data-align=\"end\"] .loc__sentence { justify-content: flex-end; text-align: right; }\n.loc__group { position: relative; }\n.loc__group[hidden] { display: none; }\n.loc__sum { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; cursor: pointer; list-style: none; font-weight: 500; }\n.loc__sum::-webkit-details-marker { display: none; }\n.loc__cur { font-weight: 400; }\n.loc__cur:empty { display: none; }\n.loc__opts { display: flex; flex-wrap: wrap; gap: 6px; }\n.loc__opt { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 14px; border: 1px solid var(--s-border); border-radius: 22px; background: none; color: inherit; font: inherit; cursor: pointer; }\n.loc__opt:hover { border-color: currentColor; }\n.loc__opt[aria-current=\"true\"] { background: var(--s-text); color: var(--s-bg); border-color: var(--s-text); }\n.loc__code { font-size: 0.8125rem; font-variant-numeric: tabular-nums; }\n.loc[data-codes=\"false\"] .loc__code { display: none; }\n/* Pills: the lists always open, the summary is only a label. */\n.loc[data-style=\"pills\"] .loc__group { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }\n.loc[data-style=\"pills\"] .loc__sum { pointer-events: none; }\n.loc[data-style=\"pills\"] .loc__cur { display: none; }\n/* Drop down: a closed details; open, the choices hang under it. */\n.loc[data-style=\"dropdown\"] .loc__sum { gap: 0; padding: 0 14px; border: 1px solid var(--s-border); }\n.loc[data-style=\"dropdown\"] .loc__sum::after { content: \"\"; width: 7px; height: 7px; margin-left: 10px; border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor; transform: translateY(-2px) rotate(45deg); }\n.loc[data-style=\"dropdown\"] .loc__cur::before { content: \": \"; }\n.loc[data-style=\"dropdown\"] .loc__opts { position: absolute; z-index: 30; top: calc(100% + 4px); left: 0; display: grid; min-width: max(100%, 180px); padding: 6px; border: 1px solid var(--s-border); background: var(--s-bg); }\n.loc[data-style=\"dropdown\"] .loc__opt { justify-content: space-between; border: 0; border-radius: 0; }\n/* Sentence: the words say what is chosen; the lists sit under it. */\n.loc__sentence { margin: 0 0 8px; }\n.loc__now { font-weight: 600; }\n.loc[data-style=\"sentence\"] .loc__sum { display: none; }\n/* A list the page hid (one language, or one currency) takes its half of the sentence with it; nothing to choose, nothing shows. */\n.loc:has([data-storelib-locale-list][hidden]) .loc__part-l, .loc:has([data-storelib-currency-list][hidden]) .loc__part-c { display: none; }\n.loc:not(:has(.loc__group:not([hidden]))) { display: none; }\n.loc :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"en\"]::before { content: \"\\1F1EC \\1F1E7\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"fr\"]::before { content: \"\\1F1EB \\1F1F7\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"de\"]::before { content: \"\\1F1E9 \\1F1EA\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"es\"]::before { content: \"\\1F1EA \\1F1F8\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"it\"]::before { content: \"\\1F1EE \\1F1F9\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"nl\"]::before { content: \"\\1F1F3 \\1F1F1\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"pt\"]::before { content: \"\\1F1F5 \\1F1F9\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"sv\"]::before { content: \"\\1F1F8 \\1F1EA\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"da\"]::before { content: \"\\1F1E9 \\1F1F0\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"nb\"]::before { content: \"\\1F1F3 \\1F1F4\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"fi\"]::before { content: \"\\1F1EB \\1F1EE\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"pl\"]::before { content: \"\\1F1F5 \\1F1F1\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"ja\"]::before { content: \"\\1F1EF \\1F1F5\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"zh\"]::before { content: \"\\1F1E8 \\1F1F3\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"ko\"]::before { content: \"\\1F1F0 \\1F1F7\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"el\"]::before { content: \"\\1F1EC \\1F1F7\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"tr\"]::before { content: \"\\1F1F9 \\1F1F7\" / \"\"; }\n.loc[data-flags=\"true\"] .loc__opt[data-option-code=\"cs\"]::before { content: \"\\1F1E8 \\1F1FF\" / \"\"; }\n@media (min-width: 760px) { .loc__row { gap: 12px 40px; } }\n@media (prefers-reduced-motion: no-preference) { .loc__opt { transition: background-color var(--t-motion-hover, 200ms) ease, color var(--t-motion-hover, 200ms) ease; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_locale\",\n  \"name\": \"Language and currency\",\n  \"settings\": [\n    { \"type\": \"paragraph\", \"id\": \"about\", \"content\": \"Shows the languages and currencies set in Settings, Markets. Each list hides itself when there is only one.\" },\n    { \"type\": \"select\", \"id\": \"style\", \"label\": \"Style\", \"default\": \"dropdown\", \"options\": [{ \"label\": \"Pills\", \"value\": \"pills\" }, { \"label\": \"Drop down\", \"value\": \"dropdown\" }, { \"label\": \"A sentence\", \"value\": \"sentence\" }] },\n    { \"type\": \"checkbox\", \"id\": \"show_language\", \"label\": \"Show languages\", \"default\": true },\n    { \"type\": \"checkbox\", \"id\": \"show_currency\", \"label\": \"Show currencies\", \"default\": true },\n    { \"type\": \"checkbox\", \"id\": \"show_flags\", \"label\": \"Show flags beside languages\", \"default\": false },\n    { \"type\": \"checkbox\", \"id\": \"show_codes\", \"label\": \"Show language codes\", \"default\": false },\n    { \"type\": \"select\", \"id\": \"align\", \"label\": \"Alignment\", \"default\": \"start\", \"options\": [{ \"label\": \"Left\", \"value\": \"start\" }, { \"label\": \"Centre\", \"value\": \"center\" }, { \"label\": \"Right\", \"value\": \"end\" }] },\n    { \"type\": \"range\", \"id\": \"padding_y\", \"label\": \"Space above and below\", \"min\": 0, \"max\": 48, \"step\": 4, \"unit\": \"px\", \"default\": 12 },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency\", \"default\": \"Currency\" },\n    { \"type\": \"text\", \"id\": \"sentence_before\", \"label\": \"Sentence: start\", \"default\": \"Reading in\" },\n    { \"type\": \"text\", \"id\": \"sentence_middle\", \"label\": \"Sentence: middle\", \"default\": \", prices in\" },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_menu_bottom.storelib",
  "source": "{# example\ntitle: Bottom sheet menu on phones, a panel on wide screens\nsummary: Chrome kit menu drawer, a section placed after the header: on a phone the menu rises from the bottom edge where the thumb is (a sheet with a grab bar, up to 88% of the screen), on a wide screen it is a panel at the top right under the header. Opened by every Menu button through the hooks (a dialog: focus kept inside and returned, Escape, the close button, the dimmed page and any link shut it). Quick action tiles (blocks: track an order, book, contact), the site's menu with sub links as accordions, and the language and currency switches. Sheet height, tile count, wide screen placement and motion are settings.\ntags: chrome kit, menu drawer, bottom sheet, mobile menu, thumb zone, sheet, quick actions, accordion menu, app like menu, locale, currency, own chrome\n#}\n<template>\n<div class=\"mbs\" data-wide=\"{{ settings.wide_place }}\" data-motion=\"{{ settings.motion }}\" {% if page.in_editor and settings.editor_open %}data-editor-open{% endif %} data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --mbs-h: {{ settings.height }}svh; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"mbs__panel\" data-storelib-menu-panel aria-label=\"{{ settings.panel_label }}\">\n    <button class=\"mbs__scrim\" type=\"button\" data-storelib-menu-close tabindex=\"-1\" aria-label=\"{{ settings.close_label }}\"></button>\n    <div class=\"mbs__sheet\">\n      <span class=\"mbs__grab\" aria-hidden=\"true\"></span>\n      <div class=\"mbs__head\">\n        <p class=\"mbs__title\">{{ settings.panel_label }}</p>\n        <button class=\"mbs__close\" type=\"button\" data-storelib-menu-close>{{ settings.close_label }}</button>\n      </div>\n      {% if section.blocks.size > 0 %}\n      <ul class=\"mbs__tiles\">\n        {% for block in section.blocks %}<li data-block-id=\"{{ block.id }}\"><a class=\"mbs__tile\" href=\"{{ block.settings.url | url }}\"><span class=\"mbs__tile-t\">{{ block.settings.title }}</span>{% if block.settings.text %}<span class=\"mbs__tile-x\">{{ block.settings.text }}</span>{% endif %}</a></li>{% endfor %}\n      </ul>\n      {% endif %}\n      <nav aria-label=\"{{ settings.nav_label }}\">\n        <ul class=\"mbs__list\">\n          {% for link in settings.menu.links %}\n          <li>\n            {% if link.links.size > 0 %}\n            <details class=\"mbs__acc\">\n              <summary class=\"mbs__link\">{{ link.title }}<span class=\"mbs__chev\" aria-hidden=\"true\"></span></summary>\n              <ul class=\"mbs__sub\"><li><a href=\"{{ link.url }}\">{{ settings.all_label }}</a></li>{% for child in link.links %}<li><a href=\"{{ child.url }}\">{{ child.title }}</a></li>{% endfor %}</ul>\n            </details>\n            {% else %}\n            <a class=\"mbs__link\" href=\"{{ link.url }}\">{{ link.title }}</a>\n            {% endif %}\n          </li>\n          {% endfor %}\n        </ul>\n      </nav>\n      <div class=\"mbs__prefs\">\n        <div class=\"mbs__pref\" data-storelib-locale-list role=\"group\" aria-label=\"{{ settings.language_label }}\"><button class=\"mbs__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n        <div class=\"mbs__pref\" data-storelib-currency-list role=\"group\" aria-label=\"{{ settings.currency_label }}\"><button class=\"mbs__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n      </div>\n    </div>\n  </div>\n</div>\n</template>\n\n<style scoped>\n.mbs, .mbs *, .mbs *::before, .mbs *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.mbs [hidden] { display: none !important; }\n.mbs__panel { position: fixed; inset: 0; z-index: 80; visibility: hidden; }\n.mbs__panel[data-open=\"true\"], .mbs[data-editor-open] .mbs__panel { visibility: visible; }\n.mbs[data-editor-open] .mbs__panel { position: relative; min-height: 680px; }\n.mbs__scrim { position: absolute; inset: 0; width: 100%; padding: 0; border: 0; background: rgba(0, 0, 0, 0.45); opacity: 0; cursor: pointer; }\n.mbs__panel[data-open=\"true\"] .mbs__scrim, .mbs[data-editor-open] .mbs__scrim { opacity: 1; }\n.mbs__sheet { position: absolute; inset: auto 0 0; display: flex; flex-direction: column; gap: 16px; max-height: var(--mbs-h, 88svh); padding: 8px 20px calc(20px + env(safe-area-inset-bottom, 0px)); overflow-y: auto; overscroll-behavior: contain; border-radius: 14px 14px 0 0; background: var(--s-bg); color: var(--s-text); transform: translateY(100%); }\n.mbs__panel[data-open=\"true\"] .mbs__sheet, .mbs[data-editor-open] .mbs__sheet { transform: none; }\n.mbs__grab { align-self: center; width: 40px; height: 4px; border-radius: 2px; background: var(--s-border); }\n.mbs__head { display: flex; align-items: center; justify-content: space-between; }\n.mbs__title { margin: 0; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: 1.375rem; font-weight: 700; letter-spacing: -0.02em; }\n.mbs__close { min-height: 44px; padding: 0 14px; border: 0; background: color-mix(in srgb, var(--s-text) 8%, var(--s-bg)); color: inherit; font: inherit; border-radius: 4px; cursor: pointer; }\n.mbs__tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(130px, 100%), 1fr)); gap: 8px; margin: 0; padding: 0; list-style: none; }\n.mbs__tile { display: grid; gap: 2px; align-content: end; min-height: 76px; padding: 12px; border-radius: 4px; background: color-mix(in srgb, var(--s-text) 6%, var(--s-bg)); color: inherit; text-decoration: none; }\n.mbs__tile:hover { background: var(--s-btn); color: var(--s-btn-text); }\n.mbs__tile-t { font-weight: 600; }\n.mbs__tile-x { font-size: 0.8125rem; }\n.mbs__list { margin: 0; padding: 0; list-style: none; }\n.mbs__link { display: flex; align-items: center; justify-content: space-between; min-height: 52px; color: var(--s-heading); text-decoration: none; font-size: 1.125rem; font-weight: 600; border-bottom: 1px solid var(--s-border); cursor: pointer; list-style: none; }\n.mbs__link::-webkit-details-marker { display: none; }\n.mbs__chev { width: 9px; height: 9px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: rotate(45deg); }\n.mbs__acc[open] .mbs__chev { transform: rotate(-135deg); }\n.mbs__sub { margin: 0; padding: 4px 0 8px 12px; list-style: none; }\n.mbs__sub a { display: flex; align-items: center; min-height: 44px; color: inherit; text-decoration: none; }\n.mbs__prefs { display: grid; gap: 8px; }\n.mbs__pref { display: flex; flex-wrap: wrap; gap: 6px; }\n.mbs__opt { min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); border-radius: 4px; background: none; color: inherit; font: inherit; cursor: pointer; }\n.mbs__opt[aria-current=\"true\"] { border-color: currentColor; font-weight: 600; }\n.mbs :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  .mbs:not([data-motion=\"off\"]) .mbs__panel { transition: visibility 0s linear var(--t-motion-duration, 650ms); }\n  .mbs:not([data-motion=\"off\"]) .mbs__panel[data-open=\"true\"] { transition-delay: 0s; }\n  .mbs:not([data-motion=\"off\"]) .mbs__sheet { transition: transform calc(var(--t-motion-duration, 650ms) * 0.7) cubic-bezier(0.32, 0.72, 0, 1); }\n  .mbs:not([data-motion=\"off\"]) .mbs__scrim { transition: opacity calc(var(--t-motion-duration, 650ms) * 0.5) ease; }\n  .mbs:not([data-motion=\"off\"]) .mbs__panel[data-open=\"true\"] .mbs__tile { animation: mbs-pop calc(var(--t-motion-duration, 650ms) * 0.8) var(--t-motion-ease, ease-out) 150ms both; }\n  @keyframes mbs-pop { from { opacity: 0; transform: scale(calc(1 - 0.06 * var(--m-k, 1))); } }\n}\n@media (prefers-reduced-motion: reduce) { .mbs__panel, .mbs__sheet, .mbs__scrim, .mbs__tile { transition: none; animation: none; } }\n@media (min-width: 900px) {\n  .mbs__sheet { inset: 72px 24px auto auto; width: min(420px, calc(100% - 48px)); max-height: calc(100svh - 96px); border-radius: 6px; transform: translateY(-12px); opacity: 0; }\n  .mbs[data-wide=\"left\"] .mbs__sheet { inset: 72px auto auto 24px; }\n  .mbs__panel[data-open=\"true\"] .mbs__sheet, .mbs[data-editor-open] .mbs__sheet { opacity: 1; }\n  .mbs__grab { display: none; }\n  .mbs:not([data-motion=\"off\"]) .mbs__sheet { transition: transform calc(var(--t-motion-duration, 650ms) * 0.5) var(--t-motion-ease, ease-out), opacity calc(var(--t-motion-duration, 650ms) * 0.4) ease; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_menu_bottom\",\n  \"name\": \"Bottom sheet menu\",\n  \"settings\": [\n    { \"type\": \"paragraph\", \"id\": \"about\", \"content\": \"Opens from every Menu button on the page. Keep it right after the header.\" },\n    { \"type\": \"checkbox\", \"id\": \"editor_open\", \"label\": \"Keep it open in the editor\", \"default\": false },\n    { \"type\": \"header\", \"id\": \"hdr_menu\", \"label\": \"Menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"main-menu\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"range\", \"id\": \"height\", \"label\": \"Tallest on a phone\", \"min\": 50, \"max\": 95, \"step\": 1, \"unit\": \"%\", \"default\": 88 },\n    { \"type\": \"select\", \"id\": \"wide_place\", \"label\": \"On wide screens\", \"default\": \"right\", \"options\": [{ \"label\": \"Top right\", \"value\": \"right\" }, { \"label\": \"Top left\", \"value\": \"left\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"panel_label\", \"label\": \"Title\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Links name (read aloud)\", \"default\": \"Main\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"all_label\", \"label\": \"Link to the whole section\", \"default\": \"See all\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language (read aloud)\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency (read aloud)\", \"default\": \"Currency\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"tile\", \"name\": \"Quick action\", \"limit\": 4, \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"Contact us\" },\n      { \"type\": \"text\", \"id\": \"text\", \"label\": \"Line under it\", \"default\": \"\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link\", \"default\": \"/contact\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Bottom sheet menu\", \"blocks\": [\n    { \"type\": \"tile\", \"settings\": { \"title\": \"Your account\", \"text\": \"Orders and returns\", \"url\": \"/account\" } },\n    { \"type\": \"tile\", \"settings\": { \"title\": \"Contact us\", \"text\": \"We answer within a day\", \"url\": \"/contact\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_menu_fullscreen.storelib",
  "source": "{# example\ntitle: Full screen menu drawer with huge staggered links\nsummary: Chrome kit menu drawer, a section of its own placed after the header: every Menu button on the page (data-storelib-menu) opens it through the hooks as a dialog (focus kept inside and returned, Escape, its close button and any link shut it). The site's menu set huge, each link rising in turn, sub links folding open under their parent (details), small links, socials (blocks) and the language and currency switches at the foot. How it opens (fade, wipe from a corner, drop), type size, alignment, colours and motion are settings; it can be kept open in the editor to style it.\ntags: chrome kit, menu drawer, full screen menu, fullscreen menu, overlay menu, mobile menu, hamburger menu, staggered links, big type menu, locale, currency, own chrome\n#}\n<template>\n<div class=\"mfs\" data-reveal=\"{{ settings.reveal }}\" data-align=\"{{ settings.align }}\" data-motion=\"{{ settings.motion }}\" {% if page.in_editor and settings.editor_open %}data-editor-open{% endif %} data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --mfs-size: {{ settings.type_size }}; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"mfs__panel\" data-storelib-menu-panel aria-label=\"{{ settings.panel_label }}\">\n    <div class=\"mfs__top\">\n      <a class=\"mfs__logo\" href=\"{{ routes.root_url }}\">{{ shop.name | default: settings.brand }}</a>\n      <button class=\"mfs__close\" type=\"button\" data-storelib-menu-close><span>{{ settings.close_label }}</span><span class=\"mfs__x\" aria-hidden=\"true\"></span></button>\n    </div>\n    <nav class=\"mfs__nav\" aria-label=\"{{ settings.nav_label }}\">\n      <ul class=\"mfs__list\">\n        {% for link in settings.menu.links %}\n        <li class=\"mfs__item\" style=\"--i: {{ forloop.index }};\">\n          {% if link.links.size > 0 %}\n          <details class=\"mfs__group\">\n            <summary class=\"mfs__big\">{{ link.title }}<span class=\"mfs__plus\" aria-hidden=\"true\"></span></summary>\n            <ul class=\"mfs__sub\">\n              <li><a href=\"{{ link.url }}\">{{ settings.all_label }}</a></li>\n              {% for child in link.links %}<li><a href=\"{{ child.url }}\">{{ child.title }}</a></li>{% endfor %}\n            </ul>\n          </details>\n          {% else %}\n          <a class=\"mfs__big\" href=\"{{ link.url }}\">{{ link.title }}</a>\n          {% endif %}\n        </li>\n        {% endfor %}\n      </ul>\n    </nav>\n    <div class=\"mfs__foot\">\n      <ul class=\"mfs__small\">{% for link in settings.small_menu.links limit: 6 %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul>\n      <ul class=\"mfs__social\">{% for block in section.blocks %}<li data-block-id=\"{{ block.id }}\"><a href=\"{{ block.settings.url | url }}\" target=\"_blank\" rel=\"noopener\">{{ block.settings.label }}</a></li>{% endfor %}</ul>\n      <div class=\"mfs__prefs\">\n        <div class=\"mfs__pref\" data-storelib-locale-list role=\"group\" aria-label=\"{{ settings.language_label }}\"><button class=\"mfs__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n        <div class=\"mfs__pref\" data-storelib-currency-list role=\"group\" aria-label=\"{{ settings.currency_label }}\"><button class=\"mfs__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n      </div>\n    </div>\n  </div>\n</div>\n</template>\n\n<style scoped>\n.mfs, .mfs *, .mfs *::before, .mfs *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.mfs [hidden] { display: none !important; }\n.mfs__panel { position: fixed; inset: 0; z-index: 80; display: flex; flex-direction: column; gap: 24px; padding: 0 var(--theme-padding-x, 16px) 24px; overflow-y: auto; overscroll-behavior: contain; background: var(--s-bg); color: var(--s-text); visibility: hidden; opacity: 0; }\n.mfs__panel[data-open=\"true\"], .mfs[data-editor-open] .mfs__panel { visibility: visible; opacity: 1; clip-path: none; transform: none; }\n.mfs[data-editor-open] .mfs__panel { position: relative; inset: auto; min-height: 640px; }\n.mfs__top { display: flex; align-items: center; justify-content: space-between; min-height: 64px; }\n.mfs__logo { display: inline-flex; align-items: center; min-height: 44px; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: 1.25rem; font-weight: 700; text-decoration: none; }\n.mfs__close { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 4px 0 12px; border: 0; background: none; color: inherit; font: inherit; cursor: pointer; }\n.mfs__x { position: relative; width: 28px; height: 28px; }\n.mfs__x::before, .mfs__x::after { content: \"\"; position: absolute; left: 3px; right: 3px; top: 13px; height: 2px; background: currentColor; transform: rotate(45deg); }\n.mfs__x::after { transform: rotate(-45deg); }\n.mfs__nav { flex: 1; display: flex; align-items: center; }\n.mfs__list { width: 100%; margin: 0; padding: 0; list-style: none; }\n.mfs[data-align=\"center\"] .mfs__list { text-align: center; }\n.mfs__big { display: flex; align-items: center; gap: 16px; padding: 2px 0; color: var(--s-heading); text-decoration: none; font-family: var(--theme-font-heading), sans-serif; font-size: calc(clamp(2.75rem, 1rem + 9vw, 8.5rem) * var(--mfs-size, 100) / 100); line-height: 1; letter-spacing: -0.045em; font-weight: 700; cursor: pointer; list-style: none; overflow-wrap: anywhere; }\n.mfs[data-align=\"center\"] .mfs__big { justify-content: center; }\n.mfs__big::-webkit-details-marker { display: none; }\n.mfs__big:hover, .mfs__big:focus-visible { color: var(--s-accent); }\n.mfs__plus { position: relative; flex: none; width: 0.4em; height: 0.4em; }\n.mfs__plus::before, .mfs__plus::after { content: \"\"; position: absolute; left: 0; right: 0; top: 50%; height: 3px; margin-top: -1.5px; background: currentColor; }\n.mfs__plus::after { transform: rotate(90deg); }\n.mfs__group[open] .mfs__plus::after { transform: none; }\n.mfs__sub { display: flex; flex-wrap: wrap; gap: 0 20px; margin: 4px 0 16px; padding: 0; list-style: none; font-size: 1.125rem; }\n.mfs[data-align=\"center\"] .mfs__sub { justify-content: center; }\n.mfs__sub a, .mfs__small a, .mfs__social a { display: inline-flex; align-items: center; min-height: 44px; color: inherit; }\n.mfs__foot { display: grid; gap: 12px; padding-top: 16px; border-top: 1px solid var(--s-border); font-size: 0.9375rem; }\n.mfs__small, .mfs__social { display: flex; flex-wrap: wrap; gap: 0 20px; margin: 0; padding: 0; list-style: none; }\n.mfs__prefs { display: flex; flex-wrap: wrap; gap: 8px 20px; }\n.mfs__pref { display: flex; flex-wrap: wrap; gap: 6px; }\n.mfs__opt { min-height: 44px; padding: 0 14px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.mfs__opt[aria-current=\"true\"] { background: var(--s-text); color: var(--s-bg); border-color: var(--s-text); }\n.mfs :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n@media (prefers-reduced-motion: no-preference) {\n  .mfs:not([data-motion=\"off\"]) .mfs__panel { transition: opacity calc(var(--t-motion-duration, 650ms) * 0.6) var(--t-motion-ease, ease-out), clip-path calc(var(--t-motion-duration, 650ms) * 1.1) var(--t-motion-ease, ease-out), transform calc(var(--t-motion-duration, 650ms) * 0.9) var(--t-motion-ease, ease-out), visibility 0s linear calc(var(--t-motion-duration, 650ms) * 1.1); }\n  .mfs:not([data-motion=\"off\"]) .mfs__panel[data-open=\"true\"] { transition-delay: 0s; }\n  .mfs[data-reveal=\"wipe\"]:not([data-motion=\"off\"]) .mfs__panel:not([data-open=\"true\"]) { opacity: 1; clip-path: circle(0% at calc(100% - 40px) 32px); }\n  .mfs[data-reveal=\"wipe\"]:not([data-motion=\"off\"]) .mfs__panel[data-open=\"true\"] { clip-path: circle(150% at calc(100% - 40px) 32px); }\n  .mfs[data-reveal=\"drop\"]:not([data-motion=\"off\"]) .mfs__panel:not([data-open=\"true\"]) { opacity: 1; transform: translateY(-100%); }\n  .mfs:not([data-motion=\"off\"]) .mfs__panel[data-open=\"true\"] .mfs__item { animation: mfs-rise var(--t-motion-duration, 650ms) var(--t-motion-ease, ease-out) both; animation-delay: calc(var(--i, 1) * var(--t-motion-stagger, 65ms) + 120ms); }\n  .mfs:not([data-motion=\"off\"]) .mfs__panel[data-open=\"true\"] .mfs__foot { animation: mfs-fade var(--t-motion-duration, 650ms) var(--t-motion-ease, ease-out) 360ms both; }\n  @keyframes mfs-rise { from { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 2.5 * var(--m-k, 1))); } }\n  @keyframes mfs-fade { from { opacity: 0; } }\n}\n@media (prefers-reduced-motion: reduce) { .mfs__panel, .mfs__item, .mfs__foot { transition: none; animation: none; } }\n@media (min-width: 900px) {\n  .mfs__panel { padding-left: clamp(24px, 6vw, 96px); padding-right: clamp(24px, 6vw, 96px); }\n  .mfs__foot { grid-template-columns: 1fr auto auto; align-items: center; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_menu_fullscreen\",\n  \"name\": \"Full screen menu\",\n  \"settings\": [\n    { \"type\": \"paragraph\", \"id\": \"about\", \"content\": \"Opens from every Menu button on the page. Keep it right after the header.\" },\n    { \"type\": \"checkbox\", \"id\": \"editor_open\", \"label\": \"Keep it open in the editor\", \"default\": false },\n    { \"type\": \"header\", \"id\": \"hdr_menu\", \"label\": \"Menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Big links\", \"default\": \"main-menu\" },\n    { \"type\": \"link_list\", \"id\": \"small_menu\", \"label\": \"Small links\", \"default\": \"footer\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no shop name\", \"default\": \"Home\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"select\", \"id\": \"reveal\", \"label\": \"How it opens\", \"default\": \"wipe\", \"options\": [{ \"label\": \"Fade\", \"value\": \"fade\" }, { \"label\": \"Wipe from the corner\", \"value\": \"wipe\" }, { \"label\": \"Drop from the top\", \"value\": \"drop\" }] },\n    { \"type\": \"select\", \"id\": \"align\", \"label\": \"Links\", \"default\": \"start\", \"options\": [{ \"label\": \"Left\", \"value\": \"start\" }, { \"label\": \"Centre\", \"value\": \"center\" }] },\n    { \"type\": \"range\", \"id\": \"type_size\", \"label\": \"Type size\", \"min\": 50, \"max\": 130, \"step\": 5, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"panel_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Links name (read aloud)\", \"default\": \"Main\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"all_label\", \"label\": \"Link to the whole section\", \"default\": \"See all\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language (read aloud)\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency (read aloud)\", \"default\": \"Currency\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"social\", \"name\": \"Social link\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"label\", \"label\": \"Name\", \"default\": \"Instagram\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Address\", \"default\": \"https://instagram.com\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Full screen menu\", \"blocks\": [\n    { \"type\": \"social\", \"settings\": { \"label\": \"Instagram\", \"url\": \"https://instagram.com\" } },\n    { \"type\": \"social\", \"settings\": { \"label\": \"YouTube\", \"url\": \"https://youtube.com\" } },\n    { \"type\": \"social\", \"settings\": { \"label\": \"Newsletter\", \"url\": \"/contact\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_menu_sheet.storelib",
  "source": "{# example\ntitle: Side sheet menu with sub menus that slide in\nsummary: Chrome kit menu drawer, a section placed after the header: a sheet from the left or right edge over a dimmed page, opened by every Menu button through the hooks (a dialog: focus kept inside and returned, Escape, the close button, the dimmed page and any link shut it). Top links with sub links open a second level that slides over the first (details, no script) and their row turns into Back; featured cards (blocks) at the foot and the language and currency switches. Edge, width, dimming, card pictures and motion are settings.\ntags: chrome kit, menu drawer, side sheet, side menu, slide out menu, offcanvas, off canvas, drill down menu, sub menu, mobile menu, featured cards, locale, currency, own chrome\n#}\n<template>\n<div class=\"msh\" data-edge=\"{{ settings.edge }}\" data-motion=\"{{ settings.motion }}\" {% if page.in_editor and settings.editor_open %}data-editor-open{% endif %} data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --msh-w: {{ settings.width }}px; --msh-dim: {{ settings.dim }}; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"msh__panel\" data-storelib-menu-panel aria-label=\"{{ settings.panel_label }}\">\n    <button class=\"msh__scrim\" type=\"button\" data-storelib-menu-close tabindex=\"-1\" aria-label=\"{{ settings.close_label }}\"></button>\n    <div class=\"msh__sheet\">\n      <div class=\"msh__head\">\n        <p class=\"msh__title\">{{ settings.panel_label }}</p>\n        <button class=\"msh__btn\" type=\"button\" data-storelib-menu-close>{{ settings.close_label }}</button>\n      </div>\n      <nav class=\"msh__levels\" aria-label=\"{{ settings.nav_label }}\">\n        <ul class=\"msh__list msh__root\">\n          {% for link in settings.menu.links %}\n          <li style=\"--i: {{ forloop.index }};\">\n            {% if link.links.size > 0 %}\n            <details class=\"msh__group\">\n              <summary class=\"msh__link\"><span class=\"msh__back-word\">{{ settings.back_label }}</span><span class=\"msh__name\">{{ link.title }}</span><span class=\"msh__chev\" aria-hidden=\"true\"></span></summary>\n              <div class=\"msh__level\">\n                <a class=\"msh__level-h\" href=\"{{ link.url }}\">{{ settings.all_label }} {{ link.title }}</a>\n                <ul class=\"msh__list\">{% for child in link.links %}<li style=\"--i: {{ forloop.index }};\"><a class=\"msh__link\" href=\"{{ child.url }}\">{{ child.title }}</a></li>{% endfor %}</ul>\n              </div>\n            </details>\n            {% else %}\n            <a class=\"msh__link\" href=\"{{ link.url }}\">{{ link.title }}</a>\n            {% endif %}\n          </li>\n          {% endfor %}\n        </ul>\n      </nav>\n      <div class=\"msh__cards\">\n        {% for block in section.blocks %}\n        <a class=\"msh__card\" href=\"{{ block.settings.url | url }}\" data-block-id=\"{{ block.id }}\">\n          {% if block.settings.image %}<img src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"400\" height=\"300\" loading=\"lazy\">{% endif %}\n          <span>{{ block.settings.title }}</span>\n        </a>\n        {% endfor %}\n      </div>\n      <div class=\"msh__prefs\">\n        <div class=\"msh__pref\" data-storelib-locale-list role=\"group\" aria-label=\"{{ settings.language_label }}\"><button class=\"msh__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n        <div class=\"msh__pref\" data-storelib-currency-list role=\"group\" aria-label=\"{{ settings.currency_label }}\"><button class=\"msh__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n      </div>\n    </div>\n  </div>\n</div>\n</template>\n\n<style scoped>\n.msh, .msh *, .msh *::before, .msh *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.msh [hidden] { display: none !important; }\n.msh__panel { position: fixed; inset: 0; z-index: 80; visibility: hidden; }\n.msh__panel[data-open=\"true\"], .msh[data-editor-open] .msh__panel { visibility: visible; }\n.msh[data-editor-open] .msh__panel { position: relative; min-height: 640px; }\n.msh__scrim { position: absolute; inset: 0; width: 100%; border: 0; padding: 0; background: rgba(0, 0, 0, var(--msh-dim, 0.4)); opacity: 0; cursor: pointer; }\n.msh__panel[data-open=\"true\"] .msh__scrim, .msh[data-editor-open] .msh__scrim { opacity: 1; }\n.msh__sheet { position: absolute; inset: 0 auto 0 0; display: flex; flex-direction: column; gap: 20px; width: min(var(--msh-w), 100%); padding: 0 20px 24px; overflow: hidden auto; overscroll-behavior: contain; background: var(--s-bg); color: var(--s-text); transform: translateX(-100%); }\n.msh[data-edge=\"right\"] .msh__sheet { inset: 0 0 0 auto; transform: translateX(100%); }\n.msh__panel[data-open=\"true\"] .msh__sheet, .msh[data-editor-open] .msh__sheet { transform: none; }\n.msh__head { display: flex; align-items: center; justify-content: space-between; min-height: 64px; border-bottom: 1px solid var(--s-border); }\n.msh__title { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: 1.25rem; font-weight: 700; color: var(--s-heading); }\n.msh__btn { min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n/* A top link with sub links is a details: open, its level covers the first one and its summary turns into Back. */\n.msh__levels { position: relative; flex: 1; min-height: 340px; }\n.msh__level { position: absolute; inset: 0; z-index: 1; padding-top: 56px; overflow-y: auto; background: var(--s-bg); }\n.msh__group[open] > .msh__link { position: absolute; inset: 0 0 auto; z-index: 2; justify-content: flex-start; background: var(--s-bg); font-family: inherit; font-size: 1rem; font-weight: 500; letter-spacing: 0; }\n.msh__group[open] .msh__chev { order: -1; transform: rotate(-135deg); }\n.msh__back-word { display: none; }\n.msh__group[open] .msh__back-word { display: inline; }\n.msh__group[open] .msh__name { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }\n.msh__levels:has(details[open]) .msh__root > li:not(:has(details[open])) { visibility: hidden; }\n.msh__group > summary { list-style: none; }\n.msh__group > summary::-webkit-details-marker { display: none; }\n.msh__list { margin: 0; padding: 0; list-style: none; }\n.msh__link { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 52px; color: var(--s-heading); text-decoration: none; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.375rem, 1.2rem + 0.8vw, 1.75rem); font-weight: 600; letter-spacing: -0.02em; border-bottom: 1px solid var(--s-border); cursor: pointer; }\n.msh__link:hover { color: var(--s-accent); }\n.msh__chev { width: 10px; height: 10px; border-top: 2px solid currentColor; border-right: 2px solid currentColor; transform: rotate(45deg); }\n.msh__level-h { display: block; margin: 4px 0 8px; color: inherit; font-size: 0.9375rem; text-underline-offset: 4px; }\n.msh__cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(140px, 100%), 1fr)); gap: 12px; margin-top: auto; }\n.msh__card { display: grid; gap: 6px; color: inherit; text-decoration: none; font-size: 0.9375rem; font-weight: 500; }\n.msh__card img { display: block; width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; }\n.msh__prefs { display: grid; gap: 8px; }\n.msh__pref { display: flex; flex-wrap: wrap; gap: 6px; }\n.msh__opt { min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.msh__opt[aria-current=\"true\"] { border-color: currentColor; font-weight: 600; }\n.msh :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  .msh:not([data-motion=\"off\"]) .msh__panel { transition: visibility 0s linear var(--t-motion-duration, 650ms); }\n  .msh:not([data-motion=\"off\"]) .msh__panel[data-open=\"true\"] { transition-delay: 0s; }\n  .msh:not([data-motion=\"off\"]) .msh__sheet { transition: transform calc(var(--t-motion-duration, 650ms) * 0.75) cubic-bezier(0.32, 0.72, 0, 1); }\n  .msh:not([data-motion=\"off\"]) .msh__scrim { transition: opacity calc(var(--t-motion-duration, 650ms) * 0.6) ease; }\n  .msh:not([data-motion=\"off\"]) .msh__group[open] .msh__level { animation: msh-over calc(var(--t-motion-duration, 650ms) * 0.6) var(--t-motion-ease, ease-out) both; }\n  @keyframes msh-over { from { transform: translateX(calc(40px * var(--m-k, 1))); opacity: 0; } }\n  .msh:not([data-motion=\"off\"]) .msh__panel[data-open=\"true\"] .msh__root li { animation: msh-in var(--t-motion-duration, 650ms) var(--t-motion-ease, ease-out) both; animation-delay: calc(var(--i, 1) * var(--t-motion-stagger, 65ms) + 100ms); }\n  @keyframes msh-in { from { opacity: 0; transform: translateX(calc(var(--t-motion-distance, 24px) * -1 * var(--m-k, 1))); } }\n}\n@media (min-width: 900px) { .msh__sheet { padding: 0 28px 28px; } .msh__head { min-height: 72px; } }\n@media (prefers-reduced-motion: reduce) { .msh__panel, .msh__sheet, .msh__scrim, .msh__level, .msh__root li { transition: none; animation: none; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_menu_sheet\",\n  \"name\": \"Side sheet menu\",\n  \"settings\": [\n    { \"type\": \"paragraph\", \"id\": \"about\", \"content\": \"Opens from every Menu button on the page. Keep it right after the header.\" },\n    { \"type\": \"checkbox\", \"id\": \"editor_open\", \"label\": \"Keep it open in the editor\", \"default\": false },\n    { \"type\": \"header\", \"id\": \"hdr_menu\", \"label\": \"Menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"main-menu\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"select\", \"id\": \"edge\", \"label\": \"Comes from\", \"default\": \"left\", \"options\": [{ \"label\": \"Left\", \"value\": \"left\" }, { \"label\": \"Right\", \"value\": \"right\" }] },\n    { \"type\": \"range\", \"id\": \"width\", \"label\": \"Width\", \"min\": 300, \"max\": 560, \"step\": 10, \"unit\": \"px\", \"default\": 420 },\n    { \"type\": \"range\", \"id\": \"dim\", \"label\": \"Page dimming\", \"min\": 0, \"max\": 0.8, \"step\": 0.05, \"default\": 0.4 },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"panel_label\", \"label\": \"Title\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Links name (read aloud)\", \"default\": \"Main\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"back_label\", \"label\": \"Back button\", \"default\": \"Back\" },\n    { \"type\": \"text\", \"id\": \"all_label\", \"label\": \"Link to the whole section starts with\", \"default\": \"All of\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language (read aloud)\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency (read aloud)\", \"default\": \"Currency\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"card\", \"name\": \"Featured card\", \"limit\": 4, \"settings\": [\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Picture description\", \"default\": \"\" },\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"New in\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link\", \"default\": \"/shop\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Side sheet menu\", \"blocks\": [\n    { \"type\": \"card\", \"settings\": { \"title\": \"New in\", \"url\": \"/shop\" } },\n    { \"type\": \"card\", \"settings\": { \"title\": \"Our story\", \"url\": \"/about\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_search_drop.storelib",
  "source": "{# example\ntitle: Drop down search with suggestions and quick links\nsummary: Chrome kit search window, a section placed after the header: the site's own search panel drops from under the header (the full width on phones, a centred box on wide screens) over a dimmed page. Suggestions (blocks) and quick links (a menu) beside the field until the visitor types, then a compact live list of this store's products, pages and posts with small pictures, prices and what each is, plus a link to every result. Opened by every search button through the hooks; focus kept inside; Escape and the close button shut it. Width, offset from the top, dimming and motion are settings.\ntags: chrome kit, search, search panel, search dropdown, drop down search, live search, autocomplete, suggestions, quick links, predictive search, own chrome\n#}\n<template>\n<div class=\"sdr\" data-motion=\"{{ settings.motion }}\" {% if page.in_editor and settings.editor_open %}data-editor-open{% endif %} data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --sdr-top: {{ settings.top_offset }}px; --sdr-w: {{ settings.width }}px; --sdr-dim: {{ settings.dim }}; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"sdr__panel\" data-storelib-search-panel role=\"dialog\" aria-label=\"{{ settings.label }}\">\n    <button class=\"sdr__scrim\" type=\"button\" data-storelib-search-close tabindex=\"-1\" aria-label=\"{{ settings.close_label }}\"></button>\n    <div class=\"sdr__box\">\n      <div class=\"sdr__field\">\n        <svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"6.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M16 16l4.5 4.5\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg>\n        <input class=\"sdr__input\" type=\"search\" autocomplete=\"off\" enterkeyhint=\"search\" data-storelib-search-input placeholder=\"{{ settings.placeholder }}\" aria-label=\"{{ settings.label }}\">\n        <button class=\"sdr__close\" type=\"button\" data-storelib-search-close>{{ settings.close_label }}</button>\n      </div>\n      <div class=\"sdr__idle\">\n        {% if section.blocks.size > 0 %}\n        <div>\n          <p class=\"sdr__h\">{{ settings.suggest_heading }}</p>\n          <ul class=\"sdr__sugg\">{% for block in section.blocks %}<li data-block-id=\"{{ block.id }}\"><a href=\"{{ routes.search_url }}?q={{ block.settings.term }}\"><span class=\"sdr__arrow\" aria-hidden=\"true\"></span>{{ block.settings.term }}</a></li>{% endfor %}</ul>\n        </div>\n        {% endif %}\n        {% if settings.quick_links.links.size > 0 %}\n        <div>\n          <p class=\"sdr__h\">{{ settings.links_heading }}</p>\n          <ul class=\"sdr__quick\">{% for link in settings.quick_links.links limit: 6 %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul>\n        </div>\n        {% endif %}\n      </div>\n      <p class=\"sdr__state\" data-storelib-search-loading hidden>{{ settings.loading_text }}</p>\n      <p class=\"sdr__state\" data-storelib-search-empty hidden>{{ settings.empty_text }}</p>\n      <ul class=\"sdr__results\" data-storelib-search-results aria-live=\"polite\">\n        <li data-storelib-search-result hidden><a class=\"sdr__hit\" data-result-url><img data-result-image alt=\"\" width=\"48\" height=\"60\"><span class=\"sdr__hit-main\"><span class=\"sdr__hit-t\" data-result-title></span><span class=\"sdr__hit-k\" data-result-kind></span></span><span class=\"sdr__hit-p\" data-result-price></span></a></li>\n      </ul>\n      <a class=\"sdr__all\" href=\"{{ routes.search_url }}\">{{ settings.all_label }}</a>\n    </div>\n  </div>\n</div>\n</template>\n\n<style scoped>\n.sdr, .sdr *, .sdr *::before, .sdr *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.sdr [hidden] { display: none !important; }\n.sdr__panel { position: fixed; inset: 0; z-index: 90; visibility: hidden; }\n.sdr__panel[data-open=\"true\"], .sdr[data-editor-open] .sdr__panel { visibility: visible; }\n.sdr[data-editor-open] .sdr__panel { position: relative; min-height: 560px; }\n.sdr__scrim { position: absolute; inset: 0; width: 100%; padding: 0; border: 0; background: rgba(0, 0, 0, var(--sdr-dim, 0.35)); opacity: 0; cursor: pointer; }\n.sdr__panel[data-open=\"true\"] .sdr__scrim, .sdr[data-editor-open] .sdr__scrim { opacity: 1; }\n.sdr__box { position: absolute; inset: 0 0 auto; display: grid; gap: 16px; max-height: 100svh; padding: 12px var(--theme-padding-x, 16px) 20px; overflow-y: auto; overscroll-behavior: contain; background: var(--s-bg); color: var(--s-text); border-bottom: 1px solid var(--s-border); opacity: 0; }\n.sdr__panel[data-open=\"true\"] .sdr__box, .sdr[data-editor-open] .sdr__box { opacity: 1; transform: none; }\n.sdr__field { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px; min-height: 52px; padding: 0 4px 0 14px; border: 1.5px solid var(--s-text); border-radius: 4px; }\n.sdr__input { min-width: 0; min-height: 48px; padding: 0; border: 0; background: none; color: inherit; font: inherit; font-size: 1.125rem; }\n.sdr__input:focus-visible { outline-offset: 10px; }\n.sdr__close { min-height: 44px; padding: 0 12px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }\n.sdr__idle { display: grid; gap: 20px; }\n.sdr__panel:not([data-state=\"idle\"]) .sdr__idle { display: none; }\n.sdr__panel[data-state=\"idle\"] .sdr__all { display: none; }\n.sdr__h { margin: 0 0 6px; font-size: 0.875rem; font-weight: 600; }\n.sdr__sugg, .sdr__quick, .sdr__results { margin: 0; padding: 0; list-style: none; }\n.sdr__sugg a { display: flex; align-items: center; gap: 12px; min-height: 44px; color: inherit; text-decoration: none; font-size: 1.0625rem; }\n.sdr__sugg a:hover { color: var(--s-accent); }\n.sdr__arrow { width: 8px; height: 8px; border-top: 1.5px solid currentColor; border-right: 1.5px solid currentColor; transform: rotate(45deg); }\n.sdr__quick { display: flex; flex-wrap: wrap; gap: 8px; }\n.sdr__quick a { display: inline-flex; align-items: center; min-height: 40px; padding: 0 12px; border: 1px solid var(--s-border); border-radius: 4px; color: inherit; text-decoration: none; font-size: 0.9375rem; }\n.sdr__hit { display: grid; grid-template-columns: 48px minmax(0, 1fr) auto; align-items: center; gap: 12px; min-height: 60px; padding: 6px 0; color: inherit; text-decoration: none; border-bottom: 1px solid var(--s-border); }\n.sdr__hit:hover .sdr__hit-t { text-decoration: underline; }\n.sdr__hit img { width: 48px; height: 60px; object-fit: cover; }\n.sdr__hit-main { display: grid; min-width: 0; }\n.sdr__hit-t { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }\n.sdr__hit-k { font-size: 0.8125rem; }\n.sdr__hit-p { font-variant-numeric: tabular-nums; }\n.sdr__state { margin: 0; }\n.sdr__all { justify-self: start; display: inline-flex; align-items: center; min-height: 44px; color: inherit; font-weight: 600; text-underline-offset: 4px; }\n.sdr :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  .sdr:not([data-motion=\"off\"]) .sdr__panel { transition: visibility 0s linear calc(var(--t-motion-duration, 650ms) * 0.5); }\n  .sdr:not([data-motion=\"off\"]) .sdr__panel[data-open=\"true\"] { transition-delay: 0s; }\n  .sdr:not([data-motion=\"off\"]) .sdr__box { transform: translateY(calc(-16px * var(--m-k, 1))); transition: opacity calc(var(--t-motion-duration, 650ms) * 0.4) ease, transform calc(var(--t-motion-duration, 650ms) * 0.5) var(--t-motion-ease, ease-out); }\n  .sdr:not([data-motion=\"off\"]) .sdr__scrim { transition: opacity calc(var(--t-motion-duration, 650ms) * 0.4) ease; }\n}\n@media (prefers-reduced-motion: reduce) { .sdr__panel, .sdr__box, .sdr__scrim { transition: none; transform: none; } }\n@media (min-width: 760px) {\n  .sdr__box { inset: var(--sdr-top, 72px) auto auto 50%; width: min(var(--sdr-w, 720px), calc(100% - 48px)); max-height: calc(100svh - var(--sdr-top, 72px) - 24px); margin-left: calc(min(var(--sdr-w, 720px), calc(100% - 48px)) / -2); padding: 16px 20px 20px; border: 1px solid var(--s-border); border-radius: 6px; }\n  .sdr__idle { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 32px; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_search_drop\",\n  \"name\": \"Drop down search\",\n  \"settings\": [\n    { \"type\": \"paragraph\", \"id\": \"about\", \"content\": \"Opens from every search button on the page. Keep it right after the header.\" },\n    { \"type\": \"checkbox\", \"id\": \"editor_open\", \"label\": \"Keep it open in the editor\", \"default\": false },\n    { \"type\": \"header\", \"id\": \"hdr_idle\", \"label\": \"Before anything is typed\" },\n    { \"type\": \"text\", \"id\": \"suggest_heading\", \"label\": \"Suggestions heading\", \"default\": \"Try\" },\n    { \"type\": \"text\", \"id\": \"links_heading\", \"label\": \"Quick links heading\", \"default\": \"Go to\" },\n    { \"type\": \"link_list\", \"id\": \"quick_links\", \"label\": \"Quick links\", \"default\": \"main-menu\" },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"range\", \"id\": \"top_offset\", \"label\": \"Space from the top on wide screens\", \"min\": 0, \"max\": 160, \"step\": 4, \"unit\": \"px\", \"default\": 72 },\n    { \"type\": \"range\", \"id\": \"width\", \"label\": \"Width on wide screens\", \"min\": 480, \"max\": 960, \"step\": 20, \"unit\": \"px\", \"default\": 720 },\n    { \"type\": \"range\", \"id\": \"dim\", \"label\": \"Page dimming\", \"min\": 0, \"max\": 0.8, \"step\": 0.05, \"default\": 0.35 },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"Label (read aloud)\", \"default\": \"Search\" },\n    { \"type\": \"text\", \"id\": \"placeholder\", \"label\": \"Hint in the field\", \"default\": \"Search products and pages\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"loading_text\", \"label\": \"While searching\", \"default\": \"Looking...\" },\n    { \"type\": \"text\", \"id\": \"empty_text\", \"label\": \"Nothing found\", \"default\": \"Nothing matches that yet.\" },\n    { \"type\": \"text\", \"id\": \"all_label\", \"label\": \"Link to every result\", \"default\": \"See every result\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"term\", \"name\": \"Suggestion\", \"limit\": 8, \"settings\": [\n      { \"type\": \"text\", \"id\": \"term\", \"label\": \"Words\", \"default\": \"Gift\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Drop down search\", \"blocks\": [\n    { \"type\": \"term\", \"settings\": { \"term\": \"New in\" } },\n    { \"type\": \"term\", \"settings\": { \"term\": \"Gift ideas\" } },\n    { \"type\": \"term\", \"settings\": { \"term\": \"Delivery\" } }\n  ] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_chrome_search_full.storelib",
  "source": "{# example\ntitle: Full screen search with live results as a picture grid\nsummary: Chrome kit search window, a section placed after the header: the site's own search panel (data-storelib-search-panel) that every search button opens. A huge input across the top; before anything is typed, popular searches (blocks, each a link to the search page for its words) and the creator's chosen products (product_list); as the visitor types, this store's products, pages and posts arrive live as a grid of picture cards with prices, with loading and nothing found states. Focus moves to the input and stays inside; Escape and the close button shut it; Enter opens the full results. Columns, card ratio, colours and motion are settings.\ntags: chrome kit, search, search panel, search overlay, full screen search, live search, instant search, predictive search, search results grid, popular searches, own chrome\n#}\n<template>\n<div class=\"sfs\" data-ratio=\"{{ settings.card_ratio }}\" data-motion=\"{{ settings.motion }}\" {% if page.in_editor and settings.editor_open %}data-editor-open{% endif %} data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --sfs-cols: {{ settings.columns }}; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"sfs__panel\" data-storelib-search-panel role=\"dialog\" aria-label=\"{{ settings.label }}\">\n    <div class=\"sfs__in\">\n      <div class=\"sfs__bar\">\n        <label class=\"sfs__label\" for=\"sfs-{{ section.id }}\">{{ settings.label }}</label>\n        <input class=\"sfs__input\" id=\"sfs-{{ section.id }}\" type=\"search\" autocomplete=\"off\" enterkeyhint=\"search\" data-storelib-search-input placeholder=\"{{ settings.placeholder }}\">\n        <button class=\"sfs__close\" type=\"button\" data-storelib-search-close>{{ settings.close_label }}</button>\n      </div>\n      <div class=\"sfs__idle\">\n        {% if section.blocks.size > 0 %}\n        <div class=\"sfs__popular\">\n          <p class=\"sfs__h\">{{ settings.popular_heading }}</p>\n          <ul class=\"sfs__terms\">{% for block in section.blocks %}<li data-block-id=\"{{ block.id }}\"><a href=\"{{ routes.search_url }}?q={{ block.settings.term }}\">{{ block.settings.term }}</a></li>{% endfor %}</ul>\n        </div>\n        {% endif %}\n        {% if settings.featured.size > 0 %}\n        <div class=\"sfs__featured\">\n          <p class=\"sfs__h\">{{ settings.featured_heading }}</p>\n          <ul class=\"sfs__grid\">\n            {% for p in settings.featured %}\n            <li><a class=\"sfs__card\" href=\"{{ p.settings.url | url }}\"><span class=\"sfs__crop\">{% if p.settings.image %}<img src=\"{{ p.settings.image | asset }}\" alt=\"{{ p.settings.title }}\" width=\"400\" height=\"500\" loading=\"lazy\">{% endif %}</span><span class=\"sfs__t\">{{ p.settings.title }}</span><span class=\"sfs__p\">{{ p.settings.price }}</span></a></li>\n            {% endfor %}\n          </ul>\n        </div>\n        {% endif %}\n      </div>\n      <p class=\"sfs__state\" data-storelib-search-loading hidden>{{ settings.loading_text }}</p>\n      <p class=\"sfs__state sfs__none\" data-storelib-search-empty hidden>{{ settings.empty_text }}</p>\n      <ul class=\"sfs__grid sfs__results\" data-storelib-search-results aria-live=\"polite\">\n        <li data-storelib-search-result hidden><a class=\"sfs__card\" data-result-url><span class=\"sfs__crop\"><img data-result-image alt=\"\" width=\"400\" height=\"500\"></span><span class=\"sfs__kind\" data-result-kind></span><span class=\"sfs__t\" data-result-title></span><span class=\"sfs__p\" data-result-price></span></a></li>\n      </ul>\n    </div>\n  </div>\n</div>\n</template>\n\n<style scoped>\n.sfs, .sfs *, .sfs *::before, .sfs *::after { box-sizing: border-box; }\n/* The page hides and shows parts with the hidden attribute (a list with one choice, the empty cart, the copied patterns): it always wins over a display set here. */\n.sfs [hidden] { display: none !important; }\n.sfs__panel { position: fixed; inset: 0; z-index: 90; overflow-y: auto; overscroll-behavior: contain; background: var(--s-bg); color: var(--s-text); visibility: hidden; opacity: 0; }\n.sfs__panel[data-open=\"true\"], .sfs[data-editor-open] .sfs__panel { visibility: visible; opacity: 1; }\n.sfs[data-editor-open] .sfs__panel { position: relative; min-height: 640px; }\n.sfs__in { max-width: var(--theme-page-width, 1440px); margin: 0 auto; padding: 12px var(--theme-padding-x, 16px) 48px; }\n.sfs__bar { position: sticky; top: 0; z-index: 1; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 4px 12px; padding: 8px 0 12px; background: var(--s-bg); border-bottom: 2px solid var(--s-text); }\n.sfs__label { grid-column: 1 / -1; font-size: 0.875rem; }\n.sfs__input { min-width: 0; min-height: 56px; padding: 0; border: 0; background: none; color: var(--s-heading); font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.75rem, 1rem + 4vw, 4.5rem); line-height: 1; letter-spacing: -0.03em; font-weight: 700; }\n.sfs__input::placeholder { color: inherit; opacity: 0.35; }\n.sfs__input:focus-visible { outline-offset: 6px; }\n.sfs__bar:focus-within { border-bottom-color: var(--s-accent); }\n.sfs__close { min-height: 44px; padding: 0 14px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.sfs__idle { display: grid; gap: 32px; padding-top: 28px; }\n.sfs__panel:not([data-state=\"idle\"]) .sfs__idle { display: none; }\n.sfs__h { margin: 0 0 12px; font-weight: 600; }\n.sfs__terms { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; }\n.sfs__terms a { display: inline-flex; align-items: center; min-height: 44px; padding: 0 16px; border: 1px solid var(--s-border); color: inherit; text-decoration: none; font-size: 1.0625rem; }\n.sfs__terms a:hover { border-color: currentColor; }\n.sfs__grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px 12px; margin: 0; padding: 0; list-style: none; }\n.sfs__results { padding-top: 28px; }\n.sfs__card { display: grid; gap: 6px; color: inherit; text-decoration: none; }\n.sfs__crop { display: block; overflow: hidden; aspect-ratio: 4 / 5; background: color-mix(in srgb, var(--s-text) 6%, var(--s-bg)); }\n.sfs[data-ratio=\"square\"] .sfs__crop { aspect-ratio: 1; }\n.sfs__crop img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.sfs__crop img[hidden] { display: none; }\n.sfs__kind { font-size: 0.8125rem; }\n.sfs__results li[data-kind=\"product\"] .sfs__kind { display: none; }\n.sfs__results li:not([data-kind=\"product\"]) .sfs__crop:not(:has(img:not([hidden]))) { aspect-ratio: auto; height: 6px; background: var(--s-accent); }\n.sfs__t { font-weight: 600; }\n.sfs__p { font-variant-numeric: tabular-nums; }\n.sfs__state { margin: 28px 0 0; font-size: 1.125rem; }\n.sfs__none { font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.5rem); letter-spacing: -0.02em; color: var(--s-heading); }\n.sfs :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  .sfs:not([data-motion=\"off\"]) .sfs__panel { transform: translateY(calc(-12px * var(--m-k, 1))); transition: opacity calc(var(--t-motion-duration, 650ms) * 0.45) ease, transform calc(var(--t-motion-duration, 650ms) * 0.7) var(--t-motion-ease, ease-out), visibility 0s linear calc(var(--t-motion-duration, 650ms) * 0.7); }\n  .sfs:not([data-motion=\"off\"]) .sfs__panel[data-open=\"true\"] { transform: none; transition-delay: 0s; }\n  .sfs:not([data-motion=\"off\"]) .sfs__results li:not([hidden]) { animation: sfs-in calc(var(--t-motion-duration, 650ms) * 0.7) var(--t-motion-ease, ease-out) both; }\n  .sfs:not([data-motion=\"off\"]) .sfs__results li:nth-child(3n) { animation-delay: var(--t-motion-stagger, 65ms); }\n  .sfs:not([data-motion=\"off\"]) .sfs__results li:nth-child(3n + 1) { animation-delay: calc(var(--t-motion-stagger, 65ms) * 2); }\n  @keyframes sfs-in { from { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 0.6 * var(--m-k, 1))); } }\n}\n@media (prefers-reduced-motion: reduce) { .sfs__panel, .sfs__results li { transition: none; animation: none; transform: none; } }\n@media (min-width: 760px) {\n  .sfs__grid { grid-template-columns: repeat(var(--sfs-cols, 4), minmax(0, 1fr)); gap: 32px 20px; }\n  .sfs__idle { grid-template-columns: minmax(0, 4fr) minmax(0, 8fr); gap: 48px; }\n  .sfs__featured .sfs__grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_chrome_search_full\",\n  \"name\": \"Full screen search\",\n  \"settings\": [\n    { \"type\": \"paragraph\", \"id\": \"about\", \"content\": \"Opens from every search button on the page. Keep it right after the header.\" },\n    { \"type\": \"checkbox\", \"id\": \"editor_open\", \"label\": \"Keep it open in the editor\", \"default\": false },\n    { \"type\": \"header\", \"id\": \"hdr_idle\", \"label\": \"Before anything is typed\" },\n    { \"type\": \"text\", \"id\": \"popular_heading\", \"label\": \"Popular searches heading\", \"default\": \"People look for\" },\n    { \"type\": \"text\", \"id\": \"featured_heading\", \"label\": \"Products heading\", \"default\": \"Start here\" },\n    { \"type\": \"product_list\", \"id\": \"featured\", \"label\": \"Products\", \"limit\": 6 },\n    { \"type\": \"header\", \"id\": \"hdr_layout\", \"label\": \"Layout\" },\n    { \"type\": \"range\", \"id\": \"columns\", \"label\": \"Result columns on wide screens\", \"min\": 3, \"max\": 6, \"step\": 1, \"default\": 4 },\n    { \"type\": \"select\", \"id\": \"card_ratio\", \"label\": \"Pictures\", \"default\": \"portrait\", \"options\": [{ \"label\": \"Portrait\", \"value\": \"portrait\" }, { \"label\": \"Square\", \"value\": \"square\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_words\", \"label\": \"Words\" },\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"Label\", \"default\": \"Search\" },\n    { \"type\": \"text\", \"id\": \"placeholder\", \"label\": \"Hint in the field\", \"default\": \"What are you after?\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"loading_text\", \"label\": \"While searching\", \"default\": \"Looking...\" },\n    { \"type\": \"text\", \"id\": \"empty_text\", \"label\": \"Nothing found\", \"default\": \"Nothing matches that. Try a shorter word.\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"term\", \"name\": \"Popular search\", \"limit\": 10, \"settings\": [\n      { \"type\": \"text\", \"id\": \"term\", \"label\": \"Words\", \"default\": \"Gift\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Full screen search\", \"blocks\": [\n    { \"type\": \"term\", \"settings\": { \"term\": \"New in\" } },\n    { \"type\": \"term\", \"settings\": { \"term\": \"Gift\" } },\n    { \"type\": \"term\", \"settings\": { \"term\": \"Bestsellers\" } },\n    { \"type\": \"term\", \"settings\": { \"term\": \"Sale\" } }\n  ] }]\n}\n</schema>\n"
 }
]
